// Bai tap ngu phap hsk3v3 — soan rieng theo trinh do (sinh tu data-grammar/hsk3v3/).
window.GRAMMAR_EXTRA = Object.assign(window.GRAMMAR_EXTRA || {}, {"/lessons/hsk3v3-bai-1.html":[{"point":"Cụm từ cố định 「看上去 / 看起来」 — trông, có vẻ","items":[{"context":"“Trông họ hơi giống nhau.”","pre":"他们","blank":"看上去有点儿像","post":"。","options":["看上去有点儿像","看上来有点儿像","有点儿像看上去"],"answer":0,"explanation":"看上去 + 有点儿像; không có 看上来."},{"context":"“Mấy món này trông đều rất ngon.”","pre":"这些菜","blank":"看起来都很好吃","post":"。","options":["看起来都很好吃","都很好吃看起来","看都很好吃"],"answer":0,"explanation":"看起来 đứng trước phần miêu tả."},{"context":"“Thầy giáo mới đến kia trông rất trẻ.”","pre":"那个新来的老师","blank":"看上去很年轻","post":"。","options":["看上去很年轻","看很年轻","看上去年轻人"],"answer":0,"explanation":"看上去 + 很 + tính từ."},{"context":"Sách: “Trông bạn giống mẹ bạn hơn.” (ôn 更 – HSK2 Bài 4)","pre":"你","blank":"看起来","post":"长得更像你妈妈。","options":["看起来","看见","看到"],"answer":0,"explanation":"看起来 = nhận xét qua vẻ ngoài; 看见/看到 = nhìn thấy."},{"context":"Sách: “Trông bạn mệt lắm, nghỉ ngơi cho tốt đi.” (累 – HSK2 Bài 3)","pre":"你","blank":"看上去很累","post":"，好好休息一下吧。","options":["看上去很累","看上去累很","很累看上去"],"answer":0,"explanation":"很 đứng trước tính từ 累."},{"context":"Sách: “Bạn sao thế? Hôm nay trông bạn không vui lắm.”","pre":"你怎么了？今天","blank":"你看起来不太高兴","post":"。","options":["你看起来不太高兴","你看不太高兴","你不太高兴看起来"],"answer":0,"explanation":"看起来 + 不太 + tính từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他看很年轻。","isCorrect":false,"correctVersion":"他看上去很年轻。","explanation":"Phải dùng 看上去 / 看起来, không dùng 看 đơn thuần."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"看起来他比同乐瘦一点儿。","isCorrect":true,"explanation":"看起来 có thể đứng đầu câu, trước chủ ngữ — đúng. Kết hợp câu so sánh 比 (HSK2 Bài 8)."},{"type":"sort","context":"Sắp xếp: “Trông họ hơi giống nhau.”","words":["他们","看上去","有点儿","像","。"],"answer":"他们看上去有点儿像。","explanation":"看上去 + 有点儿 + 像."},{"type":"sort","context":"Sắp xếp: “Mấy món này trông đều rất ngon.”","words":["这些","菜","看起来","都","很","好吃","。"],"answer":"这些菜看起来都很好吃。","explanation":"都 đứng sau 看起来, trước 很好吃."},{"type":"sort","context":"Sắp xếp: “Chị ấy trông trẻ hơn so với trong ảnh.”","words":["她","看起来","比","照片","上","年轻","。"],"answer":"她看起来比照片上年轻。","explanation":"看起来 + 比 + 照片上 + 年轻."},{"type":"sort","context":"Sắp xếp: “Mẹ bạn trông rất trẻ.”","words":["你","妈妈","看上去","很","年轻","。"],"answer":"你妈妈看上去很年轻。","explanation":"看上去 + 很年轻."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 看起来.","promptLang":"vi","prompt":"Hôm nay trông bạn rất vui.","answer":"你今天看起来很高兴。","answerPy":"Nǐ jīntiān kàn qǐlai hěn gāoxìng.","explanation":"Thời gian 今天 đứng trước 看起来."}]},{"point":"Đại từ nghi vấn không dùng để hỏi (1) — 哪儿 / 什么 / 谁 / 哪","items":[{"context":"Sách (谁): “Mình cũng không biết, để mình đi hỏi ai đó xem.”","pre":"我们是不是走错了？——我也不知道，我去","blank":"找谁问问","post":"。","options":["找谁问问","问问谁找","谁找问问"],"answer":0,"explanation":"谁 = “ai đó”; 找 + 谁 + 问问."},{"context":"Sách (什么): “Lúc nào rảnh đến nhà mình, mình làm món gì đó cho bạn ăn.”","pre":"你有时间了来我家，我","blank":"做点儿什么","post":"给你吃。","options":["做点儿什么","什么做点儿","做什么点儿"],"answer":0,"explanation":"V + 点儿 + 什么 = làm chút gì đó."},{"context":"Sách (哪儿): “Mấy hôm nay mệt quá, mình muốn đi đâu đó chơi.”","pre":"这几天太累了，我想","blank":"去哪儿玩儿玩儿","post":"。——那你去西安吧。","options":["去哪儿玩儿玩儿","哪儿去玩儿玩儿","玩儿玩儿去哪儿"],"answer":0,"explanation":"去 + 哪儿 = đi đâu đó; câu trần thuật, không phải câu hỏi."},{"context":"“Bạn ăn chút gì đó rồi hẵng đi.”","pre":"你","blank":"吃点儿什么","post":"再走吧。","options":["吃点儿什么","什么吃点儿","吃什么点儿"],"answer":0,"explanation":"什么 = “cái gì đó”, đứng sau động từ như tân ngữ."},{"context":"“Hôm nào đó chúng ta cùng đi đá bóng nhé.” (踢足球 – HSK2 Bài 7)","pre":"我们","blank":"哪天","post":"一起去踢足球吧。","options":["哪天","哪儿天","什么天"],"answer":0,"explanation":"哪天 = hôm nào đó (thời gian)."},{"context":"“Hình như anh đã thấy cái va li này ở đâu đó rồi.”","pre":"我好像","blank":"在哪儿看到过","post":"这个箱子。","options":["在哪儿看到过","看到过在哪儿","哪儿在看到过"],"answer":0,"explanation":"在哪儿 đứng trước động từ; V + 过 (ôn HSK2 Bài 4)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们哪儿天一起去踢足球吧。","isCorrect":false,"correctVersion":"我们哪天一起去踢足球吧。","explanation":"“Hôm nào đó” là 哪天, không phải 哪儿天."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们快找谁问一下吧。","isCorrect":true,"explanation":"谁 ở đây = “ai đó”, không phải câu hỏi — đúng."},{"type":"sort","context":"Sắp xếp: “Hình như tôi đã gặp anh ấy ở đâu đó rồi.”","words":["我","好像","在哪儿","见过","他","。"],"answer":"我好像在哪儿见过他。","explanation":"好像 + 在哪儿 + 见过."},{"type":"sort","context":"Sắp xếp: “Bạn ăn chút gì đó rồi hẵng đi.”","words":["你","吃","点儿","什么","再","走","吧","。"],"answer":"你吃点儿什么再走吧。","explanation":"吃点儿什么 + 再走."},{"type":"sort","context":"Sắp xếp: “Hôm nào đó chúng ta cùng đi đá bóng nhé.”","words":["我们","哪天","一起","去","踢","足球","吧","。"],"answer":"我们哪天一起去踢足球吧。","explanation":"哪天 + 一起 + 去 + V."},{"type":"sort","context":"Sắp xếp: “Chúng ta mau tìm ai đó hỏi một chút đi.”","words":["我们","快","找","谁","问","一下","吧","。"],"answer":"我们快找谁问一下吧。","explanation":"找谁问一下 = tìm ai đó hỏi."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 什么 (không phải câu hỏi).","promptLang":"vi","prompt":"Tôi muốn mua cái gì đó cho mẹ.","answer":"我想给妈妈买点儿什么。","answerPy":"Wǒ xiǎng gěi māma mǎi diǎnr shénme.","explanation":"给 + người + V (HSK2 Bài 1) + 点儿什么."}]},{"point":"Định ngữ đa tầng (多项定语)","items":[{"context":"“Lý Văn có phải là chàng trai tóc ngắn, mặc đồ đen kia không?”","pre":"李文是","blank":"那个穿着黑衣服的短头发的年轻人","post":"吗？","options":["那个穿着黑衣服的短头发的年轻人","年轻人那个穿着黑衣服的短头发的","那个年轻人穿着黑衣服短头发"],"answer":0,"explanation":"Trạng thái (穿着黑衣服的) → đặc điểm (短头发的) → danh từ."},{"context":"“Hai người hôm qua đi xem phim cùng Gia Nguyệt là bạn tôi.”","pre":"","blank":"昨天和家月一起看电影的两个人","post":"是我的朋友。","options":["昨天和家月一起看电影的两个人","两个人昨天和家月一起看电影","和家月一起看电影昨天的两个人"],"answer":0,"explanation":"Thời gian (昨天) → hành động (……看电影的) → số lượng → danh từ."},{"context":"“Chiếc áo trắng mới mua của mình đâu rồi?”","pre":"我","blank":"那件新买的白色的衣服","post":"在哪儿？","options":["那件新买的白色的衣服","衣服那件新买的白色的","那件衣服新买的白色"],"answer":0,"explanation":"Chỉ lượng (那件) → hành động (新买的) → đặc điểm (白色的) → 衣服."},{"context":"Sách: “Cuốn sách mua ở hiệu sách hôm qua là cuốn mình thích nhất.”","pre":"那本","blank":"昨天在书店买","post":"的书是我最喜欢的。","options":["昨天在书店买","买昨天在书店","在书店买昨天"],"answer":0,"explanation":"Thời gian → nơi chốn → động từ + 的."},{"context":"Sách: “Người nào là bạn trai bạn?” — “Người cao cao đứng ở cửa kia.”","pre":"哪个人是你男朋友？——","blank":"站在门口的那个高个子","post":"。","options":["站在门口的那个高个子","那个高个子站在门口的","门口站在的那个高个子"],"answer":0,"explanation":"Cụm chỉ lượng (那个) có thể đứng SAU định ngữ chỉ hành động."},{"context":"Sách: “Lớp các bạn học ở toà nhà nào?” — “Sau toà nhà màu trắng cạnh siêu thị.”","pre":"你们上课的楼在哪儿？——在","blank":"超市旁边那个白色","post":"的楼后面。","options":["超市旁边那个白色","白色的那个超市旁边","旁边超市白色那个"],"answer":0,"explanation":"Nơi chốn (超市旁边) → chỉ lượng (那个) → đặc điểm (白色的) → 楼."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"昨天和家月一起看电影两个人是我的朋友。","isCorrect":false,"correctVersion":"昨天和家月一起看电影的两个人是我的朋友。","explanation":"Thiếu 的 sau cụm động từ làm định ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我那件新买的白色的衣服在哪儿？","isCorrect":true,"explanation":"Đúng trật tự: chỉ lượng → hành động → đặc điểm → danh từ."},{"type":"sort","context":"Sắp xếp: “Lý Văn là chàng trai tóc ngắn, mặc đồ đen kia.”","words":["李文","是","那个","穿着","黑衣服","的","短头发","的","年轻人","。"],"answer":"李文是那个穿着黑衣服的短头发的年轻人。","explanation":"Mọi định ngữ đứng trước 年轻人."},{"type":"sort","context":"Sắp xếp: “Chiếc áo trắng mới mua của mình đâu rồi?”","words":["我","那件","新买","的","白色","的","衣服","在","哪儿","？"],"answer":"我那件新买的白色的衣服在哪儿？","explanation":"新买的 → 白色的 → 衣服."},{"type":"sort","context":"Sắp xếp: “Người cao cao đứng ở cửa kia là anh trai tôi.”","words":["站","在","门口","的","那个","高个子","是","我","哥哥","。"],"answer":"站在门口的那个高个子是我哥哥。","explanation":"Cụm 站在门口的 làm định ngữ."},{"type":"sort","context":"Sắp xếp: “Hai người bạn Trung Quốc đến hôm qua đều rất trẻ.”","words":["昨天","来","的","两个","中国","朋友","都","很","年轻","。"],"answer":"昨天来的两个中国朋友都很年轻。","explanation":"昨天来的 → 两个 → 中国 → 朋友."},{"type":"translate","context":"Dịch sang tiếng Trung, đặt mọi định ngữ trước danh từ.","promptLang":"vi","prompt":"Cô gái tóc dài đứng ở giữa kia là em gái tôi.","answer":"那个站在中间的长头发的女孩儿是我妹妹。","answerPy":"Nà ge zhàn zài zhōngjiān de cháng tóufa de nǚháir shì wǒ mèimei.","explanation":"Chỉ lượng → hành động (站在中间的) → đặc điểm (长头发的) → 女孩儿."}]}],"/lessons/hsk3v3-bai-10.html":[{"point":"Câu chữ 「把」 (1) — 把 + tân ngữ + V + 在/到 + địa điểm","items":[{"context":"Sách: “Hình như mình để quên thẻ sinh viên ở nhà rồi.” (忘 – ôn HSK2 Bài 6)","pre":"我好像把校园卡","blank":"忘在家里了","post":"。","options":["忘在家里了","忘家里了在","在家里忘了"],"answer":0,"explanation":"把 + O + V + 在 + nơi chốn; 好像 (ôn HSK3 Bài 1)."},{"context":"Sách: “Tài xế đã đặt hành lý của chúng tôi lên xe.” (司机 – ôn HSK3 Bài 4)","pre":"司机把我们的行李","blank":"放到车上了","post":"。","options":["放到车上了","放车上到了","到车上放了"],"answer":0,"explanation":"V + 到 + nơi chốn: vật chuyển đến chỗ mới; 行李 (ôn HSK3 Bài 1)."},{"context":"Sách: “Đến lúc soát vé tôi mới phát hiện mình không để hộ chiếu trong túi.”","pre":"检票的时候我才发现，没把护照","blank":"放在包里","post":"。","options":["放在包里","包里放在","放包里"],"answer":0,"explanation":"没 đứng trước 把; 才 (ôn HSK3 Bài 3), 发现 (ôn HSK3 Bài 1)."},{"context":"“Mình sẽ ghi hết những bài này vào vở.”","pre":"我","blank":"会把这些题","post":"都记在本子上。","options":["会把这些题","把这些题会","把会这些题"],"answer":0,"explanation":"Động từ năng nguyện 会 đứng trước 把."},{"context":"“Bạn không được viết tên ở đây.”","pre":"你","blank":"不能把名字","post":"写在这里。","options":["不能把名字","把名字不能","把不能名字"],"answer":0,"explanation":"不能 đứng trước 把."},{"context":"“Cô giáo đặt vở bài tập lên bàn rồi.”","pre":"老师把作业本","blank":"放到","post":"桌子上了。","options":["放到","放","放给"],"answer":0,"explanation":"Động từ + 到 + nơi chốn; không dùng 放 trơn, cũng không dùng 给 (给 chỉ người nhận)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我放书在桌子上。","isCorrect":false,"correctVersion":"我把书放在桌子上。","explanation":"Muốn nói vật đổi vị trí phải dùng câu chữ 把."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"妈妈把蛋糕放到冰箱里了。","isCorrect":true,"explanation":"Đúng: 把 + 蛋糕 + 放到 + 冰箱里. 蛋糕 (ôn HSK2 Bài 6), 冰箱 (ôn HSK3 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Mình sẽ ghi hết những bài này vào vở.”","words":["我","会","把","这些","题","都","记在","本子上","。"],"answer":"我会把这些题都记在本子上。","explanation":"会 + 把 + O + 都 + 记在 + nơi chốn."},{"type":"sort","context":"Sắp xếp: “Bạn không được viết tên ở đây.”","words":["你","不能","把","名字","写在","这里","。"],"answer":"你不能把名字写在这里。","explanation":"不能 + 把 + O + 写在 + nơi chốn."},{"type":"sort","context":"Sắp xếp: “Cô giáo đặt vở bài tập lên bàn rồi.”","words":["老师","把","作业本","放到","桌子上","了","。"],"answer":"老师把作业本放到桌子上了。","explanation":"把 + 作业本 + 放到 + 桌子上 + 了."},{"type":"sort","context":"Sắp xếp: “Hãy để va li của bạn ở cửa.”","words":["请","把","你的","箱子","放在","门口","。"],"answer":"请把你的箱子放在门口。","explanation":"箱子 (ôn HSK3 Bài 1), 门口 (ôn HSK2 Bài 9)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 把.","promptLang":"vi","prompt":"Đừng để điện thoại trên giường.","answer":"别把手机放在床上。","answerPy":"Bié bǎ shǒujī fàng zài chuáng shang.","explanation":"别 đứng trước 把 (ôn HSK2 Bài 2); 床 (ôn HSK2 Bài 6)."}]},{"point":"Cấu trúc cố định 「在……上 / 中 / 下」","items":[{"context":"Sách: “Do ảnh hưởng của bố, tôi và em trai đều có hứng thú với bóng đá.”","pre":"在","blank":"爸爸的影响下","post":"，我和弟弟都对足球感兴趣了。","options":["爸爸的影响下","下爸爸的影响","爸爸下的影响"],"answer":0,"explanation":"在 + định ngữ + 影响 + 下 = điều kiện; 对……感兴趣 (ôn HSK3 Bài 5)."},{"context":"Sách: “Trong cuộc sống tôi giúp cô ấy; trong việc học cô ấy giúp tôi.”","pre":"在生活上，我帮助她；","blank":"在学习上","post":"，她帮助我。","options":["在学习上","在学习下","在学习里"],"answer":0,"explanation":"Phương diện → 在……上; 帮助 (ôn HSK3 Bài 1)."},{"context":"Sách: “Anh ấy rất nhiệt tình, nhờ có anh ấy giúp đỡ, chúng tôi chơi rất vui.”","pre":"他非常热情，","blank":"在他的帮助下","post":"，我们玩得很开心。","options":["在他的帮助下","在他的帮助上","在下他的帮助"],"answer":0,"explanation":"Điều kiện → 在……的帮助下; 热情 (ôn HSK3 Bài 2)."},{"context":"“Trong trận đấu, anh ấy ghi điểm cao nhất.”","pre":"","blank":"在比赛中","post":"，他得分最高。","options":["在比赛中","在比赛下","比赛在中"],"answer":0,"explanation":"Môi trường xảy ra hành động → 在……中; 最 (ôn HSK2 Bài 11)."},{"context":"“Trong kỳ nghỉ, tôi đã quen mấy người bạn mới.” (假期 – ôn HSK3 Bài 4)","pre":"在","blank":"假期中","post":"，我认识了几个新朋友。","options":["假期中","假期下","中假期"],"answer":0,"explanation":"Thời gian → 在……中."},{"context":"“Trong công việc, anh ấy luôn giúp đỡ tôi rất nhiều.”","pre":"","blank":"在工作上","post":"，他总是能给我很多帮助。","options":["在工作上","在工作下","在上工作"],"answer":0,"explanation":"Phương diện → 在……上; 总是 (ôn HSK3 Bài 5)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在老师的下帮助，我的成绩提高很快。","isCorrect":false,"correctVersion":"在老师的帮助下，我的成绩提高很快。","explanation":"下 phải đứng cuối cụm: 在 + 老师的帮助 + 下."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在学习上，遇到什么问题都可以问我。","isCorrect":true,"explanation":"Đúng: 在学习上 = về mặt học tập; 什么……都…… (ôn HSK3 Bài 2)."},{"type":"sort","context":"Sắp xếp: “Nhờ sự giúp đỡ của thầy cô, thành tích của tôi tiến bộ rất nhanh.”","words":["在","老师的","帮助","下","，","我的","成绩","提高","很快","。"],"answer":"在老师的帮助下，我的成绩提高很快。","explanation":"在 + 老师的帮助 + 下 đứng đầu câu."},{"type":"sort","context":"Sắp xếp: “Trong việc học, gặp vấn đề gì cũng có thể hỏi mình.”","words":["在","学习","上","，","遇到","什么","问题","都","可以","问我","。"],"answer":"在学习上，遇到什么问题都可以问我。","explanation":"在学习上 + 遇到什么问题都……."},{"type":"sort","context":"Sắp xếp: “Do ảnh hưởng của cô ấy, tôi bắt đầu thích chụp ảnh.”","words":["在","她的","影响","下","，","我","开始","喜欢","拍照","。"],"answer":"在她的影响下，我开始喜欢拍照。","explanation":"开始 (ôn HSK2 Bài 7), 拍照 (ôn HSK3 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Trong kỳ nghỉ, tôi đã quen mấy người bạn mới.”","words":["在","假期","中","，","我","认识了","几个","新","朋友","。"],"answer":"在假期中，我认识了几个新朋友。","explanation":"在 + 假期 + 中."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 在……下.","promptLang":"vi","prompt":"Nhờ sự giúp đỡ của mọi người, cuối cùng tôi cũng tìm được va li.","answer":"在大家的帮助下，我终于找到了行李箱。","answerPy":"Zài dàjiā de bāngzhù xià, wǒ zhōngyú zhǎodàole xínglixiāng.","explanation":"终于 (ôn HSK3 Bài 5); 行李箱 (ôn HSK3 Bài 1)."}]},{"point":"Câu chữ 「把」 (2) — 把 + tân ngữ₁ + V + 给 + tân ngữ₂","items":[{"context":"Sách: “Tôi muốn đem những đồ ăn này biếu bà.” (奶奶 – ôn HSK2 Bài 5)","pre":"我想把这些吃的","blank":"送给奶奶","post":"。","options":["送给奶奶","给奶奶送","送奶奶给"],"answer":0,"explanation":"把 + O + 送给 + người; 想 đứng trước 把."},{"context":"Sách: “Mình đã đưa vở ghi bài hôm nay cho bạn cùng lớp rồi.”","pre":"我把今天上课的笔记","blank":"拿给同学了","post":"。","options":["拿给同学了","给同学拿了","拿同学给了"],"answer":0,"explanation":"拿 (ôn HSK2 Bài 3) + 给 + người."},{"context":"Sách: “Hôm nay là sinh nhật mẹ, tôi muốn tặng những bông hoa này cho mẹ.”","pre":"今天是妈妈的生日，我要把这些花","blank":"送给妈妈","post":"。","options":["送给妈妈","给妈妈送","送妈妈给"],"answer":0,"explanation":"生日 (ôn HSK2 Bài 6); 把 + 这些花 + 送给 + người."},{"context":"“Ngày mai em trả lại sách cho cô nhé.”","pre":"你明天再把书","blank":"还给","post":"我。","options":["还给","给还","还"],"answer":0,"explanation":"还 huán (ôn HSK3 Bài 3) + 给 + người."},{"context":"“Bạn mang cuốn sách này cho thầy giáo giúp mình nhé.”","pre":"请你","blank":"把这本书带给","post":"老师。","options":["把这本书带给","带给把这本书","把带给这本书"],"answer":0,"explanation":"带 (ôn HSK3 Bài 1) + 给 + người."},{"context":"“Tôi đã tặng quà cho cô ấy rồi.”","pre":"我","blank":"把礼物送给她","post":"了。","options":["把礼物送给她","把她送给礼物","送给她把礼物"],"answer":0,"explanation":"Vật (礼物) đứng sau 把, người (她) đứng sau 给; 礼物 (ôn HSK2 Bài 5)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你明天再把书还我给。","isCorrect":false,"correctVersion":"你明天再把书还给我。","explanation":"给 đứng ngay sau động từ: 还给我."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把那个红色的箱子送给妹妹了。","isCorrect":true,"explanation":"Đúng: tân ngữ xác định (那个红色的箱子) + 送给 + người. 红色 (ôn HSK2 Bài 4)."},{"type":"sort","context":"Sắp xếp: “Ngày mai em trả lại sách cho cô nhé.”","words":["你","明天","再","把","书","还给","我","。"],"answer":"你明天再把书还给我。","explanation":"再 đứng trước 把."},{"type":"sort","context":"Sắp xếp: “Tôi đã tặng quà cho cô ấy rồi.”","words":["我","把","礼物","送给","她","了","。"],"answer":"我把礼物送给她了。","explanation":"把 + 礼物 + 送给 + 她 + 了."},{"type":"sort","context":"Sắp xếp: “Bạn mang cuốn sách này cho thầy giáo giúp mình nhé.”","words":["请","你","把","这本书","带给","老师","。"],"answer":"请你把这本书带给老师。","explanation":"请 + người + 把…… (ôn HSK2 Bài 1)."},{"type":"sort","context":"Sắp xếp: “Tôi đã đưa vở bài tập cho cô giáo rồi.”","words":["我","已经","把","作业本","拿给","老师","了","。"],"answer":"我已经把作业本拿给老师了。","explanation":"已经 đứng trước 把; 已经……了 (ôn HSK2 Bài 1)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 把 (2).","promptLang":"vi","prompt":"Bạn trả điện thoại lại cho tôi đi.","answer":"你把手机还给我吧。","answerPy":"Nǐ bǎ shǒujī huán gěi wǒ ba.","explanation":"把 + 手机 + 还给 + 我; 吧 đề nghị."}]}],"/lessons/hsk3v3-bai-11.html":[{"point":"「还是」 và 「或者」 — hỏi để chọn / nêu khả năng","items":[{"context":"Sách: “A: Bữa tối hôm nay bạn muốn ăn gì? B: Tôi muốn ăn sủi cảo hoặc mì.”","pre":"今天的晚饭我想吃饺子","blank":"或者","post":"面条儿。","options":["或者","还是","都"],"answer":0,"explanation":"Câu trần thuật nêu khả năng → 或者; 饺子、面条儿 (ôn HSK1 Bài 5)."},{"context":"Sách: “A: Kỳ nghỉ tuần sau bạn có dự định gì? B: Tôi muốn đi Tây An hoặc Bắc Kinh du lịch.”","pre":"我想去西安","blank":"或者","post":"北京旅游。","options":["或者","还是","吗"],"answer":0,"explanation":"Câu trần thuật → 或者; 打算 (ôn HSK3 Bài 6), 旅游 (ôn HSK2 Bài 1)."},{"context":"Sách: “A: …? B: Là ngày mai, 2 giờ chiều ở Phòng họp số 1.” (A hỏi họp ngày mai hay ngày kia)","pre":"会议是明天","blank":"还是","post":"后天？","options":["还是","或者","或"],"answer":0,"explanation":"Câu hỏi để người nghe chọn → 还是; B trả lời 是明天."},{"context":"“Chúng ta dùng máy tính của phòng họp hay máy tính xách tay của mình?”","pre":"我们用会议室的电脑","blank":"还是","post":"自己的笔记本电脑？","options":["还是","或者","或"],"answer":0,"explanation":"Câu hỏi lựa chọn → 还是 (ôn HSK2 Bài 2)."},{"context":"“Bạn có thể đi tàu điện ngầm hoặc bắt taxi đến trường.”","pre":"你可以坐地铁","blank":"或者","post":"打车去学校。","options":["或者","还是","跟"],"answer":0,"explanation":"Câu trần thuật → 或者; 地铁 (ôn HSK2 Bài 12), 打车 (ôn HSK2 Bài 2)."},{"context":"“Bạn đi một mình hay đi với bạn bè?”","pre":"你一个人去","blank":"还是","post":"跟朋友一起去？","options":["还是","或者","也"],"answer":0,"explanation":"还是 nối hai cụm động từ trong câu hỏi; 跟……一起 (ôn HSK2 Bài 5)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你喝茶或者咖啡？","isCorrect":false,"correctVersion":"你喝茶还是咖啡？","explanation":"Câu hỏi lựa chọn phải dùng 还是."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"星期六或者星期天我都有时间。","isCorrect":true,"explanation":"Đúng: câu trần thuật, A 或者 B + 都."},{"type":"sort","context":"Sắp xếp: “Chúng ta đi hôm nay, ngày mai hay ngày kia?”","words":["我们","今天去","、","明天去","还是","后天去","？"],"answer":"我们今天去、明天去还是后天去？","explanation":"Câu hỏi nhiều phương án: A、B 还是 C？"},{"type":"sort","context":"Sắp xếp: “Máy tính của phòng họp hoặc máy tính của mình đều được.”","words":["会议室的电脑","或者","自己的电脑","都","可以","。"],"answer":"会议室的电脑或者自己的电脑都可以。","explanation":"A 或者 B + 都可以."},{"type":"sort","context":"Sắp xếp: “Bạn muốn đi xem phim hay ở nhà nghỉ ngơi?”","words":["你","想","去看电影","还是","在家","休息","？"],"answer":"你想去看电影还是在家休息？","explanation":"还是 nối hai cụm động từ; 休息 (ôn HSK1 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Bạn có thể gọi điện hoặc gửi email cho tôi.”","words":["你","可以","给我","打电话","或者","发邮件","。"],"answer":"你可以给我打电话或者发邮件。","explanation":"给 + người + V (ôn HSK2 Bài 1); câu trần thuật → 或者."},{"type":"translate","context":"Dịch sang tiếng Trung, chú ý chọn 还是 / 或者.","promptLang":"vi","prompt":"Bạn muốn mua cái màu đỏ hay cái màu trắng?","answer":"你想买红色的还是白色的？","answerPy":"Nǐ xiǎng mǎi hóngsè de háishi báisè de?","explanation":"Câu hỏi → 还是; 红色、白色 (ôn HSK2 Bài 4)."}]},{"point":"Cụm từ cố định 「看来」 — xem ra (suy đoán, kết luận)","items":[{"context":"Sách: “Bây giờ bên ngoài trời âm u lắm, …” (得很 – ôn HSK3 Bài 5)","pre":"现在外面天阴得很，","blank":"看来要下雨了","post":"。","options":["看来要下雨了","看来要下雨吗","看起来下雨了吗"],"answer":0,"explanation":"看来 + suy đoán; 要……了 — sắp (ôn HSK2 Bài 10); 阴 (ôn HSK2 Bài 12)."},{"context":"Sách: “Dạo này anh ấy bận quá, …”","pre":"他最近工作太忙了，","blank":"看来没时间跟我们去旅游了","post":"。","options":["看来没时间跟我们去旅游了","看来有时间跟我们去旅游吗","看起来他去旅游了"],"answer":0,"explanation":"Kết luận hợp lý từ tình hình “quá bận”; 最近 (ôn HSK3 Bài 8)."},{"context":"Sách: “Anh ấy mãi không nghe điện thoại, …”","pre":"他一直没接电话，","blank":"看来在开会呢","post":"。","options":["看来在开会呢","看来接电话了","看起来很高"],"answer":0,"explanation":"Suy đoán lý do: đang họp; 一直 (ôn HSK3 Bài 4), 在……呢 (ôn HSK1 Bài 11)."},{"context":"“Muộn thế này rồi, xem ra hôm nay anh ấy sẽ không đến nữa.”","pre":"这么晚了，","blank":"看来","post":"他今天不会来了。","options":["看来","看起来","看见"],"answer":0,"explanation":"看来 đứng đầu mệnh đề, rút ra kết luận."},{"context":"“Thang máy hỏng rồi, xem ra chúng ta chỉ có thể đi bộ xuống.”","pre":"电梯坏了，看来咱们","blank":"只能","post":"走下去了。","options":["只能","愿意","怕"],"answer":0,"explanation":"只能 + V; 电梯 (ôn HSK3 Bài 6), 坏 (ôn HSK2 Bài 9)."},{"context":"“Cô ấy cứ cười suốt, xem ra rất vui.”","pre":"她一直在笑，","blank":"看来","post":"很开心。","options":["看来","来看","看见"],"answer":0,"explanation":"笑 (ôn HSK2 Bài 10), 开心 (ôn HSK3 Bài 8)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我看来他今天不会来了。","isCorrect":false,"correctVersion":"看来他今天不会来了。","explanation":"Không nói 我看来; dùng 看来 đứng đầu mệnh đề."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"已经十点了，看来他已经睡觉了。","isCorrect":true,"explanation":"Đúng: tình hình (已经十点了) → kết luận với 看来; 已经……了 (ôn HSK2 Bài 1)."},{"type":"sort","context":"Sắp xếp: “Xem ra em không thể giải quyết vấn đề này.”","words":["看来","我","没","办法","解决","这个","问题","。"],"answer":"看来我没办法解决这个问题。","explanation":"看来 + kết luận; 没办法 + V."},{"type":"sort","context":"Sắp xếp: “Muộn thế này rồi, xem ra hôm nay anh ấy không đến nữa.”","words":["这么晚了","，","看来","他","今天","不会","来了","。"],"answer":"这么晚了，看来他今天不会来了。","explanation":"这么 (ôn HSK2 Bài 3) + Adj + 了，看来……."},{"type":"sort","context":"Sắp xếp: “Trời âm u lắm, xem ra sắp mưa rồi.”","words":["天","阴得很","，","看来","要","下雨","了","。"],"answer":"天阴得很，看来要下雨了。","explanation":"阴得很 (ôn HSK3 Bài 5); 要……了 (ôn HSK2 Bài 10)."},{"type":"sort","context":"Sắp xếp: “Thang máy hỏng rồi, xem ra chúng ta chỉ có thể đi bộ lên.”","words":["电梯","坏了","，","看来","咱们","只能","走上去","了","。"],"answer":"电梯坏了，看来咱们只能走上去了。","explanation":"走上去 — bổ ngữ xu hướng (ôn HSK2 Bài 5); 咱们 (ôn HSK3 Bài 3)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 看来.","promptLang":"vi","prompt":"Đã hơn 12 giờ rồi, xem ra anh ấy không về ăn cơm nữa.","answer":"十二点多了，看来他不回来吃饭了。","answerPy":"Shí'èr diǎn duō le, kànlái tā bù huílai chīfàn le.","explanation":"十二点多 — hơn mười hai giờ (câu Bài khoá 3); 回来 (ôn HSK2 Bài 3)."}]},{"point":"Câu chữ 「把」 (3) — 把 + tân ngữ + V + bổ ngữ kết quả","items":[{"context":"Sách: “A: Trước khi cuộc họp bắt đầu, chúng ta phải… B: Được, tôi giúp bạn.” (打扫 – ôn HSK3 Bài 3)","pre":"会议开始前，我们得把","blank":"会议室打扫干净","post":"。","options":["会议室打扫干净","打扫会议室干净","会议室打扫"],"answer":0,"explanation":"把 + O + V + 干净 (干净 – ôn HSK3 Bài 4); 得 děi = phải."},{"context":"Sách: “A: Mẹ ơi, con đói rồi, bây giờ ăn tối được chưa? B: Đợi một lát, mẹ còn…”","pre":"再等一会儿，我还","blank":"没把菜做好呢","post":"。","options":["没把菜做好呢","把菜没做好呢","没把菜做呢"],"answer":0,"explanation":"没 đứng trước 把; V + 好; 还没……呢 — vẫn chưa; 饿 (ôn HSK3 Bài 2)."},{"context":"Sách: “A: Có thời gian thì cậu qua văn phòng tôi một chút. B: Vâng, giám đốc Lưu. Tôi … rồi sẽ đến văn phòng ngài ngay.”","pre":"好的，刘经理。我把","blank":"这封邮件发完","post":"就去您的办公室。","options":["这封邮件发完","发完这封邮件","这封邮件发"],"answer":0,"explanation":"V + 完 + 就…… (……了……就 – ôn HSK3 Bài 5); 封 (ôn HSK3 Bài 5)."},{"context":"“Em sẽ cùng chị làm xong những việc này.”","pre":"我跟您一起把这些工作","blank":"做完","post":"。","options":["做完","做","完做"],"answer":0,"explanation":"Bổ ngữ kết quả 完 đứng ngay sau động từ (ôn HSK2 Bài 3)."},{"context":"“Mẹ đã giặt sạch quần áo rồi.”","pre":"妈妈把衣服","blank":"洗干净了","post":"。","options":["洗干净了","干净洗了","洗了干净"],"answer":0,"explanation":"洗 (ôn HSK2 Bài 3) + 干净 (ôn HSK3 Bài 4)."},{"context":"“Anh ấy vẫn chưa kết nối xong máy tính xách tay.”","pre":"他还","blank":"没把笔记本电脑","post":"接好呢。","options":["没把笔记本电脑","把笔记本电脑没","把没笔记本电脑"],"answer":0,"explanation":"没 + 把 + O + V + 好."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把作业写。","isCorrect":false,"correctVersion":"我把作业写完了。","explanation":"Thiếu bổ ngữ kết quả sau động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"请你把这个句子写清楚。","isCorrect":true,"explanation":"Đúng: 把 + 这个句子 + 写 + 清楚 (清楚、句子 – ôn HSK3 Bài 10)."},{"type":"sort","context":"Sắp xếp: “Em sẽ cùng chị làm xong những việc này.”","words":["我","跟您","一起","把","这些","工作","做完","。"],"answer":"我跟您一起把这些工作做完。","explanation":"跟……一起 đứng trước 把."},{"type":"sort","context":"Sắp xếp: “Em kết nối máy tính giúp chị nhé.”","words":["你","帮我","把","电脑","接好","吧","。"],"answer":"你帮我把电脑接好吧。","explanation":"帮 + người + 把…… (帮 – ôn HSK2 Bài 10)."},{"type":"sort","context":"Sắp xếp: “Tôi vẫn chưa làm xong bài tập.”","words":["我","还","没","把","作业","写完","呢","。"],"answer":"我还没把作业写完呢。","explanation":"没 đứng trước 把; 作业 (ôn HSK3 Bài 10)."},{"type":"sort","context":"Sắp xếp: “Bạn phải nghe rõ câu hỏi của cô giáo.”","words":["你","要","把","老师的","问题","听","清楚","。"],"answer":"你要把老师的问题听清楚。","explanation":"V + 清楚 (ôn HSK3 Bài 10); 要 đứng trước 把."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 把 (3).","promptLang":"vi","prompt":"Em trai tôi đã ăn hết chỗ bánh kem rồi.","answer":"弟弟把蛋糕吃完了。","answerPy":"Dìdi bǎ dàngāo chīwán le.","explanation":"蛋糕 (ôn HSK2 Bài 6); 吃 + 完."}]},{"point":"Cấu trúc cố định 「对……来说」 — đối với… mà nói","items":[{"context":"Sách: “A: Đối với bạn, công việc như thế nào thì phù hợp? B: …” (合适 – ôn HSK3 Bài 7)","pre":"对我来说，","blank":"离家近的工作比较合适","post":"。","options":["离家近的工作比较合适","我很合适离家近的工作","离家近的工作吗"],"answer":0,"explanation":"离 (ôn HSK2 Bài 9); 比较 (ôn HSK3 Bài 5)."},{"context":"Sách: “A: Với người trẻ, lúc tìm việc điều gì quan trọng nhất? B: …”","pre":"对年轻人来说，找工作的时候","blank":"机会最重要","post":"。","options":["机会最重要","最重要机会","机会重要最"],"answer":0,"explanation":"最 + Adj (ôn HSK2 Bài 11); 年轻 (ôn HSK3 Bài 1)."},{"context":"Sách: “A: Tôi thấy khi làm việc vui vẻ là quan trọng nhất. B: Tôi không giống bạn, …”","pre":"我跟你不一样，","blank":"对我来说，工作的环境最重要","post":"。","options":["对我来说，工作的环境最重要","对我说，工作的环境最重要","我来说，工作的环境最重要"],"answer":0,"explanation":"跟……不一样 (ôn HSK3 Bài 4); 环境 (ôn HSK3 Bài 3)."},{"context":"“Đối với cô ấy, học tiếng Trung rất thú vị.”","pre":"","blank":"对她来说","post":"，学习汉语很有意思。","options":["对她来说","对她说","她来说"],"answer":0,"explanation":"Khung đầy đủ 对 + người + 来说; 有意思 (ôn HSK2 Bài 8)."},{"context":"“Đối với trẻ con, chơi cũng là một cách học.”","pre":"对","blank":"孩子","post":"来说，玩也是一种学习。","options":["孩子","给孩子","孩子说"],"answer":0,"explanation":"Giữa 对 và 来说 là người / nhóm người; 种 (ôn HSK3 Bài 8)."},{"context":"“Đối với tôi, gia đình quan trọng hơn công việc.”","pre":"对我来说，家人","blank":"比工作更重要","post":"。","options":["比工作更重要","比工作很重要","更重要比工作"],"answer":0,"explanation":"A 比 B 更 + Adj (ôn HSK3 Bài 7); không dùng 很 trong câu so sánh 比."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"对我说，生活也很重要。","isCorrect":false,"correctVersion":"对我来说，生活也很重要。","explanation":"Thiếu 来: 对……来说."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"对学生来说，考试很重要。","isCorrect":true,"explanation":"Đúng: 对 + 学生 + 来说 + nhận định; 考试 (ôn HSK2 Bài 10)."},{"type":"sort","context":"Sắp xếp: “Đối với tôi, gia đình quan trọng hơn công việc.”","words":["对我","来说","，","家人","比","工作","更","重要","。"],"answer":"对我来说，家人比工作更重要。","explanation":"比……更 (ôn HSK3 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Đối với cô ấy, học tiếng Trung rất thú vị.”","words":["对","她","来说","，","学习","汉语","很","有意思","。"],"answer":"对她来说，学习汉语很有意思。","explanation":"对 + người + 来说 đứng đầu câu."},{"type":"sort","context":"Sắp xếp: “Đối với ông bà, sức khoẻ là quan trọng nhất.”","words":["对","爷爷奶奶","来说","，","身体","健康","最","重要","。"],"answer":"对爷爷奶奶来说，身体健康最重要。","explanation":"健康 (ôn HSK3 Bài 8); 最 (ôn HSK2 Bài 11); 爷爷奶奶 (ôn HSK2 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Đối với tôi, công việc này hơi khó.”","words":["对","我","来说","，","这个","工作","有点儿","难","。"],"answer":"对我来说，这个工作有点儿难。","explanation":"有点儿 + Adj (ôn HSK1 Bài 12); 难 (ôn HSK3 Bài 10)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 对……来说.","promptLang":"vi","prompt":"Đối với tôi, cơ hội này rất quan trọng.","answer":"对我来说，这个机会很重要。","answerPy":"Duì wǒ lái shuō, zhège jīhuì hěn zhòngyào.","explanation":"机会 của bài này; 重要 (ôn HSK3 Bài 1)."}]}],"/lessons/hsk3v3-bai-12.html":[{"point":"Câu ghép lựa chọn 「或者……，或者……」 — hoặc là… hoặc là…","items":[{"context":"Sách: “明天天气不错，你打算做什么？” — Trả lời: “Mình hoặc là đi công viên chèo thuyền, hoặc là đi leo núi.”","pre":"我","blank":"或者去公园坐船，或者去爬山","post":"。","options":["或者去公园坐船，或者去爬山","还是去公园坐船，还是去爬山","去公园坐船或者，去爬山或者"],"answer":0,"explanation":"Câu trần thuật dùng 或者……，或者……; 爬山 (ôn HSK3 Bài 5), 打算 (ôn HSK3 Bài 6)."},{"context":"Sách: “你每天下课回家以后做什么？” — “Mình hoặc là xem TV, hoặc là chơi bóng rổ với bạn.”","pre":"我","blank":"或者看电视，或者跟朋友打篮球","post":"。","options":["或者看电视，或者跟朋友打篮球","看电视或者，跟朋友打篮球或者","或者看电视，跟朋友或者打篮球"],"answer":0,"explanation":"或者 đứng trước mỗi phương án; 打篮球 (ôn HSK2 Bài 7), 以后 (ôn HSK3 Bài 8)."},{"context":"Sách: “考完试你有什么打算？” — “Thi xong, mình hoặc là về nhà, hoặc là đi du lịch với bạn.”","pre":"考完试，我","blank":"或者回家，或者跟朋友去旅游","post":"。","options":["或者回家，或者跟朋友去旅游","还是回家，还是跟朋友去旅游","或者回家，还是跟朋友去旅游"],"answer":0,"explanation":"Không trộn 或者 với 还是; 旅游 (ôn HSK2 Bài 1), V + 完 (ôn HSK2 Bài 3)."},{"context":"“Hoặc là ngày mai, hoặc là ngày kia, cô sẽ gọi điện cho em.”","pre":"","blank":"或者明天去，或者后天去","post":"，我给你打电话。","options":["或者明天去，或者后天去","还是明天去，还是后天去","或者明天去，还是后天去"],"answer":0,"explanation":"Câu của Bài khoá 1; 给 + người + 打电话 (ôn HSK1 Bài 13)."},{"context":"“Bạn uống trà hay cà phê?” (câu hỏi lựa chọn)","pre":"你喝茶","blank":"还是","post":"喝咖啡？","options":["还是","或者","也"],"answer":0,"explanation":"Câu HỎI lựa chọn dùng 还是 (ôn HSK2 Bài 2, HSK3 Bài 11), không dùng 或者; 咖啡 (ôn HSK2 Bài 9)."},{"context":"“Bữa tối em tự chọn nhé, hoặc món Trung, hoặc món Thái.”","pre":"晚饭你自己选，","blank":"或者吃中国菜，或者吃泰国菜","post":"。","options":["或者吃中国菜，或者吃泰国菜","还是吃中国菜，还是吃泰国菜","吃中国菜或者，吃泰国菜或者"],"answer":0,"explanation":"自己 (ôn HSK2 Bài 3); 选 (ôn HSK3 Bài 2)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你想去公园或者去爬山？","isCorrect":false,"correctVersion":"你想去公园还是去爬山？","explanation":"Câu hỏi lựa chọn phải dùng 还是."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们或者今天去电影院看电影，或者明天在家看电影。","isCorrect":true,"explanation":"Đúng: hai phương án đều có 或者 đứng trước; 电影院 (ôn HSK1 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Hoặc là ngày mai, hoặc là ngày kia, cô sẽ gọi điện cho em.”","words":["或者","明天去","，","或者","后天去","，","我","给你","打电话","。"],"answer":"或者明天去，或者后天去，我给你打电话。","explanation":"或者 + phương án A，或者 + phương án B."},{"type":"sort","context":"Sắp xếp: “Thứ bảy mình hoặc là ở nhà nghỉ ngơi, hoặc là đi siêu thị mua đồ.”","words":["星期六","我","或者","在家","休息","，","或者","去","超市","买东西","。"],"answer":"星期六我或者在家休息，或者去超市买东西。","explanation":"休息 (ôn HSK1 Bài 5); 超市 (ôn HSK1 Bài 6)."},{"type":"sort","context":"Sắp xếp: “Chúng ta hoặc là đi tàu cao tốc, hoặc là đi máy bay, đều được.”","words":["咱们","或者","坐高铁","，","或者","坐飞机","，","都","可以","。"],"answer":"咱们或者坐高铁，或者坐飞机，都可以。","explanation":"高铁 (ôn HSK3 Bài 6); 咱们 (ôn HSK3 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Bạn hoặc là gọi điện cho tôi, hoặc là viết email cho tôi.”","words":["你","或者","给我","打电话","，","或者","给我","写","邮件","。"],"answer":"你或者给我打电话，或者给我写邮件。","explanation":"邮件 (ôn HSK3 Bài 5); 给 + người + V."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 或者……，或者…….","promptLang":"vi","prompt":"Ngày mai trời đẹp, chúng ta hoặc là đi công viên, hoặc là đi leo núi.","answer":"明天天气很好，咱们或者去公园，或者去爬山。","answerPy":"Míngtiān tiānqì hěn hǎo, zánmen huòzhě qù gōngyuán, huòzhě qù pá shān.","explanation":"咱们 (ôn HSK3 Bài 3); 爬山 (ôn HSK3 Bài 5)."}]},{"point":"Bổ ngữ xu hướng mở rộng (2) 「起来」 — bắt đầu, chuyển sang trạng thái mới","items":[{"context":"Sách: “Nhìn thấy bức ảnh đó, mọi người đều bật cười.”","pre":"看到那张照片，大家都","blank":"笑起来了","post":"。","options":["笑起来了","笑起了来","起来笑了"],"answer":0,"explanation":"笑 (ôn HSK2 Bài 10) + 起来: bắt đầu cười; 张 (ôn HSK3 Bài 2)."},{"context":"Sách: “Uống thuốc xong, sức khoẻ của anh ấy đã khá lên.”","pre":"吃了药以后，他的身体","blank":"好起来了","post":"。","options":["好起来了","起来好了","好起了来"],"answer":0,"explanation":"Tính từ + 起来 + 了: chuyển sang trạng thái mới; 身体 (ôn HSK2 Bài 11), 药 (ôn HSK1 Bài 12)."},{"context":"Sách: “Cậu ấy làm xong bài tập là bắt đầu xem TV.”","pre":"他写完作业就","blank":"看起电视来了","post":"。","options":["看起电视来了","看电视起来了","看起来电视了"],"answer":0,"explanation":"Có tân ngữ (电视) thì đặt giữa 起 và 来; 作业 (ôn HSK3 Bài 10), 就 = ngay (ôn HSK3 Bài 3)."},{"context":"“Sao bỗng nhiên lại nổi gió thế?”","pre":"怎么突然","blank":"刮起风来","post":"了？","options":["刮起风来","刮风起来","起来刮风"],"answer":0,"explanation":"Tân ngữ 风 đứng giữa 起 và 来; 突然 (ôn HSK3 Bài 8)."},{"context":"“Dạo này trời bắt đầu nóng lên rồi.”","pre":"最近天气","blank":"热起来","post":"了。","options":["热起来","起来热","热下来"],"answer":0,"explanation":"Tính từ 热 + 起来: bắt đầu nóng lên; 最近 (ôn HSK3 Bài 8)."},{"context":"“Lúc chúng tôi ra khỏi nhà thì trời bắt đầu mưa.”","pre":"我们出门的时候，","blank":"下起雨来了","post":"。","options":["下起雨来了","下雨起来了","起来下雨了"],"answer":0,"explanation":"下雨 có tân ngữ 雨 → 下起雨来; 出门 (ôn HSK2 Bài 15)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"外面突然刮风起来了。","isCorrect":false,"correctVersion":"外面突然刮起风来了。","explanation":"Tân ngữ 风 phải đặt giữa 起 và 来."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"雨已经下起来了，咱们快点儿走吧。","isCorrect":true,"explanation":"Đúng: 下 + 起来 + 了; 咱们 (ôn HSK3 Bài 3), 已经……了 (ôn HSK2 Bài 1)."},{"type":"sort","context":"Sắp xếp: “Trời đã bắt đầu mưa rồi.”","words":["雨","已经","下","起来","了","。"],"answer":"雨已经下起来了。","explanation":"已经……了 (ôn HSK2 Bài 1)."},{"type":"sort","context":"Sắp xếp: “Sao bỗng nhiên lại nổi gió thế?”","words":["怎么","突然","刮","起","风","来","了","？"],"answer":"怎么突然刮起风来了？","explanation":"刮 + 起 + 风 + 来."},{"type":"sort","context":"Sắp xếp: “Dạo này trời bắt đầu nóng lên rồi.”","words":["最近","天气","热","起来","了","。"],"answer":"最近天气热起来了。","explanation":"Tính từ + 起来 + 了."},{"type":"sort","context":"Sắp xếp: “Sức khoẻ của anh ấy cuối cùng cũng khá lên rồi.”","words":["他的","身体","终于","好","起来","了","。"],"answer":"他的身体终于好起来了。","explanation":"终于 (ôn HSK3 Bài 5)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 起来.","promptLang":"vi","prompt":"Vừa nãy còn nắng, bây giờ trời bắt đầu mưa rồi.","answer":"刚才还是晴天，现在下起雨来了。","answerPy":"Gāngcái hái shì qíngtiān, xiànzài xià qǐ yǔ lai le.","explanation":"晴 (ôn HSK2 Bài 12); 刚才 của bài này."}]},{"point":"Phó từ chỉ phạm vi 「就」 — chỉ (số lượng ít / ngoại lệ)","items":[{"context":"Sách: “Hôm qua mình ngủ không ngon, chỉ ngủ có năm tiếng.”","pre":"我昨天没睡好，","blank":"就睡了五个小时","post":"。","options":["就睡了五个小时","睡了就五个小时","睡了五个小时就"],"answer":0,"explanation":"就 + V + 了 + số lượng: chỉ… (cho là ít); 小时 (ôn HSK1 Bài 15)."},{"context":"Sách: “Lần thi này mọi người đều làm tốt, chỉ có cậu ấy làm chưa tốt.”","pre":"这次考试大家都考得很好，","blank":"就他没考好","post":"。","options":["就他没考好","他没考好就","都他没考好"],"answer":0,"explanation":"就 + chủ ngữ (他): ngoại lệ “chỉ riêng cậu ấy”; 考得很好 (ôn HSK2 Bài 7)."},{"context":"Sách: “Bạn trong lớp mình hầu như ai cũng biết chơi bóng rổ, chỉ có mình là không biết.”","pre":"我们班同学几乎都会打篮球，","blank":"就我不会","post":"。","options":["就我不会","我不会就","只就我不会"],"answer":0,"explanation":"几乎 (ôn HSK3 Bài 9); 就 + 我: ngoại lệ."},{"context":"“Hôm qua cậu ấy chỉ đọc sách có mười phút.”","pre":"他昨天","blank":"就看了十分钟","post":"书。","options":["就看了十分钟","看了就十分钟","看了十分钟就"],"answer":0,"explanation":"就 đứng trước động từ mang số lượng; 分钟 (ôn HSK1 Bài 7)."},{"context":"“Ngày nào em cũng để ô trong cặp, chỉ riêng hôm nay không mang.”","pre":"我每天书包里都放着雨伞，","blank":"就今天","post":"没带。","options":["就今天","今天都","才今天"],"answer":0,"explanation":"……都……，就 + N + ……: ngoại lệ; 书包 (ôn HSK2 Bài 4), 带 (ôn HSK3 Bài 1)."},{"context":"“Món các bạn gọi đều khá ngon, chỉ có món mình gọi là không ngon lắm.”","pre":"你们点的菜都挺好吃的，","blank":"就","post":"我点的这个菜不太好吃。","options":["就","才","都"],"answer":0,"explanation":"挺……的 (ôn HSK3 Bài 3); 就 + chủ ngữ: ngoại lệ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我昨天睡了就五个小时。","isCorrect":false,"correctVersion":"我昨天就睡了五个小时。","explanation":"就 phải đứng TRƯỚC động từ, không đứng trước cụm số lượng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"北京常常下雪，但听说今年就下了一次。","isCorrect":true,"explanation":"Đúng: 就 + V + 了 + 一次 — chỉ một lần (cho là ít); 听说 (ôn HSK3 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Hôm qua cậu ấy chỉ đọc sách có mười phút.”","words":["他","昨天","就","看了","十分钟","书","。"],"answer":"他昨天就看了十分钟书。","explanation":"就 + V + 了 + thời lượng + tân ngữ."},{"type":"sort","context":"Sắp xếp: “Bắc Kinh thường có tuyết, nhưng nghe nói năm nay chỉ rơi có một lần.”","words":["北京","常常","下雪","，","但","听说","今年","就","下了","一次","。"],"answer":"北京常常下雪，但听说今年就下了一次。","explanation":"常常 của bài này; 听说 (ôn HSK3 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Mọi người đều đến rồi, chỉ có Tiểu Vương vẫn chưa đến.”","words":["大家","都","来了","，","就","小王","还","没来","。"],"answer":"大家都来了，就小王还没来。","explanation":"就 + chủ ngữ: ngoại lệ; 还没 + V = vẫn chưa."},{"type":"sort","context":"Sắp xếp: “Tôi chỉ có một trăm tệ.”","words":["我","就","有","一百","块","钱","。"],"answer":"我就有一百块钱。","explanation":"就 + 有 + số lượng: chỉ có; 块 (ôn HSK1 Bài 10)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 就 (chỉ).","promptLang":"vi","prompt":"Các bạn lớp tôi đều thích mùa đông, chỉ có tôi là không thích.","answer":"我们班同学都喜欢冬天，就我不喜欢。","answerPy":"Wǒmen bān tóngxué dōu xǐhuan dōngtiān, jiù wǒ bù xǐhuan.","explanation":"班 (ôn HSK2 Bài 13); 就 + 我: ngoại lệ."}]},{"point":"Bổ ngữ xu hướng mở rộng (3) 「下来」 — hoàn thành việc tốn thời gian, công sức","items":[{"context":"Sách: “Cảm ơn bạn đã luôn giúp mình, mình mới học trọn được khoá học năm nay.”","pre":"谢谢你一直帮助我，才让我","blank":"把这一年的课学下来","post":"。","options":["把这一年的课学下来","把这一年的课学起来","把这一年的课下来学"],"answer":0,"explanation":"下来: hoàn thành việc tốn thời gian, công sức; 帮助 (ôn HSK3 Bài 1), 才 (ôn HSK3 Bài 3)."},{"context":"Sách: “Tuy ngoại ngữ rất khó học, nhưng mình vẫn luôn kiên trì học được đến giờ.”","pre":"虽然外语很难学，可是我","blank":"一直学下来了","post":"。","options":["一直学下来了","一直学起来了","一直下来学了"],"answer":0,"explanation":"虽然……可是…… (≈ 但是, ôn HSK2 Bài 8); 外语 (ôn HSK3 Bài 10)."},{"context":"Sách: “Cuốn sách này với tôi rất khó, tôi mất một tháng cuối cùng cũng đọc hết được.”","pre":"这本书对我来说很难，我用了一个月终于","blank":"看下来了","post":"。","options":["看下来了","看起来了","下来看了"],"answer":0,"explanation":"对……来说 (ôn HSK3 Bài 11); 终于 (ôn HSK3 Bài 5)."},{"context":"“Sống ở đây hơn một năm, tôi vẫn thích bốn mùa ở Bắc Kinh hơn.”","pre":"这一年多","blank":"住下来","post":"，我还是更喜欢北京的四季。","options":["住下来","住起来","下来住"],"answer":0,"explanation":"Câu của Bài khoá 4; 更 (ôn HSK2 Bài 4)."},{"context":"“Luyện suốt nửa năm nay, trình độ vẽ của cậu ấy tiến bộ không ít.”","pre":"这半年","blank":"练下来","post":"，他画画的水平提高了不少。","options":["练下来","练起来","下来练"],"answer":0,"explanation":"练 (ôn HSK3 Bài 9); 水平 (ôn HSK3 Bài 5); 提高 (ôn HSK3 Bài 10)."},{"context":"“Cuộc thi chạy 5000 mét, không ngờ tôi lại chạy được đến đích.”","pre":"5000米的长跑比赛，没想到我","blank":"跑下来了","post":"。","options":["跑下来了","跑起来了","下来跑了"],"answer":0,"explanation":"比赛 (ôn HSK3 Bài 9); 米 (ôn HSK3 Bài 1). 长跑 = chạy cự ly dài."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"一年多住起来，我已经习惯这里了。","isCorrect":false,"correctVersion":"一年多住下来，我已经习惯这里了。","explanation":"Hoàn thành một quá trình tốn thời gian → dùng 下来, không dùng 起来."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这本书很难，可是我终于看下来了。","isCorrect":true,"explanation":"Đúng: 看下来 = đọc trọn được (tốn công sức); 终于 (ôn HSK3 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Sống ở đây hơn một năm, tôi vẫn thích bốn mùa ở Bắc Kinh hơn.”","words":["这","一年多","住","下来","，","我","还是","更","喜欢","北京的","四季","。"],"answer":"这一年多住下来，我还是更喜欢北京的四季。","explanation":"Khoảng thời gian + V + 下来，kết quả."},{"type":"sort","context":"Sắp xếp: “Luyện suốt nửa năm nay, trình độ vẽ của cậu ấy tiến bộ không ít.”","words":["这","半年","练","下来","，","他","画画的","水平","提高了","不少","。"],"answer":"这半年练下来，他画画的水平提高了不少。","explanation":"半 (ôn HSK1 Bài 7); 画 (ôn HSK2 Bài 6)."},{"type":"sort","context":"Sắp xếp: “Cuộc thi chạy 5000 mét, không ngờ tôi lại chạy được đến đích.”","words":["5000米的","长跑","比赛","，","没想到","我","跑","下来","了","。"],"answer":"5000米的长跑比赛，没想到我跑下来了。","explanation":"跑 (ôn HSK2 Bài 7) + 下来."},{"type":"sort","context":"Sắp xếp: “Học suốt một tháng, tiếng Trung của tôi tiến bộ rất nhiều.”","words":["一个月","学","下来","，","我的","中文","提高了","很多","。"],"answer":"一个月学下来，我的中文提高了很多。","explanation":"提高 (ôn HSK3 Bài 10)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng V + 下来.","promptLang":"vi","prompt":"Học suốt một năm, tiếng Trung của cô ấy đã nói rất tốt rồi.","answer":"一年学下来，她的中文说得很好了。","answerPy":"Yì nián xué xiàlai, tā de Zhōngwén shuō de hěn hǎo le.","explanation":"V + 得 + Adj (ôn HSK2 Bài 7)."}]}],"/lessons/hsk3v3-bai-13.html":[{"point":"Câu ghép giả định 「……的话，就……」 — nếu… thì…","items":[{"context":"Sách: A: “Mai bạn rảnh thì đến nhà mình ăn cơm nhé.” — B: “Được đấy, nghe nói món Bắc Kinh bạn nấu ngon lắm.”","pre":"明天你没事的话，","blank":"就来我家吃饭吧","post":"。——好啊，早就听说你做的北京菜特别好吃。","options":["就来我家吃饭吧","来就我家吃饭吧","的话来我家吃饭吧"],"answer":0,"explanation":"Vế sau dùng 就 + V; 听说 (ôn HSK3 Bài 3)."},{"context":"Sách: A: “Hôm nay bạn có thời gian thì chúng mình đi ăn vịt quay nhé?” — B: “Hôm nay không được, trưa mai chúng ta cùng đi nhé.”","pre":"","blank":"你今天有时间的话，我们就去吃烤鸭","post":"，好吗？——今天不行，明天中午我们一起去吧。","options":["你今天有时间的话，我们就去吃烤鸭","的话你今天有时间，我们就去吃烤鸭","你今天有时间，就我们的话去吃烤鸭"],"answer":0,"explanation":"……的话，chủ ngữ + 就 + V; 烤鸭 (ôn HSK2 Bài 1)."},{"context":"Sách: A: “Bạn không muốn nấu cơm thì chúng ta gọi đồ ăn ngoài nhé.” — B: “Được, mình không hay gọi đồ ăn ngoài, bạn gọi đi.”","pre":"你不想做饭","blank":"的话，我们就点外卖吧","post":"。——行，我不常点外卖，你点吧。","options":["的话，我们就点外卖吧","，的话我们就点外卖吧","的话，就我们点外卖吧"],"answer":0,"explanation":"外卖 (ôn HSK3 Bài 2); 的话 đứng trước dấu phẩy, 就 sau chủ ngữ."},{"context":"“Bạn thấy hài lòng thì chúng ta mua.” (满意 – ôn HSK3 Bài 4)","pre":"你觉得满意","blank":"的话，咱们就买","post":"。","options":["的话，咱们就买","，的话咱们就买","的话，就咱们买"],"answer":0,"explanation":"咱们 (ôn HSK3 Bài 3) đứng trước 就."},{"context":"“Mai trời đẹp thì tôi đi leo núi.” (爬山 – ôn HSK3 Bài 5)","pre":"明天天气好的话，","blank":"我就去爬山","post":"。","options":["我就去爬山","就我去爬山","我去就爬山"],"answer":0,"explanation":"Chủ ngữ + 就 + V."},{"context":"“Nếu bạn mệt thì nghỉ một lát đi.” (如果 – ôn HSK3 Bài 6)","pre":"","blank":"如果你累了的话","post":"，就休息一会儿吧。","options":["如果你累了的话","的话如果你累了","如果的话你累了"],"answer":0,"explanation":"如果……的话 kết hợp được; 一会儿 (ôn HSK2 Bài 5)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"的话你有时间，就来我家做客吧。","isCorrect":false,"correctVersion":"你有时间的话，就来我家做客吧。","explanation":"的话 đứng cuối vế giả định."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你不忙的话，我们就一起去看电影吧。","isCorrect":true,"explanation":"Đúng: ……的话，chủ ngữ + 就……; 电影 (ôn HSK1 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Các bạn có thời gian thì đến nhà mình chơi nhé.”","words":["你们","有","时间","的话","，","就","来","我家","做客","。"],"answer":"你们有时间的话，就来我家做客。","explanation":"……的话 +，+ 就 + V."},{"type":"sort","context":"Sắp xếp: “Bạn thấy hài lòng thì chúng ta mua.”","words":["你","觉得","满意","的话","，","咱们","就","买","。"],"answer":"你觉得满意的话，咱们就买。","explanation":"咱们 đứng trước 就."},{"type":"sort","context":"Sắp xếp: “Mai trời mưa thì chúng ta không đi nữa.”","words":["明天","下雨","的话","，","我们","就","不","去","了","。"],"answer":"明天下雨的话，我们就不去了。","explanation":"下雨 (ôn HSK1 Bài 12); 不……了 = không… nữa."},{"type":"sort","context":"Sắp xếp: “Bạn thích thì tôi tặng bạn.”","words":["你","喜欢","的话","，","我","就","送给","你","。"],"answer":"你喜欢的话，我就送给你。","explanation":"送给 (ôn HSK2 Bài 3)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng ……的话，就…….","promptLang":"vi","prompt":"Bạn đói thì ăn chút gì đó trước đi.","answer":"你饿了的话，就先吃点儿什么吧。","answerPy":"Nǐ è le dehuà, jiù xiān chī diǎnr shénme ba.","explanation":"饿 (ôn HSK3 Bài 2); 什么 = cái gì đó (ôn HSK3 Bài 1); 先 (ôn HSK3 Bài 4)."}]},{"point":"Câu chữ 「把」 (4) — 把 + tân ngữ + V + bổ ngữ xu hướng / trạng thái","items":[{"context":"Sách: “Mẹ dọn phòng rất sạch sẽ.” (打扫 – ôn HSK3 Bài 3; 干净 – ôn HSK3 Bài 4)","pre":"妈妈把房间","blank":"打扫得很干净","post":"。","options":["打扫得很干净","很干净打扫","打扫很干净得"],"answer":0,"explanation":"把 + O + V + 得 + trạng thái."},{"context":"Sách: “Bây giờ trời nóng quá, bạn nên cho mấy thứ này vào tủ lạnh.”","pre":"现在天气太热了，你应该把这些东西","blank":"放进冰箱里","post":"。","options":["放进冰箱里","冰箱里放进","放冰箱进里"],"answer":0,"explanation":"V + 进 + nơi chốn; 应该 (ôn HSK3 Bài 1) đứng trước 把; 冰箱 (ôn HSK3 Bài 3)."},{"context":"Sách: “Trời lạnh quá, bạn đi lấy áo khoác lại đây.” (大衣 – ôn HSK3 Bài 5)","pre":"天气太冷了，你去把大衣","blank":"拿过来","post":"。","options":["拿过来","过来拿","拿来过"],"answer":0,"explanation":"Bổ ngữ xu hướng kép 过来: mang lại gần người nói."},{"context":"“Bạn viết chữ nhỏ quá, tôi nhìn không rõ.”","pre":"你把字","blank":"写得太小了","post":"，我看不清楚。","options":["写得太小了","太小了写得","写太小得了"],"answer":0,"explanation":"把 + 字 + 写得 + 太小了; 看不清楚 (ôn HSK3 Bài 9, 10)."},{"context":"“Anh ấy đá bóng vào lưới chưa?” (踢 – ôn HSK2 Bài 7)","pre":"他","blank":"把球踢进去","post":"了吗？","options":["把球踢进去","踢进去把球","把踢进去球"],"answer":0,"explanation":"把 + 球 + 踢 + 进去."},{"context":"“Em nhớ vừa nãy đã lấy đồ uống ra rồi.” (记得 – ôn HSK2 Bài 8)","pre":"我记得刚才已经把饮料","blank":"拿出来","post":"了。","options":["拿出来","出来拿","拿出"],"answer":0,"explanation":"V + 出来 — vật từ trong ra ngoài; 刚才 = vừa nãy."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他把球没踢进去。","isCorrect":false,"correctVersion":"他没把球踢进去。","explanation":"没 đứng trước 把."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我去把盘子拿过来。","isCorrect":true,"explanation":"Đúng: 把 + 盘子 + 拿过来 (bổ ngữ xu hướng kép); câu liên động 去 + V."},{"type":"sort","context":"Sắp xếp: “Em bật âm thanh to quá rồi.”","words":["你","把","声音","开","得","太","大","了","。"],"answer":"你把声音开得太大了。","explanation":"把 + O + V + 得 + 太 + Adj + 了."},{"type":"sort","context":"Sắp xếp: “Anh để hết đồ uống và rượu vào tủ lạnh rồi.”","words":["我","把","饮料","和","酒","都","放进","冰箱里","了","。"],"answer":"我把饮料和酒都放进冰箱里了。","explanation":"都 đứng sau tân ngữ của 把, trước động từ."},{"type":"sort","context":"Sắp xếp: “Chị đi lấy đĩa lại đây.”","words":["我","去","把","盘子","拿","过来","。"],"answer":"我去把盘子拿过来。","explanation":"去 + 把 + O + 拿过来."},{"type":"sort","context":"Sắp xếp: “Mẹ dọn phòng rất sạch sẽ.”","words":["妈妈","把","房间","打扫","得","很","干净","。"],"answer":"妈妈把房间打扫得很干净。","explanation":"房间 (ôn HSK1 Bài 8)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu chữ 把 + bổ ngữ xu hướng.","promptLang":"vi","prompt":"Bạn mang va li vào đi.","answer":"你把箱子拿进来吧。","answerPy":"Nǐ bǎ xiāngzi ná jìnlai ba.","explanation":"箱子 (ôn HSK3 Bài 1); 进来 (ôn HSK2 Bài 5)."}]},{"point":"Câu ghép đẳng lập 「一边……，一边……」 — vừa… vừa…","items":[{"context":"Sách: A: “Hôm qua bạn đi đâu với Gia Nguyệt?” — B: “Đi nhà hàng, bọn mình vừa ăn vừa trò chuyện, vui ơi là vui.”","pre":"昨天你跟家月去哪儿了？——去饭馆了，我们","blank":"一边吃饭，一边聊天儿","post":"，开心极了。","options":["一边吃饭，一边聊天儿","一边吃饭，聊天儿一边","吃饭一边，聊天儿一边"],"answer":0,"explanation":"极了 (ôn HSK3 Bài 7); 开心 (ôn HSK3 Bài 8)."},{"context":"Sách: A: “Hôm qua leo núi chắc mệt lắm nhỉ?” — B: “Bọn mình vừa leo vừa hát, chẳng mệt chút nào.”","pre":"你们昨天爬山爬得很累吧？——我们","blank":"一边爬山，一边唱歌","post":"，一点儿也不累。","options":["一边爬山，一边唱歌","一边爬山，一边很高兴","爬山一边，唱歌一边"],"answer":0,"explanation":"Sau 一边 là động từ, không phải tính từ; 一点儿也不 + Adj (ôn HSK3 Bài 4)."},{"context":"Sách: A: “Lúc nghỉ ngơi bạn thích làm gì?” — B: “Mình thường vừa uống trà vừa đọc sách.”","pre":"休息的时候你喜欢做什么？——我常常","blank":"一边喝茶，一边看书","post":"。","options":["一边喝茶，一边看书","一边喝茶，看书","喝茶一边，看书一边"],"answer":0,"explanation":"Hai vế đều cần 一边; 茶 (ôn HSK1 Bài 13)."},{"context":"“Tôi thích vừa chạy bộ vừa nghe nhạc.” (跑步 – ôn HSK2 Bài 7)","pre":"我喜欢","blank":"一边跑步，一边听音乐","post":"。","options":["一边跑步，一边听音乐","一边跑步，又听音乐","跑步一边，听音乐"],"answer":0,"explanation":"音乐 (ôn HSK3 Bài 5)."},{"context":"“Bạn không nên vừa lái xe vừa gọi điện thoại.” (应该 – ôn HSK3 Bài 1)","pre":"你不应该","blank":"边开车边打电话","post":"。","options":["边开车边打电话","开车边打电话边","边开车打电话"],"answer":0,"explanation":"Dạng rút gọn 边……边……."},{"context":"“Món này vừa rẻ vừa ngon.” (phân biệt với 一边……一边……)","pre":"这个菜","blank":"又便宜又好吃","post":"。","options":["又便宜又好吃","一边便宜一边好吃","边便宜边好吃"],"answer":0,"explanation":"Hai tính chất → 又……又…… (ôn HSK3 Bài 2); 便宜 (ôn HSK1 Bài 10)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个菜一边便宜，一边好吃。","isCorrect":false,"correctVersion":"这个菜又便宜又好吃。","explanation":"Hai tính từ → dùng 又……又……."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"咱们一边吃蛋糕，一边聊天儿吧。","isCorrect":true,"explanation":"Đúng: hai hành động cùng lúc; 咱们 (ôn HSK3 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Chúng ta vừa ăn bánh kem vừa trò chuyện nhé.”","words":["咱们","一边","吃","蛋糕","，","一边","聊天儿","吧","。"],"answer":"咱们一边吃蛋糕，一边聊天儿吧。","explanation":"蛋糕 (ôn HSK2 Bài 6)."},{"type":"sort","context":"Sắp xếp: “Tôi thích vừa chạy bộ vừa nghe nhạc.”","words":["我","喜欢","一边","跑步","，","一边","听","音乐","。"],"answer":"我喜欢一边跑步，一边听音乐。","explanation":"喜欢 + cả cụm 一边……一边……."},{"type":"sort","context":"Sắp xếp: “Bạn không nên vừa lái xe vừa gọi điện thoại.”","words":["你","不","应该","边","开车","边","打","电话","。"],"answer":"你不应该边开车边打电话。","explanation":"边……边…… rút gọn."},{"type":"sort","context":"Sắp xếp: “Hôm đó chúng tôi vừa uống trà đen vừa trò chuyện.”","words":["那天","我们","一边","喝","红茶","，","一边","聊天儿","。"],"answer":"那天我们一边喝红茶，一边聊天儿。","explanation":"Thời gian 那天 đứng đầu câu."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 一边……，一边…….","promptLang":"vi","prompt":"Bố tôi thường vừa ăn sáng vừa xem điện thoại.","answer":"我爸爸常常一边吃早饭，一边看手机。","answerPy":"Wǒ bàba chángcháng yìbiān chī zǎofàn, yìbiān kàn shǒujī.","explanation":"早饭 (ôn HSK1 Bài 13); 常常 (ôn HSK3 Bài 8)."}]}],"/lessons/hsk3v3-bai-14.html":[{"point":"Câu bị động (1) — Chủ ngữ + 被 + (tân ngữ) + V + thành phần khác","items":[{"context":"Sách: A: 你的自行车呢？ B: “Bị anh trai mình đi mất rồi.” (自行车 – ôn HSK3 Bài 7)","pre":"我的自行车","blank":"被哥哥骑走了","post":"。","options":["被哥哥骑走了","哥哥被骑走了","被骑哥哥走了"],"answer":0,"explanation":"被 + người + 骑 + 走了; 骑 (ôn HSK3 Bài 4), 走 cho biết kết quả."},{"context":"Sách: A: 你怎么没带照相机？ B: “Máy ảnh bị bạn mình mượn đi rồi.” (相机 – ôn HSK3 Bài 4)","pre":"照相机","blank":"被朋友借走了","post":"。","options":["被朋友借走了","朋友被借走了","被借朋友走了"],"answer":0,"explanation":"被 + người + V + 走了; 借 (ôn HSK3 Bài 12)."},{"context":"Sách: A: 我刚买的咖啡呢？ B: “Có lẽ bị em gái bạn uống mất rồi.” (咖啡 – ôn HSK2 Bài 9)","pre":"咖啡","blank":"可能被你妹妹喝了","post":"。","options":["可能被你妹妹喝了","被你妹妹可能喝了","被可能你妹妹喝了"],"answer":0,"explanation":"可能 (ôn HSK2 Bài 13) đứng TRƯỚC 被."},{"context":"“Hoa quả có lẽ đã bị em trai ăn mất rồi.”","pre":"水果","blank":"可能被弟弟","post":"吃了。","options":["可能被弟弟","被弟弟可能","被可能弟弟"],"answer":0,"explanation":"Phó từ / động từ năng nguyện đứng trước 被; 水果 (ôn HSK1 Bài 10)."},{"context":"“Hai đứa mình thường bị gọi nhầm tên.” (俩 = hai người)","pre":"我们俩经常被叫","blank":"错","post":"名字。","options":["错","在","给"],"answer":0,"explanation":"V + 错 — bổ ngữ kết quả “nhầm” (错 – ôn HSK2 Bài 10); 经常 (ôn HSK2 Bài 11) đứng trước 被."},{"context":"“Mình không nhớ nữa, có thể bị mình để ở nhà rồi.”","pre":"我忘记了，可能被我","blank":"放在家里了","post":"。","options":["放在家里了","放家里在了","在家里放"],"answer":0,"explanation":"Sau 被 + người + V cần thành phần khác: 放 + 在家里 + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这本书被别人借。","isCorrect":false,"correctVersion":"这本书被别人借走了。","explanation":"Động từ 借 sau 被 không đứng một mình, phải thêm 走了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我的校园卡没被别人拿走，还在我的书包里。","isCorrect":true,"explanation":"Đúng: 没 đứng trước 被. 书包 (ôn HSK2 Bài 4), 校园卡 (ôn HSK3 Bài 9)."},{"type":"sort","context":"Sắp xếp: “Quyển sách này đã bị người khác mượn mất rồi.”","words":["这本书","被","别人","借走","了","。"],"answer":"这本书被别人借走了。","explanation":"这本书 + 被 + 别人 + 借走了."},{"type":"sort","context":"Sắp xếp: “Bánh kem bị em trai ăn mất rồi.”","words":["蛋糕","被","弟弟","吃","了","。"],"answer":"蛋糕被弟弟吃了。","explanation":"蛋糕 (ôn HSK2 Bài 6)."},{"type":"sort","context":"Sắp xếp: “Thầy cô và hiệu trưởng cũng được mời lên nhảy cùng.”","words":["老师","和","校长","也","被","叫","起来","一块儿","跳","。"],"answer":"老师和校长也被叫起来一块儿跳。","explanation":"也 đứng trước 被; câu của Bài khoá 4."},{"type":"sort","context":"Sắp xếp: “Hộ chiếu của tôi bị tôi để quên ở khách sạn rồi.”","words":["我的","护照","被","我","忘在","宾馆","了","。"],"answer":"我的护照被我忘在宾馆了。","explanation":"忘 (ôn HSK2 Bài 6), 宾馆 (ôn HSK3 Bài 4), 护照 (ôn HSK3 Bài 1)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu bị động 被.","promptLang":"vi","prompt":"Điện thoại của tôi bị em gái lấy đi rồi.","answer":"我的手机被妹妹拿走了。","answerPy":"Wǒ de shǒujī bèi mèimei názǒu le.","explanation":"拿 (ôn HSK2 Bài 3) + 走 cho biết kết quả."}]},{"point":"Câu ghép tiếp nối 「先……，再 / 然后……」","items":[{"context":"Sách: A: 下课以后，你做什么？ B: …","pre":"我先去图书馆看书，","blank":"然后","post":"去游泳。","options":["然后","以后","先"],"answer":0,"explanation":"先……，然后…… — trước… sau đó…; 游泳 (ôn HSK2 Bài 7)."},{"context":"Sách: A: 考完试了，你有什么打算？ B: …","pre":"我打算先好好休息几天，","blank":"再","post":"去旅游。","options":["再","先","才"],"answer":0,"explanation":"再 + V = rồi mới…; 打算 (ôn HSK3 Bài 6), 旅游 (ôn HSK2 Bài 1)."},{"context":"Sách: A: 听说你妈妈要来北京，你打算带她去哪儿玩？ B: …","pre":"我打算","blank":"先带她去北京大学看看，然后去吃饺子","post":"。","options":["先带她去北京大学看看，然后去吃饺子","然后带她去北京大学看看，先去吃饺子","带她去北京大学先看看，以后先去吃饺子"],"answer":0,"explanation":"先 + V₁，然后 + V₂; 北京大学 (ôn HSK2 Bài 2), 带 (ôn HSK3 Bài 1)."},{"context":"“Bạn đi mua vé vào cửa trước, rồi hãy đến đây tìm mình.”","pre":"你先去买门票，","blank":"再来","post":"这里找我。","options":["再来","来再","先来"],"answer":0,"explanation":"再 đứng ngay trước động từ 来; 门票 (ôn HSK2 Bài 15)."},{"context":"“Các bạn về phòng nghỉ một lát trước, sau đó hẵng ra ăn tối.”","pre":"你们","blank":"先回房间","post":"休息一会儿，然后再出来吃晚饭。","options":["先回房间","回先房间","回房间先"],"answer":0,"explanation":"先 đứng trước động từ 回; 一会儿 (ôn HSK2 Bài 5)."},{"context":"“Hôm nay mình rất bận, phải đến thư viện mượn sách trước, sau đó đi bơi.”","pre":"我今天忙得很，要","blank":"先去图书馆借书","post":"，然后去游泳。","options":["先去图书馆借书","去先图书馆借书","去图书馆借书先"],"answer":0,"explanation":"要 + 先 + V; câu của Bài khoá 2."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我先去超市买东西，然后回家做饭。","isCorrect":true,"explanation":"Đúng: 先 + V₁，然后 + V₂. 超市 (ôn HSK1 Bài 6)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你先吃饭，再你去写作业。","isCorrect":false,"correctVersion":"你先吃饭，再去写作业。","explanation":"再 đứng sau chủ ngữ, trước động từ."},{"type":"sort","context":"Sắp xếp: “Mình phải đến thư viện mượn sách trước, sau đó đi bơi.”","words":["我","要","先","去","图书馆","借书","，","然后","去","游泳","。"],"answer":"我要先去图书馆借书，然后去游泳。","explanation":"先 + 去图书馆借书，然后 + 去游泳."},{"type":"sort","context":"Sắp xếp: “Bạn đi mua vé vào cửa trước, rồi hãy đến đây tìm mình.”","words":["你","先","去","买","门票","，","再","来","这里","找我","。"],"answer":"你先去买门票，再来这里找我。","explanation":"再 + 来."},{"type":"sort","context":"Sắp xếp: “Chúng ta ăn cơm trước rồi đi xem phim nhé.”","words":["我们","先","吃饭","，","然后","去","看","电影","吧","。"],"answer":"我们先吃饭，然后去看电影吧。","explanation":"吧 đề nghị (ôn HSK1 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Con làm bài tập trước, rồi hãy xem tivi.”","words":["你","先","写","作业","，","再","看","电视","。"],"answer":"你先写作业，再看电视。","explanation":"作业 (ôn HSK3 Bài 10)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 先……，然后…….","promptLang":"vi","prompt":"Tôi về nhà nghỉ một lát trước, sau đó đi siêu thị.","answer":"我先回家休息一会儿，然后去超市。","answerPy":"Wǒ xiān huí jiā xiūxi yíhuìr, ránhòu qù chāoshì.","explanation":"一会儿 (ôn HSK2 Bài 5); 超市 (ôn HSK1 Bài 6)."}]},{"point":"Cấu trúc cố định 「× 什么（啊）」 — phản bác, an ủi","items":[{"context":"Sách: A: 这个地方太远了，走过去要很久。 B: “… , đi bộ mười mấy phút là đến.”","pre":"","blank":"远什么啊","post":"，走路十几分钟就到了。","options":["远什么啊","什么远啊","很远什么啊"],"answer":0,"explanation":"× = 远, lặp lại từ câu A; 走路 (ôn HSK2 Bài 9), 久 (ôn HSK3 Bài 4)."},{"context":"Sách: A: 这家饭馆的菜挺贵的，咱们换一家吧。 B: …","pre":"","blank":"贵什么啊","post":"，今天你生日，想吃什么就吃什么。","options":["贵什么啊","什么贵啊","贵不贵啊"],"answer":0,"explanation":"想吃什么就吃什么 (ôn HSK3 Bài 2); 换 (ôn HSK3 Bài 3)."},{"context":"Sách: A: 明天就要考试了，我好紧张。 B: …","pre":"","blank":"紧张什么啊","post":"，我们都相信你。","options":["紧张什么啊","什么紧张啊","紧张吗"],"answer":0,"explanation":"紧张 (ôn HSK3 Bài 9); 相信 của bài này."},{"context":"A: 我最近胖了很多，不想拍照了。 B: “Béo gì mà béo, …”","pre":"","blank":"胖什么啊","post":"，你看起来不胖也不瘦。","options":["胖什么啊","什么胖啊","胖了什么啊"],"answer":0,"explanation":"看起来 (ôn HSK3 Bài 1); 胖 (ôn HSK3 Bài 8)."},{"context":"A: 还有十分钟，快点儿走吧。 B: “Vội gì chứ, …”","pre":"","blank":"急什么啊","post":"，马上就到了。","options":["急什么啊","什么急啊","很急什么啊"],"answer":0,"explanation":"急 (ôn HSK3 Bài 6); 马上 (ôn HSK3 Bài 2)."},{"context":"A: 这个题太难了，我不会做。 B: “Khó gì mà khó, …”","pre":"","blank":"难什么啊","post":"，老师上课讲过，你再想想。","options":["难什么啊","什么难啊","很难什么啊"],"answer":0,"explanation":"难, 讲 (ôn HSK3 Bài 10)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"什么冷啊，今天一点儿也不冷。","isCorrect":false,"correctVersion":"冷什么啊，今天一点儿也不冷。","explanation":"× (冷) phải đứng trước 什么."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"A: 这件衣服太贵了。B: 贵什么啊，才一百块。","isCorrect":true,"explanation":"Đúng: phản bác ý “đắt”; 才 = chỉ có (ôn HSK3 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Có gì mà phải căng thẳng chứ, bạn phải tin vào bản thân.”","words":["紧张","什么","啊","，","你","要","相信","自己","。"],"answer":"紧张什么啊，你要相信自己。","explanation":"紧张什么啊 + lời động viên."},{"type":"sort","context":"Sắp xếp: “Vội gì chứ, sắp đến nơi rồi.”","words":["急","什么","啊","，","马上","就","到","了","。"],"answer":"急什么啊，马上就到了。","explanation":"马上就……了 (ôn HSK3 Bài 2)."},{"type":"sort","context":"Sắp xếp: “Đắt gì mà đắt, quán này rất rẻ.”","words":["贵","什么","啊","，","这家","饭馆","很","便宜","。"],"answer":"贵什么啊，这家饭馆很便宜。","explanation":"便宜 (ôn HSK1 Bài 10); 饭馆 (ôn HSK2 Bài 8)."},{"type":"sort","context":"Sắp xếp: “Xa gì mà xa, đi bộ mười phút là đến.”","words":["远","什么","啊","，","走路","十","分钟","就","到","了","。"],"answer":"远什么啊，走路十分钟就到了。","explanation":"远 (ôn HSK2 Bài 2); 就 (ôn HSK2 Bài 1)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng “× 什么啊”.","promptLang":"vi","prompt":"(A: Mình mệt quá.) Mệt gì mà mệt, chúng ta mới đi được mười phút thôi.","answer":"累什么啊，我们才走了十分钟。","answerPy":"Lèi shénme a, wǒmen cái zǒule shí fēnzhōng.","explanation":"才 = mới (ôn HSK3 Bài 3); 累 (ôn HSK2 Bài 3)."}]}],"/lessons/hsk3v3-bai-15.html":[{"point":"Giới từ 「根据」 — 根据 + căn cứ, chủ ngữ + động từ","items":[{"context":"Sách: “Chúng tôi sẽ căn cứ vào thời gian của mọi người để quyết định mua vé máy bay giờ nào.”","pre":"我们会","blank":"根据大家的时间","post":"决定买什么时候的机票。","options":["根据大家的时间","大家的时间根据","在大家的时间"],"answer":0,"explanation":"根据 + N đứng trước động từ 决定 (ôn HSK3 Bài 7); 机票 (ôn HSK2 Bài 15)."},{"context":"Sách: “Bạn nên căn cứ vào thời tiết để chọn quần áo phù hợp.”","pre":"你应该","blank":"根据天气","post":"选择合适的衣服。","options":["根据天气","天气根据","对天气"],"answer":0,"explanation":"根据 + 天气 + V; 应该 (ôn HSK3 Bài 1), 合适 (ôn HSK3 Bài 7), 选择 (ôn HSK3 Bài 6)."},{"context":"Sách: “Cô giáo sẽ căn cứ vào trình độ của từng học sinh để giao bài tập khác nhau.”","pre":"老师会","blank":"根据每个学生的水平","post":"，给每个学生不同的作业。","options":["根据每个学生的水平","每个学生的水平根据","根据每个学生"],"answer":0,"explanation":"根据 + định ngữ + danh từ (水平 – ôn HSK3 Bài 5), không nói 根据 + người; 作业 (ôn HSK3 Bài 10)."},{"context":"“Thầy nói: theo yêu cầu, chúng ta đều phải tham gia cuộc thi ngày mai.”","pre":"老师说，","blank":"根据要求","post":"，我们都必须参加明天的比赛。","options":["根据要求","要求根据","在要求"],"answer":0,"explanation":"根据 đứng đầu vế câu, sau là dấu phẩy; 必须 (ôn HSK3 Bài 6), 参加、比赛 (ôn HSK3 Bài 9)."},{"context":"“Thầy cô căn cứ vào sở thích của từng học sinh, đã chọn những cuốn sách khác nhau.”","pre":"老师","blank":"根据","post":"每个学生的兴趣，选择了不一样的书。","options":["根据","了解","经过"],"answer":0,"explanation":"根据 + 兴趣 (ôn HSK3 Bài 5); 不一样 (ôn HSK3 Bài 4)."},{"context":"“Mấy năm nay khu dân cư căn cứ vào nhu cầu của người già, đã có nhiều thay đổi.”","pre":"这几年小区根据老人的","blank":"需要","post":"，有了很多变化。","options":["需要","帮助","影响"],"answer":0,"explanation":"根据 + nhu cầu (需要 – ôn HSK3 Bài 3); 帮助 / 影响 đi với khung 在……下 (ôn HSK3 Bài 10), không đi với 根据."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"小区有了很多变化根据他们的需要。","isCorrect":false,"correctVersion":"小区根据他们的需要，有了很多变化。","explanation":"Cụm 根据 + N phải đứng trước động từ hoặc ở đầu câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们根据天气决定明天去不去爬山。","isCorrect":true,"explanation":"Đúng: 根据 + 天气 + 决定……; 爬山 (ôn HSK3 Bài 5), câu hỏi chính phản 去不去."},{"type":"sort","context":"Sắp xếp: “Theo yêu cầu, chúng ta phải đến trước 8 giờ.”","words":["根据","要求","，","我们","必须","八点","以前","到","。"],"answer":"根据要求，我们必须八点以前到。","explanation":"根据 đầu câu; ……以前 (ôn HSK3 Bài 8), 必须 (ôn HSK3 Bài 6)."},{"type":"sort","context":"Sắp xếp: “Bạn có thể chọn theo sở thích của mình.”","words":["你","可以","根据","自己的","兴趣","来","选择","。"],"answer":"你可以根据自己的兴趣来选择。","explanation":"Câu 选词填空 của sách; 根据……来 + V; 自己 (ôn HSK2 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Mấy năm nay khu dân cư căn cứ nhu cầu của họ, đã có rất nhiều thay đổi.”","words":["这几年","小区","根据","他们的","需要","，","有了","很多","变化","。"],"answer":"这几年小区根据他们的需要，有了很多变化。","explanation":"Câu của Bài khoá 1: chủ ngữ + 根据 + N, động từ."},{"type":"sort","context":"Sắp xếp: “Mẹ căn cứ vào thời tiết chuẩn bị quần áo cho tôi.”","words":["妈妈","根据","天气","给我","准备","衣服","。"],"answer":"妈妈根据天气给我准备衣服。","explanation":"准备 (ôn HSK2 Bài 5); 给 + người + V (ôn HSK2 Bài 1)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng giới từ 根据.","promptLang":"vi","prompt":"Căn cứ vào thành tích, cô giáo đã chọn ba bạn tham gia cuộc thi.","answer":"根据成绩，老师选了三个同学参加比赛。","answerPy":"Gēnjù chéngjì, lǎoshī xuǎnle sān ge tóngxué cānjiā bǐsài.","explanation":"成绩、参加、比赛 (ôn HSK3 Bài 9); 选 (ôn HSK3 Bài 2)."}]},{"point":"Cụm số lượng lặp lại 「số từ + lượng từ + số từ + lượng từ (+ 地) + động từ」","items":[{"context":"Sách (完成对话, 本): A: Con gái chị có thích đọc sách ngoại ngữ không? B: “Thích, tuy hơi khó nhưng cháu đọc từng quyển một, đã đọc xong hơn mười quyển rồi.”","pre":"喜欢，虽然有点儿难，她","blank":"一本一本地看","post":"，已经看完十多本了。","options":["一本一本地看","看一本一本地","本本地看"],"answer":0,"explanation":"Số + lượng + số + lượng + (地) + V; 本本 = quyển nào cũng (ôn HSK3 Bài 5); 虽然 (ôn HSK2 Bài 8)."},{"context":"Sách (完成对话, 张): A: Bây giờ bạn chọn được dùng tấm ảnh nào chưa? B: “Đừng vội, mình phải xem từng tấm một.”","pre":"别着急，我要","blank":"一张一张地看","post":"。","options":["一张一张地看","看一张一张","张张地看"],"answer":0,"explanation":"一张一张地 + V; 着急 (ôn HSK3 Bài 1), 张 (ôn HSK3 Bài 2)."},{"context":"Sách (完成对话, 个): A: Nhiều bài tập thế này, bao giờ mới làm xong? B: “Làm từng bài một, từ từ sẽ xong thôi.”","pre":"","blank":"一个一个地做","post":"，慢慢就做完了。","options":["一个一个地做","做一个一个地","个个地做"],"answer":0,"explanation":"一个一个地 + 做; 慢慢 + V (ôn HSK2 Bài 11 慢); 做完 bổ ngữ kết quả."},{"context":"“Trình độ tiếng Trung của học sinh đã nâng cao lên từng ngày.”","pre":"学生们的汉语水平","blank":"一天一天地","post":"提高了。","options":["一天一天地","天天地","一天地"],"answer":0,"explanation":"一天一天地 = từng ngày một (thay đổi dần dần); 天天 = ngày nào cũng (ôn HSK3 Bài 5); 提高 (ôn HSK3 Bài 10)."},{"context":"“Vậy thì nhiều lắm, em phải kể cho chị từng chút một.”","pre":"那太多了，我得","blank":"一点儿一点儿","post":"给您讲。","options":["一点儿一点儿","一点儿","点儿点儿"],"answer":0,"explanation":"一点儿一点儿 = từng chút một; 得 děi (ôn HSK3 Bài 8), 讲 (ôn HSK3 Bài 10)."},{"context":"“Họ đi vào từng tốp hai người một.”","pre":"他们","blank":"两个两个地","post":"走进去了。","options":["两个两个地","两个地","个个地"],"answer":0,"explanation":"Cụm lặp đứng trước động từ; 走进去 — bổ ngữ xu hướng (ôn HSK2 Bài 4)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他们走进去两个两个地。","isCorrect":false,"correctVersion":"他们两个两个地走进去了。","explanation":"Cụm số lượng lặp lại làm trạng ngữ, phải đứng trước động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"请大家一个一个地说，别着急。","isCorrect":true,"explanation":"Đúng: 一个一个地 + 说; 别着急 (ôn HSK3 Bài 1, HSK2 Bài 2)."},{"type":"sort","context":"Sắp xếp: “Mình phải giảng cho bạn từng chút một.”","words":["我","得","一点儿","一点儿","给你","讲","。"],"answer":"我得一点儿一点儿给你讲。","explanation":"得 + cụm lặp + 给 + người + 讲."},{"type":"sort","context":"Sắp xếp: “Trình độ tiếng Trung của học sinh nâng cao lên từng ngày.”","words":["学生们的","汉语","水平","一天一天地","提高了","。"],"answer":"学生们的汉语水平一天一天地提高了。","explanation":"水平 (ôn HSK3 Bài 5); cụm lặp đứng trước 提高."},{"type":"sort","context":"Sắp xếp: “Các bạn nhỏ lần lượt từng người một đi vào lớp học.”","words":["小朋友们","一个一个地","走进了","教室","。"],"answer":"小朋友们一个一个地走进了教室。","explanation":"小朋友 (ôn HSK1 Bài 11); 教室 (ôn HSK2 Bài 2)."},{"type":"sort","context":"Sắp xếp: “Cô ấy xem từng tấm ảnh một lượt.”","words":["她","把","照片","一张一张地","看了","一遍","。"],"answer":"她把照片一张一张地看了一遍。","explanation":"Câu chữ 把 + cụm lặp + V (ôn HSK3 Bài 10); 遍 (ôn HSK3 Bài 10)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng cụm số lượng lặp lại.","promptLang":"vi","prompt":"Chúng mình làm từng bài một nhé, đừng vội.","answer":"咱们一个一个地做吧，别着急。","answerPy":"Zánmen yí ge yí ge de zuò ba, bié zháojí.","explanation":"咱们 (ôn HSK3 Bài 3); 别着急 (ôn HSK3 Bài 1)."}]},{"point":"Cấu trúc cố định 「在……看来」","items":[{"context":"Sách (完成句子): “Theo tôi, thời gian quan trọng hơn tiền bạc.”","pre":"","blank":"在我看来","post":"，时间比钱更重要。","options":["在我看来","在我看","我看来在"],"answer":0,"explanation":"在 + người + 看来; câu so sánh 比……更…… (ôn HSK2 Bài 8, HSK3 Bài 7)."},{"context":"Sách (完成句子): “Theo bác sĩ, vận động mỗi ngày rất tốt cho sức khỏe.”","pre":"","blank":"在医生看来","post":"，每天运动对身体很好。","options":["在医生看来","根据医生","医生在看来"],"answer":0,"explanation":"Nêu ý kiến của ai dùng 在……看来, không dùng 根据 + người; 运动 (ôn HSK2 Bài 7)."},{"context":"Sách (完成句子): “Trong mắt du khách, môi trường của thành phố này vô cùng tốt.”","pre":"","blank":"在游客们看来","post":"，这个城市的环境非常好。","options":["在游客们看来","在游客们看","游客们在看来"],"answer":0,"explanation":"游客 của bài này; 环境 (ôn HSK3 Bài 3)."},{"context":"“Trong mắt các đồng nghiệp, cô ấy làm việc vô cùng chăm chỉ.”","pre":"在同事们","blank":"看来","post":"，她工作非常认真。","options":["看来","看","来看"],"answer":0,"explanation":"Khung 在……看来 phải đủ 看来; 认真 (ôn HSK3 Bài 10)."},{"context":"“Theo tôi, đọc sách mỗi ngày là một thói quen rất tốt.”","pre":"","blank":"在我看来","post":"，每天读书是一种很好的习惯。","options":["在我看来","我看来","在我的看"],"answer":0,"explanation":"习惯、种 (ôn HSK3 Bài 8); 读书 (ôn HSK1 Bài 9)."},{"context":"“Đối với người Trung Quốc chúng ta, sông Hoàng Hà giống như mẹ.”","pre":"","blank":"在我们中国人看来","post":"，黄河像妈妈一样。","options":["在我们中国人看来","我们中国人在看来","在看来我们中国人"],"answer":0,"explanation":"Câu của Bài khoá 3; A 像 B 一样 (ôn HSK3 Bài 1, Bài 4)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在我看来，我觉得时间比钱更重要。","isCorrect":false,"correctVersion":"在我看来，时间比钱更重要。","explanation":"在我看来 đã nêu ý kiến, không thêm 我觉得."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在爷爷看来，每天早上锻炼身体是最好的习惯。","isCorrect":true,"explanation":"Đúng: 在 + 爷爷 + 看来; 锻炼 (ôn HSK3 Bài 5), 爷爷 (ôn HSK2 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Theo tôi, đọc sách mỗi ngày là một thói quen rất tốt.”","words":["在","我","看来","，","每天","读书","是","一种","很好的","习惯","。"],"answer":"在我看来，每天读书是一种很好的习惯。","explanation":"在 + 我 + 看来，quan điểm."},{"type":"sort","context":"Sắp xếp: “Trong mắt mẹ, việc học là quan trọng nhất.”","words":["在","妈妈","看来","，","学习","是","最","重要的","。"],"answer":"在妈妈看来，学习是最重要的。","explanation":"最 (ôn HSK2 Bài 11); 重要 (ôn HSK3 Bài 1)."},{"type":"sort","context":"Sắp xếp: “Theo các bạn học, bài kiểm tra lần này chẳng khó chút nào.”","words":["在","同学们","看来","，","这次","考试","一点儿","也","不难","。"],"answer":"在同学们看来，这次考试一点儿也不难。","explanation":"一点儿也不 + Adj (ôn HSK3 Bài 4); 考试 (ôn HSK2 Bài 10)."},{"type":"sort","context":"Sắp xếp: “Theo các cụ già, khu dân cư này rất thuận tiện.”","words":["在","老人们","看来","，","这个","小区","非常","方便","。"],"answer":"在老人们看来，这个小区非常方便。","explanation":"老人 của bài này; 方便 (ôn HSK3 Bài 2)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 在……看来.","promptLang":"vi","prompt":"Theo tôi, sống ở thành phố nhỏ thoải mái hơn sống ở thành phố lớn.","answer":"在我看来，住在小城市比住在大城市舒服。","answerPy":"Zài wǒ kànlái, zhù zài xiǎo chéngshì bǐ zhù zài dà chéngshì shūfu.","explanation":"Câu so sánh 比 (ôn HSK2 Bài 8); 舒服 (ôn HSK2 Bài 6)."}]},{"point":"Cụm từ cố định 「不一会儿」 — 不一会儿 + (chủ ngữ) + 就 + V + 了","items":[{"context":"Sách (完成句子): “Tôi chỉ định xem nửa tiếng ti vi, nhưng chẳng mấy chốc một tiếng đã trôi qua.”","pre":"我只想看半个小时电视，可是","blank":"不一会儿","post":"一个小时就过去了。","options":["不一会儿","一会儿","一会儿不"],"answer":0,"explanation":"不一会儿 + 就……了 — thời gian trôi rất nhanh; 只 (ôn HSK3 Bài 2), 半 (ôn HSK1 Bài 7)."},{"context":"Sách (完成句子): “Họ đứng chờ ở cổng, chẳng mấy chốc taxi đã đến.”","pre":"他们在门口站着，出租车","blank":"不一会儿就来了","post":"。","options":["不一会儿就来了","来了不一会儿","一会儿不来了"],"answer":0,"explanation":"Chủ ngữ + 不一会儿 + 就 + V + 了; V + 着 (ôn HSK2 Bài 11), 门口 (ôn HSK2 Bài 9)."},{"context":"Sách (完成句子): “Chúng tôi ngồi trong phòng họp, một lát sau thầy giáo đã đến.”","pre":"我们坐在会议室里，","blank":"不一会儿，老师就来了","post":"。","options":["不一会儿，老师就来了","老师来了不一会儿","不一会儿，老师就来"],"answer":0,"explanation":"不一会儿 đứng đầu vế câu, sau là 就……了 (việc đã xảy ra)."},{"context":"“Một lát sau, hiệu trưởng Trương đã đến.”","pre":"","blank":"不一会儿","post":"，张校长就来了。","options":["不一会儿","一会儿不","不会一儿"],"answer":0,"explanation":"Cụm cố định 不一会儿, không tách hay đảo chữ."},{"context":"“Hai tiếng nghe có vẻ dài, nhưng chẳng mấy chốc đã trôi qua.”","pre":"两个小时看起来长，但是不一会儿","blank":"就","post":"过去了。","options":["就","才","再"],"answer":0,"explanation":"不一会儿 hay đi với 就 (sớm, nhanh); 才 = muộn, chậm (ôn HSK3 Bài 3); 看起来 (ôn HSK3 Bài 1)."},{"context":"“Mẹ nấu rất nhiều món, chẳng mấy chốc chúng tôi đã ăn hết.”","pre":"妈妈做了很多菜，","blank":"不一会儿我们就吃完了","post":"。","options":["不一会儿我们就吃完了","我们吃完了不一会儿","我们不一会儿吃完"],"answer":0,"explanation":"吃完 — bổ ngữ kết quả (ôn HSK2 Bài 3); 不一会儿 + 就 + V + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你等一下，我不一会儿就回来。","isCorrect":false,"correctVersion":"你等一下，我一会儿就回来。","explanation":"不一会儿 dùng khi kể lại việc đã xảy ra; nói việc sắp làm dùng 一会儿 / 马上 (ôn HSK2 Bài 5, HSK3 Bài 2)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们聊了几句，不一会儿就到家了。","isCorrect":true,"explanation":"Đúng: 不一会儿 + 就 + V + 了; 聊 của bài này, 句 (ôn HSK3 Bài 10)."},{"type":"sort","context":"Sắp xếp: “Những chuyện buồn chẳng mấy chốc là quên hết.”","words":["难过的","事情","不一会儿","就","忘了","。"],"answer":"难过的事情不一会儿就忘了。","explanation":"Câu của Bài khoá 4; 难过 (ôn HSK3 Bài 5), 忘 (ôn HSK2 Bài 6)."},{"type":"sort","context":"Sắp xếp: “Một lát sau, hiệu trưởng Trương đã đến.”","words":["不一会儿","，","张校长","就","来了","。"],"answer":"不一会儿，张校长就来了。","explanation":"不一会儿 ở đầu câu, có dấu phẩy."},{"type":"sort","context":"Sắp xếp: “Chúng tôi vừa ăn vừa trò chuyện, chẳng mấy chốc đã 10 giờ.”","words":["我们","边吃边聊","，","不一会儿","就","十点","了","。"],"answer":"我们边吃边聊，不一会儿就十点了。","explanation":"边……边…… (ôn HSK3 Bài 13); 就……了."},{"type":"sort","context":"Sắp xếp: “Bạn tôi đạp xe đến, một lát sau đã tới nơi.”","words":["朋友","骑","自行车","来","，","不一会儿","就","到了","。"],"answer":"朋友骑自行车来，不一会儿就到了。","explanation":"骑 (ôn HSK3 Bài 4), 自行车 (ôn HSK3 Bài 7); câu liên động (ôn HSK3 Bài 7)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 不一会儿.","promptLang":"vi","prompt":"Bài tập hôm nay rất đơn giản, chẳng mấy chốc tôi đã làm xong.","answer":"今天的作业很简单，我不一会儿就写完了。","answerPy":"Jīntiān de zuòyè hěn jiǎndān, wǒ bù yíhuìr jiù xiěwán le.","explanation":"简单 (ôn HSK3 Bài 2); 作业 (ôn HSK3 Bài 10); 写完 — bổ ngữ kết quả."}]}],"/lessons/hsk3v3-bai-16.html":[{"point":"Câu ghép đẳng lập 「一会儿……，一会儿……」 — lúc thì…, lúc thì…","items":[{"context":"Sách (完成句子): “Suy nghĩ của cô ấy luôn thay đổi, lúc thì nói muốn học vẽ, lúc thì nói muốn học múa.”","pre":"她的想法总是变，","blank":"一会儿说想学画画","post":"，一会儿说想学跳舞。","options":["一会儿说想学画画","说想学画画一会儿","一下儿说想学画画"],"answer":0,"explanation":"一会儿 + V, hai vế đối nhau; 总是 (ôn HSK3 Bài 5), 画 (ôn HSK2 Bài 6), 跳舞 (ôn HSK2 Bài 14)."},{"context":"Sách (完成句子): “Ở hội thao, cậu ấy lúc thì tham gia thi chạy, lúc thì tham gia thi bơi.”","pre":"运动会上，他一会儿参加跑步比赛，","blank":"一会儿参加游泳比赛","post":"。","options":["一会儿参加游泳比赛","也一会儿参加游泳比赛","参加游泳比赛一会儿"],"answer":0,"explanation":"运动会、参加、比赛 (ôn HSK3 Bài 9); 跑步、游泳 (ôn HSK2 Bài 7)."},{"context":"Sách (完成句子): “Con mèo này rất đáng yêu, lúc thì nằm ngủ trên sofa, lúc thì chơi cạnh chân tôi.”","pre":"这只猫很可爱，一会儿躺在沙发上睡觉，","blank":"一会儿在我脚边玩","post":"。","options":["一会儿在我脚边玩","在我脚边玩一会儿","一下儿在我脚边玩"],"answer":0,"explanation":"沙发 (ôn HSK3 Bài 6); 脚、可爱 của bài này."},{"context":"Sách (miêu tả tranh): “Hôm nay có mấy chú mèo ốm mới đến, lúc thì đòi ăn, lúc thì đòi uống nước.”","pre":"今天新来了几只生病的小猫，一会儿要吃东西，","blank":"一会儿要喝水","post":"。","options":["一会儿要喝水","要喝水一会儿","也一会儿要喝水"],"answer":0,"explanation":"Bài miêu tả tranh của sách; 生病 (ôn HSK1 Bài 12), 只 (ôn HSK1 Bài 8)."},{"context":"“Dạo này thời tiết thay đổi rất nhanh, lúc thì lạnh, lúc thì nóng.”","pre":"最近天气变化很快，","blank":"一会儿冷，一会儿热","post":"。","options":["一会儿冷，一会儿热","一会儿冷，一下儿热","冷一会儿，热一会儿"],"answer":0,"explanation":"Sau 一会儿 có thể là tính từ; 变化 (ôn HSK3 Bài 12), 最近 (ôn HSK3 Bài 8)."},{"context":"“Anh ấy lúc thì đi vào, lúc thì đi ra, bận lắm.”","pre":"他一会儿进来，一会儿","blank":"出去","post":"，忙得很。","options":["出去","出去一会儿","一下儿出去"],"answer":0,"explanation":"进来 / 出去 — bổ ngữ xu hướng (ôn HSK2 Bài 4, 5); 忙得很 — bổ ngữ trình độ (ôn HSK3 Bài 3)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"最近天气一会儿冷，一下儿热。","isCorrect":false,"correctVersion":"最近天气一会儿冷，一会儿热。","explanation":"Hai vế phải cùng dùng 一会儿."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"孩子们一会儿唱歌，一会儿跳舞，高兴极了。","isCorrect":true,"explanation":"Đúng: 一会儿 + V1，一会儿 + V2; 唱歌 (ôn HSK1 Bài 9), 极了 (ôn HSK3 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Nó lúc thì ngủ cạnh chân bạn, lúc thì trèo lên người bạn.”","words":["它","一会儿","在你脚边","睡觉","，","一会儿","在你身上","爬","。"],"answer":"它一会儿在你脚边睡觉，一会儿在你身上爬。","explanation":"Câu của Bài khoá 1; 爬 (ôn HSK3 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Chú gấu trúc này lúc thì trèo lên, lúc thì nhảy xuống.”","words":["这只","大熊猫","一会儿","爬上去","，","一会儿","跳下来","。"],"answer":"这只大熊猫一会儿爬上去，一会儿跳下来。","explanation":"Câu của Bài khoá 3; 跳 (ôn HSK3 Bài 14), 上去 / 下来 (ôn HSK2 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Em trai lúc thì xem ti vi, lúc thì chơi game.”","words":["弟弟","一会儿","看电视","，","一会儿","玩游戏","。"],"answer":"弟弟一会儿看电视，一会儿玩游戏。","explanation":"游戏 (ôn HSK3 Bài 15); 电视 (ôn HSK1 Bài 9)."},{"type":"sort","context":"Sắp xếp: “Trời lúc thì nắng, lúc thì mưa.”","words":["天","一会儿","晴","，","一会儿","下雨","。"],"answer":"天一会儿晴，一会儿下雨。","explanation":"晴 (ôn HSK2 Bài 12); 下雨 (ôn HSK1 Bài 12)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 一会儿……，一会儿…….","promptLang":"vi","prompt":"Mẹ lúc thì nấu cơm, lúc thì dọn phòng, bận suốt cả buổi sáng.","answer":"妈妈一会儿做饭，一会儿打扫房间，忙了一个上午。","answerPy":"Māma yíhuìr zuò fàn, yíhuìr dǎsǎo fángjiān, mángle yí ge shàngwǔ.","explanation":"做饭 (ôn HSK1 Bài 5); 打扫 (ôn HSK3 Bài 3); bổ ngữ thời lượng 忙了一个上午 (ôn HSK3 Bài 8)."}]},{"point":"Giới từ 「关于」 — 关于 + N，……  /  关于 + N + 的 + danh từ","items":[{"context":"Sách (完成句子): “Về chuyến du lịch ngày mai, tôi còn có một vài câu hỏi muốn hỏi bạn.”","pre":"","blank":"关于明天的旅游","post":"，我还有一些问题想问你。","options":["关于明天的旅游","明天的旅游关于","我关于明天的旅游"],"answer":0,"explanation":"关于 + N đứng đầu câu, có dấu phẩy; 旅游 (ôn HSK2 Bài 1), 问题 (ôn HSK1 Bài 13)."},{"context":"Sách (完成句子): “Giám đốc muốn nói chuyện với bạn về việc bạn xin nghỉ.”","pre":"经理要跟你谈一谈","blank":"关于你请假","post":"的事情。","options":["关于你请假","你请假关于","根据你请假"],"answer":0,"explanation":"关于 + N + 的 + 事情 làm định ngữ; 经理、请假 (ôn HSK3 Bài 11); 根据 = căn cứ (ôn HSK3 Bài 15)."},{"context":"Sách (完成句子): “Bạn đi tìm thầy Lý đi, thầy ấy có thể cho bạn biết một vài phương pháp học tiếng Trung.”","pre":"你去找李老师吧，他可以告诉你一些","blank":"关于学习汉语","post":"的方法。","options":["关于学习汉语","学习汉语关于","在学习汉语"],"answer":0,"explanation":"方法 (ôn HSK3 Bài 8); 告诉 (ôn HSK2 Bài 13)."},{"context":"“Về vấn đề này, mẹ phải từ từ kể cho con nghe.”","pre":"","blank":"关于","post":"这个问题，我得慢慢给你讲。","options":["关于","根据","在"],"answer":0,"explanation":"关于 dẫn ra nội dung được nói đến; 根据 = căn cứ vào (ôn HSK3 Bài 15); 得 děi (ôn HSK3 Bài 8)."},{"context":"“Về yêu cầu của anh ấy, chúng ta còn phải họp xong rồi mới quyết định.”","pre":"","blank":"关于他的要求","post":"，我们还要开会以后再决定。","options":["关于他的要求","他的要求关于","我们关于他的要求"],"answer":0,"explanation":"要求 (ôn HSK3 Bài 10); 开会 (ôn HSK3 Bài 11); ……以后再 + V (ôn HSK3 Bài 8)."},{"context":"“Tôi muốn mượn một cuốn sách về động vật.”","pre":"我想借一本","blank":"关于动物的","post":"书。","options":["关于动物的","关于动物","动物关于的"],"answer":0,"explanation":"Làm định ngữ phải có 的; 借 (ôn HSK3 Bài 12)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我关于这件事还不太了解。","isCorrect":false,"correctVersion":"关于这件事，我还不太了解。","explanation":"Cụm 关于 làm trạng ngữ phải đứng đầu câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"关于比赛的时间，我明天一定告诉大家。","isCorrect":true,"explanation":"Đúng: 关于 + N đứng đầu câu; 比赛 (ôn HSK3 Bài 9), 一定 (ôn HSK3 Bài 4)."},{"type":"sort","context":"Sắp xếp: “Về vấn đề này, mẹ phải từ từ kể cho con nghe.”","words":["关于","这个问题","，","我","得","慢慢","给你","讲","。"],"answer":"关于这个问题，我得慢慢给你讲。","explanation":"Câu của Bài khoá 2; 讲 (ôn HSK3 Bài 10)."},{"type":"sort","context":"Sắp xếp: “Tôi muốn đọc một cuốn sách về lịch sử Trung Quốc.”","words":["我","想看","一本","关于","中国历史","的","书","。"],"answer":"我想看一本关于中国历史的书。","explanation":"历史 (ôn HSK3 Bài 10)."},{"type":"sort","context":"Sắp xếp: “Về thời gian thi đấu, ngày mai tôi nhất định báo cho mọi người.”","words":["关于","比赛的","时间","，","我","明天","一定","告诉","大家","。"],"answer":"关于比赛的时间，我明天一定告诉大家。","explanation":"一定 (ôn HSK3 Bài 4); 告诉 (ôn HSK2 Bài 13)."},{"type":"sort","context":"Sắp xếp: “Cô giáo cho chúng tôi xem một video về gấu trúc.”","words":["老师","给我们","看了","一个","关于","大熊猫的","视频","。"],"answer":"老师给我们看了一个关于大熊猫的视频。","explanation":"视频 (ôn HSK3 Bài 14)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 关于.","promptLang":"vi","prompt":"Về chuyện chuyển nhà, cuối tuần chúng ta hãy bàn tiếp nhé.","answer":"关于搬家的事情，我们周末再说吧。","answerPy":"Guānyú bānjiā de shìqing, wǒmen zhōumò zài shuō ba.","explanation":"搬家 (ôn HSK3 Bài 3); 事情 (ôn HSK2 Bài 12); 周末 của bài này."}]},{"point":"Cụm từ cố định 「一般来说」 — nói chung, thông thường","items":[{"context":"Sách (完成对话): A: Bạn thích tập thể dục buổi sáng hay buổi tối? B: “Nói chung là buổi sáng, vì buổi sáng tôi dậy rất sớm.”","pre":"","blank":"一般来说，我早上锻炼","post":"，因为我早上起床起得很早。","options":["一般来说，我早上锻炼","我一般来说早上锻炼","经常来说，我早上锻炼"],"answer":0,"explanation":"锻炼 (ôn HSK3 Bài 5); 还是 trong câu hỏi lựa chọn (ôn HSK3 Bài 11); 起床起得很早 — lặp động từ + bổ ngữ trình độ."},{"context":"Sách (完成对话): A: Bạn thấy lúc tan làm đi tàu điện ngầm hay đi taxi nhanh hơn? B: “Nói chung đi tàu điện ngầm nhanh hơn.”","pre":"","blank":"一般来说，坐地铁更快","post":"。","options":["一般来说，坐地铁更快","坐地铁一般来说更快的","一般来说，坐地铁快更"],"answer":0,"explanation":"更 + Adj (ôn HSK2 Bài 4); 地铁 (ôn HSK2 Bài 12), 出租车 (ôn HSK1 Bài 6)."},{"context":"Sách (完成对话): A: Cuối tuần bạn thích làm gì? B: “Thông thường, cuối tuần tôi thích ở nhà đọc sách.”","pre":"","blank":"一般来说，周末我喜欢在家看书","post":"。","options":["一般来说，周末我喜欢在家看书","周末我一般来说喜欢在家看书","一般来说，周末我喜欢看书在家"],"answer":0,"explanation":"在 + nơi chốn + V (ôn HSK1 Bài 7); 周末 của bài này."},{"context":"“Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều giấc.”","pre":"","blank":"一般来说","post":"，熊猫每天要睡很多次觉。","options":["一般来说","一会儿","关于"],"answer":0,"explanation":"Câu của Bài khoá 3; 睡觉 là từ ly hợp: 睡很多次觉 (ôn HSK3 Bài 8)."},{"context":"“Thông thường, loại cây này mỗi năm ra hoa một lần.”","pre":"一般来说，这种树每年","blank":"开一次花","post":"。","options":["开一次花","开花一次","一次开花"],"answer":0,"explanation":"Từ ly hợp 开花: số lần chen vào giữa (ôn HSK3 Bài 8, 12); 种 (ôn HSK3 Bài 8), 树 (ôn HSK3 Bài 5)."},{"context":"“Nói chung, học ngoại ngữ cần luyện tập nhiều.”","pre":"一般来说，学习外语","blank":"需要多练习","post":"。","options":["需要多练习","需要练习多","多需要练习"],"answer":0,"explanation":"多 + V = làm nhiều hơn; 外语 (ôn HSK3 Bài 10), 练习 (ôn HSK3 Bài 9), 需要 (ôn HSK3 Bài 3)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我一般来说七点起床。","isCorrect":false,"correctVersion":"一般来说，我七点起床。","explanation":"一般来说 đặt đầu câu; hoặc dùng 一般 trước động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"一般来说，北方的冬天比南方冷。","isCorrect":true,"explanation":"Đúng: 一般来说 đầu câu nêu quy luật chung; 北方、南方 (ôn HSK3 Bài 13), câu so sánh 比 (ôn HSK2 Bài 8)."},{"type":"sort","context":"Sắp xếp: “Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều giấc.”","words":["一般来说","，","熊猫","每天","要睡","很多次","觉","。"],"answer":"一般来说，熊猫每天要睡很多次觉。","explanation":"Câu của Bài khoá 3."},{"type":"sort","context":"Sắp xếp: “Thông thường, loại cây này mỗi năm ra hoa một lần.”","words":["一般来说","，","这种树","每年","开","一次","花","。"],"answer":"一般来说，这种树每年开一次花。","explanation":"开花 (ôn HSK3 Bài 12)."},{"type":"sort","context":"Sắp xếp: “Nói chung, học ngoại ngữ cần luyện tập nhiều.”","words":["一般来说","，","学习","外语","需要","多","练习","。"],"answer":"一般来说，学习外语需要多练习。","explanation":"外语 (ôn HSK3 Bài 10)."},{"type":"sort","context":"Sắp xếp: “Nói chung, mùa hè ở đây rất nóng.”","words":["一般来说","，","这里的","夏天","很","热","。"],"answer":"一般来说，这里的夏天很热。","explanation":"夏天 (ôn HSK3 Bài 12); 热 (ôn HSK1 Bài 12)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 一般来说.","promptLang":"vi","prompt":"Nói chung, cuối tuần du khách ở sở thú đông hơn ngày thường.","answer":"一般来说，周末动物园的游客比平时多。","answerPy":"Yìbān lái shuō, zhōumò dòngwùyuán de yóukè bǐ píngshí duō.","explanation":"游客、平时 (ôn HSK3 Bài 15); câu so sánh 比 (ôn HSK2 Bài 8)."}]},{"point":"Câu so sánh (11) 「A 比 B + 多/少/早/晚 + động từ + cụm số lượng」","items":[{"context":"Sách (完成对话): A: Sao hôm nay bạn đến sớm thế? B: “Tôi đi tàu điện ngầm đến, nên đến sớm hơn ngày thường hai mươi phút.”","pre":"我是坐地铁来的，所以","blank":"比平时早到了二十分钟","post":"。","options":["比平时早到了二十分钟","比平时到了早二十分钟","比平时很早到二十分钟"],"answer":0,"explanation":"是……的 nhấn mạnh cách thức (ôn HSK2 Bài 1); 平时 (ôn HSK3 Bài 15)."},{"context":"Sách (完成对话): A: Đã 11 giờ rồi, sao bạn còn chưa ngủ? B: “Mai không phải đi học, tôi muốn ngủ muộn hơn ngày thường một tiếng.”","pre":"明天不上课，我想","blank":"比平时晚睡一个小时","post":"。","options":["比平时晚睡一个小时","比平时睡晚一个小时","晚睡比平时一个小时"],"answer":0,"explanation":"晚 + V + thời lượng; 上课 (ôn HSK1 Bài 7)."},{"context":"Sách (完成对话): A: Chúng ta đến lúc trả tiền thẻ tín dụng rồi. B: “Đúng, tháng này tiêu nhiều hơn tháng trước hai nghìn tệ.”","pre":"对，这个月","blank":"比上个月多花了两千块钱","post":"。","options":["比上个月多花了两千块钱","比上个月花了多两千块钱","比上个月花了两千块钱多"],"answer":0,"explanation":"花 = tiêu tiền (ôn HSK2 Bài 8); 该……了 (ôn HSK3 Bài 6); 信用卡、还 (ôn HSK3 Bài 3)."},{"context":"Sách (miêu tả tranh): “Đã 11 giờ đêm rồi, bạn về muộn hơn trước hai tiếng đấy.”","pre":"已经晚上十一点了，你比以前","blank":"晚回来了两个小时","post":"。","options":["晚回来了两个小时","回来了晚两个小时","很晚回来两个小时"],"answer":0,"explanation":"以前 (ôn HSK3 Bài 6); 回来 (ôn HSK2 Bài 3)."},{"context":"Sách (miêu tả tranh): A: Đã năm giờ rồi, sở thú sắp đóng cửa chưa? B: “Mùa hè đóng cửa muộn hơn mùa đông một tiếng. Chúng ta đi ngay bây giờ.”","pre":"夏天比冬天","blank":"晚关门一个小时","post":"。咱们现在就去。","options":["晚关门一个小时","关门了晚一个小时","很晚关门一个小时"],"answer":0,"explanation":"夏天、冬天 (ôn HSK3 Bài 12); 关门 (关 – ôn HSK3 Bài 3)."},{"context":"“Anh trai ăn nhiều hơn em trai ba cái sủi cảo.”","pre":"哥哥比弟弟","blank":"多","post":"吃了三个饺子。","options":["多","很多","更"],"answer":0,"explanation":"多 đứng trước động từ; không dùng 很多 / 更 trong mẫu này (更 – ôn HSK2 Bài 4)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我比他到了晚十分钟。","isCorrect":false,"correctVersion":"我比他晚到了十分钟。","explanation":"晚 đặt trước động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"今天我比昨天多跑了半个小时。","isCorrect":true,"explanation":"Đúng: 多 + V + thời lượng; 跑 (ôn HSK2 Bài 7), 半 (ôn HSK1 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Mùa đông đóng cửa sớm hơn mùa hè một tiếng.”","words":["冬天","比","夏天","早","关门","一个小时","。"],"answer":"冬天比夏天早关门一个小时。","explanation":"Ví dụ của sách: A 比 B + 早 + V + thời lượng."},{"type":"sort","context":"Sắp xếp: “Anh trai ăn nhiều hơn em trai ba cái sủi cảo.”","words":["哥哥","比","弟弟","多","吃了","三个","饺子","。"],"answer":"哥哥比弟弟多吃了三个饺子。","explanation":"饺子 (ôn HSK1 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Tôi đến muộn hơn anh ấy mười phút.”","words":["我","比","他","晚","到了","十分钟","。"],"answer":"我比他晚到了十分钟。","explanation":"分钟 (ôn HSK1 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Tháng này tôi tiêu ít hơn tháng trước năm trăm tệ.”","words":["这个月","我","比","上个月","少","花了","五百块钱","。"],"answer":"这个月我比上个月少花了五百块钱。","explanation":"块 (ôn HSK1 Bài 10); 花 (ôn HSK2 Bài 8)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu so sánh 比 + 早/晚 + động từ.","promptLang":"vi","prompt":"Hôm nay tôi dậy sớm hơn ngày thường một tiếng.","answer":"今天我比平时早起了一个小时。","answerPy":"Jīntiān wǒ bǐ píngshí zǎo qǐle yí ge xiǎoshí.","explanation":"平时 (ôn HSK3 Bài 15); 起床 (ôn HSK1 Bài 11)."}]}],"/lessons/hsk3v3-bai-17.html":[{"point":"Giới từ 「向」 — 向 + phương hướng / đối tượng + động từ","items":[{"context":"Sách (完成句子): “Nếu có việc không thể lên lớp, bạn nên xin phép thầy cô nghỉ.”","pre":"如果有事不能上课，你就应该","blank":"向老师请假","post":"。","options":["向老师请假","请假向老师","老师向请假"],"answer":0,"explanation":"向 + người + 请假 (请假 – ôn HSK3 Bài 11); 如果……就…… (ôn HSK3 Bài 6)."},{"context":"Sách (完成句子): “Trời đột nhiên mưa, anh ấy vừa xuống xe đã chạy về phía siêu thị đằng trước.”","pre":"突然下雨了，他一下车就","blank":"向前面的超市跑过去了","post":"。","options":["向前面的超市跑过去了","跑过去向前面的超市了","向跑过去前面的超市了"],"answer":0,"explanation":"向 + nơi chốn + V + 过去 (bổ ngữ xu hướng – ôn HSK2 Bài 4); 突然 (ôn HSK3 Bài 8)."},{"context":"Sách (完成句子): “Tôi là người mới đến, những gì chưa hiểu tôi sẽ học hỏi mọi người nhiều.”","pre":"我是新来的，不懂的东西我会多","blank":"向大家学习","post":"。","options":["向大家学习","学习向大家","大家向学习"],"answer":0,"explanation":"多 + 向 + người + 学习; 懂 (ôn HSK2 Bài 1)."},{"context":"“Đừng đi về phía trước nữa, văn phòng cô Lý đến rồi.”","pre":"别再","blank":"向前","post":"走了，李老师的办公室已经到了。","options":["向前","前向","走向"],"answer":0,"explanation":"向 + phương hướng (前、后、左、右) + V; 办公室 (ôn HSK3 Bài 10)."},{"context":"“Đứa bé vừa nhìn thấy mẹ liền chạy về phía mẹ.”","pre":"孩子一看见妈妈，就","blank":"向她跑过去了","post":"。","options":["向她跑过去了","跑过去向她了","她向跑过去了"],"answer":0,"explanation":"向 + người + V + 过去; 一……就…… — vừa… liền…."},{"context":"“Đi về bên trái khoảng 5 phút là đến thư viện.”","pre":"","blank":"向左","post":"走五分钟就到图书馆了。","options":["向左","左向","在左"],"answer":0,"explanation":"向 + 左 / 右 (ôn HSK2 Bài 8) chỉ hướng di chuyển; 图书馆 (ôn HSK3 Bài 14)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"以后我要多学习向认真的人。","isCorrect":false,"correctVersion":"以后我要多向认真的人学习。","explanation":"Cụm 向 + đối tượng phải đứng trước động từ 学习."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"明天我得向经理请一天假。","isCorrect":true,"explanation":"Đúng: 向 + người + 请假; 请假 là từ ly hợp nên chen 一天 vào giữa (ôn HSK3 Bài 8, 11); 经理 (ôn HSK3 Bài 11)."},{"type":"sort","context":"Sắp xếp: “Sau này mình sẽ học hỏi nhiều từ những người cẩn thận.”","words":["以后","我","要","多","向","认真的人","学习","。"],"answer":"以后我要多向认真的人学习。","explanation":"Câu của Bài khoá 1: 多 + 向 + người + 学习."},{"type":"sort","context":"Sắp xếp: “Chúng ta đi về phía trước thêm một chút nữa nhé.”","words":["我们","再","向前","走","一点儿","吧","。"],"answer":"我们再向前走一点儿吧。","explanation":"再 + 向前 + 走; 一点儿 (ôn HSK1 Bài 12)."},{"type":"sort","context":"Sắp xếp: “Bạn nên học hỏi bạn ấy.”","words":["你","应该","向","他","学习","。"],"answer":"你应该向他学习。","explanation":"应该 (ôn HSK3 Bài 1) đứng trước cụm 向."},{"type":"sort","context":"Sắp xếp: “Anh ấy mỉm cười đi về phía tôi.”","words":["他","笑着","向","我","走","过来","了","。"],"answer":"他笑着向我走过来了。","explanation":"V1 + 着 + V2 (ôn HSK2 Bài 11); 笑 (ôn HSK2 Bài 10); 过来 (ôn HSK2 Bài 2)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng giới từ 向.","promptLang":"vi","prompt":"Thấy chúng tôi đến, bọn trẻ đều chạy về phía chúng tôi.","answer":"看见我们来了，孩子们都向我们跑过来了。","answerPy":"Kànjiàn wǒmen lái le, háizimen dōu xiàng wǒmen pǎo guòlai le.","explanation":"向 + người + V + 过来 (bổ ngữ xu hướng – ôn HSK2 Bài 2, 4); 看见 (ôn HSK1 Bài 8)."}]},{"point":"Câu phản vấn 「不是……吗？」 — chẳng phải… sao?","items":[{"context":"Sách (完成对话): A: Kỳ nghỉ năm nay mình vẫn muốn đi Nam Kinh. B: “Chẳng phải bạn đã đi Nam Kinh rồi sao?”","pre":"A：今年放假我还想去南京。B：","blank":"你不是去过南京吗","post":"？","options":["你不是去过南京吗","你没是去过南京吗","你是不去过南京吗"],"answer":0,"explanation":"不是 + V过 + 吗 — nhắc điều mình biết (bạn đi rồi mà); V过 (ôn HSK2 Bài 4); 放假 (ôn HSK3 Bài 6)."},{"context":"Sách (完成对话): A: “…?” B: Xin lỗi, em không mang. Em để bài tập ở nhà rồi. — A: “Chẳng phải em nói hôm nay mang bài tập đến sao?”","pre":"A：","blank":"你不是说今天把作业带来吗","post":"？B：对不起，我没带。我把作业放在家里了。","options":["你不是说今天把作业带来吗","你没是说今天把作业带来吗","你不是说今天把作业带来"],"answer":0,"explanation":"不是……吗 nhắc nhở / trách nhẹ; câu chữ 把 (ôn HSK3 Bài 10); 带 (ôn HSK3 Bài 1)."},{"context":"Sách (完成对话): A: Chiều nay tôi đi làm, chuyện này mai nói tiếp nhé. B: Hôm nay là chủ nhật, “chẳng phải anh không phải đi làm sao?”","pre":"A：我下午上班，这件事明天再说吧。B：今天是星期天，","blank":"你不是不用上班吗","post":"？","options":["你不是不用上班吗","你不用上班不是","你不是不用上班"],"answer":0,"explanation":"不是 + 不用 + V + 吗 → khẳng định: anh không phải đi làm mà; 不用 (ôn HSK3 Bài 2)."},{"context":"“Chẳng phải bạn nói hôm nay có việc sao? Sao lại đến?”","pre":"你","blank":"不是说今天有事吗","post":"？为什么来了？","options":["不是说今天有事吗","没是说今天有事吗","是不说今天有事吗"],"answer":0,"explanation":"Người nói không hiểu vì sao bạn lại đến → dùng 不是……吗; 为什么 (ôn HSK2 Bài 3)."},{"context":"“Kỳ thi chẳng phải tháng sau sao? Sao hôm nay bạn đã bắt đầu ôn tập rồi?”","pre":"考试","blank":"不是下个月吗","post":"？你怎么今天就开始复习了？","options":["不是下个月吗","是下个月不吗","不下个月吗"],"answer":0,"explanation":"不是 + thời gian + 吗; 复习 (ôn HSK3 Bài 10); 就 = sớm (ôn HSK3 Bài 3)."},{"context":"“Chẳng phải bạn thích chơi máy tính sao? Bạn có thể đọc sách liên quan đến máy tính.”","pre":"你不是喜欢玩电脑","blank":"吗","post":"？你可以去看看跟电脑有关系的书。","options":["吗","呢","吧"],"answer":0,"explanation":"Khung cố định 不是……吗, cuối câu dùng 吗; 关系 (ôn HSK3 Bài 15)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你不是说今天有事？为什么来了？","isCorrect":false,"correctVersion":"你不是说今天有事吗？为什么来了？","explanation":"Thiếu 吗: khung phản vấn là 不是……吗？"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你不是会说汉语吗？你去问问吧。","isCorrect":true,"explanation":"Đúng: 不是……吗 nhắc điều người nghe biết (bạn biết nói tiếng Trung mà) để đề nghị; 会 (ôn HSK1 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Chẳng phải bạn thích chơi máy tính sao?”","words":["你","不是","喜欢","玩","电脑","吗","？"],"answer":"你不是喜欢玩电脑吗？","explanation":"Câu của Bài khoá 2."},{"type":"sort","context":"Sắp xếp: “Chẳng phải bạn nói hôm nay có việc sao?”","words":["你","不是","说","今天","有事","吗","？"],"answer":"你不是说今天有事吗？","explanation":"不是 + 说 + nội dung + 吗."},{"type":"sort","context":"Sắp xếp: “Hôm nay chẳng phải chủ nhật sao? Sao bạn còn đi làm?”","words":["今天","不是","星期天","吗","？","你","怎么","还","去上班","？"],"answer":"今天不是星期天吗？你怎么还去上班？","explanation":"星期天 (ôn HSK1 Bài 5); 怎么 hỏi lý do (ôn HSK1 Bài 6)."},{"type":"sort","context":"Sắp xếp: “Chẳng phải bạn đã học tiếng Trung hai năm rồi sao?”","words":["你","不是","已经","学了","两年","汉语","了","吗","？"],"answer":"你不是已经学了两年汉语了吗？","explanation":"已经……了 (ôn HSK2 Bài 1); bổ ngữ thời lượng (ôn HSK3 Bài 8)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 不是……吗.","promptLang":"vi","prompt":"Chẳng phải bạn rất hứng thú với văn hoá Trung Quốc sao? Bạn có thể sang Trung Quốc du học.","answer":"你不是对中国文化很感兴趣吗？你可以去中国留学。","answerPy":"Nǐ bú shì duì Zhōngguó wénhuà hěn gǎn xìngqù ma? Nǐ kěyǐ qù Zhōngguó liúxué.","explanation":"对……感兴趣 (ôn HSK3 Bài 5); 文化 (ôn HSK3 Bài 13); 留学 của bài này."}]},{"point":"Câu ghép tăng tiến 「……，更……」","items":[{"context":"Sách (完成句子): “Lúc tìm việc cần sự giúp đỡ của người khác, càng cần sự cố gắng của bản thân.”","pre":"找工作的时候需要别人的帮助，更需要","blank":"自己的努力","post":"。","options":["自己的努力","别人的帮助","很努力"],"answer":0,"explanation":"Vế sau nêu điều quan trọng hơn; 努力 (ôn HSK3 Bài 10), 帮助 (ôn HSK3 Bài 1), 别人 (ôn HSK3 Bài 11)."},{"context":"Sách (完成句子): “Muốn khỏe mạnh thì nên vận động nhiều, càng nên ngủ sớm.”","pre":"要想身体健康，应该","blank":"多运动，更应该早点儿睡觉","post":"。","options":["多运动，更应该早点儿睡觉","多运动，应该更很早睡觉","更多运动，应该早点儿睡觉"],"answer":0,"explanation":"更 đứng trước 应该, không thêm 很; 健康 (ôn HSK3 Bài 8), 运动 (ôn HSK2 Bài 7)."},{"context":"Sách (完成句子): “Ngày mai thi đấu trận quan trọng, hôm nay phải luyện tập kỹ, càng phải nghỉ ngơi cho tốt.”","pre":"明天参加重要的比赛，今天要","blank":"好好练习，更要好好休息","post":"。","options":["好好练习，更要好好休息","好好练习，要更好好休息","更好好练习，要好好休息"],"answer":0,"explanation":"更 + 要 + V; 参加、比赛、练习 (ôn HSK3 Bài 9); 休息 (ôn HSK1 Bài 5)."},{"context":"“Mình vẫn chưa nghĩ kỹ học gì, càng chưa nghĩ kỹ đi nước nào.”","pre":"我还没想好学什么，","blank":"更没想好","post":"去哪个国家。","options":["更没想好","没更想好","更很没想好"],"answer":0,"explanation":"更 đứng trước 没; 想好 — bổ ngữ kết quả."},{"context":"“Muốn nâng cao trình độ tiếng Trung thì phải nghe nhiều đọc nhiều, càng phải nói nhiều luyện nhiều.”","pre":"想提高中文水平要多听多看，","blank":"更要","post":"多说多练。","options":["更要","要更","更很"],"answer":0,"explanation":"更 + 要 + V; 提高 (ôn HSK3 Bài 10), 水平 (ôn HSK3 Bài 5), 练 (ôn HSK3 Bài 9)."},{"context":"“Đến Trung Quốc học, tôi học được tiếng Trung, hơn nữa còn hiểu thêm văn hoá Trung Quốc.”","pre":"来中国学习，我学会了中文，","blank":"更了解了","post":"中国文化。","options":["更了解了","了解更了","更很了解"],"answer":0,"explanation":"了解 (ôn HSK3 Bài 15); 文化 (ôn HSK3 Bài 13); 学会 — bổ ngữ kết quả."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我喜欢学中文，更很喜欢中国文化。","isCorrect":false,"correctVersion":"我喜欢学中文，更喜欢中国文化。","explanation":"更 không đi cùng 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个问题老师都不会回答，我更不会了。","isCorrect":true,"explanation":"Đúng: vế sau mức độ cao hơn (thầy còn không trả lời được thì tôi càng không); 更 đứng trước 不."},{"type":"sort","context":"Sắp xếp: “Mình vẫn chưa nghĩ kỹ học gì, càng chưa nghĩ kỹ đi nước nào.”","words":["我","还没","想好","学什么","，","更","没想好","去哪个","国家","。"],"answer":"我还没想好学什么，更没想好去哪个国家。","explanation":"Câu của Bài khoá 3."},{"type":"sort","context":"Sắp xếp: “Muốn học tốt tiếng Trung phải nghe nhiều, càng phải nói nhiều.”","words":["想","学好","中文","要","多听","，","更要","多说","。"],"answer":"想学好中文要多听，更要多说。","explanation":"更要 + V; 学好 — bổ ngữ kết quả."},{"type":"sort","context":"Sắp xếp: “Tìm việc cần sự giúp đỡ của người khác, càng cần sự cố gắng của bản thân.”","words":["找工作","需要","别人的","帮助","，","更","需要","自己的","努力","。"],"answer":"找工作需要别人的帮助，更需要自己的努力。","explanation":"需要 (ôn HSK3 Bài 3); 自己 (ôn HSK2 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Tôi thích mùa xuân, càng thích mùa thu hơn.”","words":["我","喜欢","春天","，","更","喜欢","秋天","。"],"answer":"我喜欢春天，更喜欢秋天。","explanation":"春天、秋天 (ôn HSK3 Bài 12)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng “……，更……”.","promptLang":"vi","prompt":"Ông bà tôi không biết dùng máy tính, càng không biết lên mạng.","answer":"我爷爷奶奶不会用电脑，更不会上网。","answerPy":"Wǒ yéye nǎinai bú huì yòng diànnǎo, gèng bú huì shàngwǎng.","explanation":"爷爷、奶奶 (ôn HSK2 Bài 5); 上网 (ôn HSK2 Bài 13)."}]},{"point":"Câu ghép điều kiện 「只有……，才……」","items":[{"context":"Sách (完成对话): A: Ngày nào bạn cũng ra sân luyện tập à? B: Ừ, “chỉ có luyện tập mỗi ngày mới chơi tốt hơn được”.","pre":"A：你每天都去球场练习吗？B：对，只有每天练习，","blank":"才能打得更好","post":"。","options":["才能打得更好","就能打得更好","能才打得更好"],"answer":0,"explanation":"只有……才……; bổ ngữ trạng thái 得 (ôn HSK2 Bài 7); 球场、练习 (ôn HSK3 Bài 9)."},{"context":"Sách (完成对话): A: Bạn thấy làm thế nào mới tìm được công việc ưng ý? B: “Chỉ có học hành chăm chỉ mới tìm được công việc ưng ý.”","pre":"A：你觉得怎么才能找到满意的工作？B：","blank":"只有努力学习，才能找到满意的工作","post":"。","options":["只有努力学习，才能找到满意的工作","只有努力学习，就能找到满意的工作","努力学习只有，才能找到满意的工作"],"answer":0,"explanation":"满意 (ôn HSK3 Bài 4); 努力 (ôn HSK3 Bài 10)."},{"context":"Sách (完成对话): A: Nghe nói dạo này mẹ bạn không cho bạn chơi điện thoại à? B: “Ừ, chỉ khi điểm thi tiến bộ, mẹ mới cho mình chơi.”","pre":"A：听说你妈妈最近不让你玩手机了？B：","blank":"是啊，只有考试成绩提高了，她才让我玩","post":"。","options":["是啊，只有考试成绩提高了，她才让我玩","是啊，只有考试成绩提高了，才她让我玩","是啊，只有考试成绩提高了，她就让我玩"],"answer":0,"explanation":"才 đứng sau chủ ngữ 她; 成绩 (ôn HSK3 Bài 9), 提高 (ôn HSK3 Bài 10), 让 (ôn HSK2 Bài 1)."},{"context":"“Chỉ có rèn luyện thân thể mỗi ngày mới ngày càng khỏe mạnh.”","pre":"只有每天锻炼身体，","blank":"才","post":"会越来越健康。","options":["才","就","都"],"answer":0,"explanation":"只有 đi với 才; 越来越 (ôn HSK3 Bài 6), 锻炼 (ôn HSK3 Bài 5)."},{"context":"“Chỉ có nghe nhiều, nói nhiều, đọc nhiều, trình độ tiếng Trung của bạn mới nâng cao được.”","pre":"只有多听、多说、多看，","blank":"你的中文水平才能提高","post":"。","options":["你的中文水平才能提高","才你的中文水平能提高","你的中文水平能才提高"],"answer":0,"explanation":"才 đứng sau chủ ngữ, trước 能."},{"context":"“Chỉ khi nghĩ rõ bản thân thực sự thích gì, mới có thể đưa ra lựa chọn phù hợp nhất.”","pre":"","blank":"只有","post":"想清楚自己真正喜欢什么，才能做出最合适的选择。","options":["只有","虽然","可是"],"answer":0,"explanation":"Câu của Bài khoá 4; 合适 (ôn HSK3 Bài 7), 选择 (ôn HSK3 Bài 6)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"只有每天锻炼身体，就会越来越健康。","isCorrect":false,"correctVersion":"只有每天锻炼身体，才会越来越健康。","explanation":"只有 phải đi với 才, không đi với 就."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"只有你去请他，他才会来。","isCorrect":true,"explanation":"Đúng: chủ ngữ vế sau 他 đứng trước 才; 请 (ôn HSK1 Bài 13)."},{"type":"sort","context":"Sắp xếp: “Chỉ có luyện tập mỗi ngày mới chơi tốt hơn được.”","words":["只有","每天","练习","，","才能","打得","更好","。"],"answer":"只有每天练习，才能打得更好。","explanation":"Câu 完成对话 của sách."},{"type":"sort","context":"Sắp xếp: “Chỉ có học hành chăm chỉ mới tìm được công việc ưng ý.”","words":["只有","努力","学习","，","才能","找到","满意的","工作","。"],"answer":"只有努力学习，才能找到满意的工作。","explanation":"找到 — bổ ngữ kết quả; 满意 (ôn HSK3 Bài 4)."},{"type":"sort","context":"Sắp xếp: “Chỉ khi trời nắng, chúng ta mới đi leo núi được.”","words":["只有","天","晴了","，","我们","才能","去","爬山","。"],"answer":"只有天晴了，我们才能去爬山。","explanation":"晴 (ôn HSK2 Bài 12); 爬山 (ôn HSK3 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Chỉ có bạn mới giúp được tôi.”","words":["只有","你","才能","帮","我","。"],"answer":"只有你才能帮我。","explanation":"只有 + người + 才……; 帮 (ôn HSK2 Bài 10)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 只有……才…….","promptLang":"vi","prompt":"Chỉ khi làm xong bài tập, con mới được chơi game.","answer":"只有写完作业，你才可以玩游戏。","answerPy":"Zhǐyǒu xiěwán zuòyè, nǐ cái kěyǐ wán yóuxì.","explanation":"作业 (ôn HSK3 Bài 10); 游戏 (ôn HSK3 Bài 15); 写完 — bổ ngữ kết quả."}]}],"/lessons/hsk3v3-bai-18.html":[{"point":"Cách diễn đạt số ước lượng 「概数」 — hai số liền kề + lượng từ","items":[{"context":"Sách (用概数回答问题): “你一般晚上几点睡觉？” — Tôi thường ngủ khoảng mười một, mười hai giờ đêm.","pre":"我一般晚上","blank":"十一二点","post":"睡觉。","options":["十一二点","十一十二点","十一或十二点"],"answer":0,"explanation":"11–12 giờ: ghép 十一 + 二 → 十一二点; không lặp 十, không thêm 或. Đáp án mở — tuỳ giờ ngủ của bạn."},{"context":"Sách (用概数回答问题): “你每天学习多长时间汉语？” — Mỗi ngày tôi học tiếng Trung khoảng một hai tiếng.","pre":"我每天学习","blank":"一两个小时","post":"汉语。","options":["一两个小时","一二个小时","一个两个小时"],"answer":0,"explanation":"Trước lượng từ dùng 两, không dùng 二 (ôn HSK1): 一两个; thời lượng đứng giữa động từ và tân ngữ (ôn HSK3 Bài 8). Đáp án mở."},{"context":"Sách (用概数回答问题): “你们国家新年一般放几天假？” — Ở nước tôi Tết thường được nghỉ khoảng bảy tám ngày.","pre":"我们国家新年一般放","blank":"七八天","post":"假。","options":["七八天","七天八天","八七天"],"answer":0,"explanation":"Hai số liền kề theo thứ tự nhỏ → lớn; 放假 là từ ly hợp, thời lượng chen giữa: 放七八天假 (ôn HSK3 Bài 6, Bài 8). Đáp án mở."},{"context":"“Trong lớp học có năm sáu học sinh đến.”","pre":"教室里来了","blank":"五六个","post":"学生。","options":["五六个","五个六个","五六"],"answer":0,"explanation":"Dùng chung một lượng từ 个 sau số thứ hai; không bỏ lượng từ. 教室 (ôn HSK2 Bài 2)."},{"context":"“Những bức ảnh này chụp khoảng ba bốn năm trước nhỉ?”","pre":"这些照片是","blank":"三四年","post":"前照的吧？","options":["三四年","三年四年","三四个年"],"answer":0,"explanation":"年 đi thẳng sau số, không cần lượng từ 个; 是……的 nhấn mạnh thời gian; 照片 (ôn HSK3 Bài 1)."},{"context":"“Lớp chúng tôi có khoảng hai ba mươi học sinh.”","pre":"我们班大概有","blank":"二三十","post":"个学生。","options":["二三十","二十三十","三二十"],"answer":0,"explanation":"Hàng chục: 二三十 = 20–30; 大概 + số ước lượng; 班 (ôn HSK2 Bài 13)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"春节大概放七或八天假。","isCorrect":false,"correctVersion":"春节大概放七八天假。","explanation":"Số ước lượng không dùng 或: hai số liền kề đặt sát nhau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我昨天晚上大概睡了五六个小时。","isCorrect":true,"explanation":"Đúng: 大概 + 五六个小时; bổ ngữ thời lượng (ôn HSK3 Bài 8)."},{"type":"sort","context":"Sắp xếp: “Tết được nghỉ khoảng bảy tám ngày.”","words":["春节","大概","放","七八天","假","。"],"answer":"春节大概放七八天假。","explanation":"Câu của Bài khoá 1; 放……假 (ôn HSK3 Bài 6)."},{"type":"sort","context":"Sắp xếp: “Trong lớp học có năm sáu học sinh đến.”","words":["教室里","来了","五六个","学生","。"],"answer":"教室里来了五六个学生。","explanation":"Câu tồn hiện: nơi chốn + V + 了 + người (ôn HSK3 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Cuốn sách này tôi đã đọc hai ba lượt rồi.”","words":["这本书","我","看了","两三遍","了","。"],"answer":"这本书我看了两三遍了。","explanation":"遍 (ôn HSK3 Bài 10); trước lượng từ dùng 两三, không dùng 二三."},{"type":"sort","context":"Sắp xếp: “Mỗi ngày tôi đi bộ đi học, mất khoảng mười lăm mười sáu phút.”","words":["我","每天","走路","上学","，","大概","要","十五六","分钟","。"],"answer":"我每天走路上学，大概要十五六分钟。","explanation":"十五六 = 15–16; 走路 (ôn HSK2 Bài 9), 上学 (ôn HSK1 Bài 14)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng số ước lượng.","promptLang":"vi","prompt":"Hôm qua có khoảng ba bốn mươi người đến tham gia buổi liên hoan.","answer":"昨天大概有三四十个人来参加晚会。","answerPy":"Zuótiān dàgài yǒu sān-sìshí ge rén lái cānjiā wǎnhuì.","explanation":"三四十 = 30–40; 参加 (ôn HSK3 Bài 9); 晚会 (ôn HSK3 Bài 13)."}]},{"point":"「刚才」 và 「刚刚」 — danh từ thời gian và phó từ thời gian","items":[{"context":"Sách (用“刚刚”或者“刚才”填空): “Bạn nói lại một lần câu hỏi lúc nãy nhé.”","pre":"请你再说一遍","blank":"刚才","post":"的问题。","options":["刚才","刚刚","刚"],"answer":0,"explanation":"刚才 là danh từ, làm định ngữ được (刚才的问题); 刚刚 / 刚 là phó từ, không đi với 的. 遍 (ôn HSK3 Bài 10)."},{"context":"Sách (用“刚刚”或者“刚才”填空): “Bạn mới đến được hai ba ngày đã muốn đi, vì sao vậy?”","pre":"你","blank":"刚刚","post":"来了两三天就要走，为什么？","options":["刚刚","刚才","以前"],"answer":0,"explanation":"刚刚 + V + thời lượng (两三天 — số ước lượng, ngữ pháp 1); 刚才 chỉ vài phút trước, không hợp với “hai ba ngày”."},{"context":"Sách (用“刚刚”或者“刚才”填空): “Tôi không phải mới bắt đầu học tiếng Trung, tôi đã học một năm rồi.”","pre":"我不是","blank":"刚刚","post":"开始学习中文的，我已经学了一年了。","options":["刚刚","刚才","马上"],"answer":0,"explanation":"Mốc “một năm” không hợp với 刚才 (vài phút trước); 刚刚 đứng trước động từ 开始; 已经……了 (ôn HSK2 Bài 1)."},{"context":"“Cuộc điện thoại lúc nãy là mẹ tôi gọi đến.”","pre":"","blank":"刚才","post":"的电话是我妈妈打来的。","options":["刚才","刚刚","刚"],"answer":0,"explanation":"刚才的 + N; 是……的 nhấn mạnh người thực hiện; 打电话 (ôn HSK1 Bài 13)."},{"context":"“Anh ấy vừa mới đến Bắc Kinh được hai tháng.”","pre":"他","blank":"刚刚","post":"来北京两个月。","options":["刚刚","刚才","不久"],"answer":0,"explanation":"刚刚 + V + thời lượng dài; 不久 là tính từ, không đứng thẳng trước động từ như vậy."},{"context":"“Lúc nãy tôi nghe không rõ, bạn nói lại lần nữa nhé.”","pre":"我","blank":"刚才","post":"没听清楚，请你再说一遍。","options":["刚才","刚","以后"],"answer":0,"explanation":"刚才 là danh từ, phía sau dùng được phủ định 没 / 不; phó từ 刚 không đi với phủ định; 清楚 (ôn HSK3 Bài 10)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"刚刚的电话是谁打来的？","isCorrect":false,"correctVersion":"刚才的电话是谁打来的？","explanation":"刚刚 là phó từ, không làm định ngữ; dùng 刚才的 + N."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我刚刚搬到这个小区两个星期。","isCorrect":true,"explanation":"Đúng: 刚刚 + V + thời lượng; 搬、小区 (ôn HSK3 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Tôi vừa mới xem video học được cách gói sủi cảo.”","words":["我","刚刚","看视频","学会了","包饺子","。"],"answer":"我刚刚看视频学会了包饺子。","explanation":"Câu của Bài khoá 2: chủ ngữ + 刚刚 + V; 视频 (ôn HSK3 Bài 14)."},{"type":"sort","context":"Sắp xếp: “Cuộc điện thoại lúc nãy là mẹ tôi gọi đến.”","words":["刚才的","电话","是","我妈妈","打来的","。"],"answer":"刚才的电话是我妈妈打来的。","explanation":"刚才 làm định ngữ: 刚才的电话."},{"type":"sort","context":"Sắp xếp: “Anh ấy vừa mới đến Bắc Kinh được hai tháng.”","words":["他","刚刚","来","北京","两个月","。"],"answer":"他刚刚来北京两个月。","explanation":"刚刚 + V + nơi chốn + thời lượng."},{"type":"sort","context":"Sắp xếp: “Lúc nãy tôi đã xem một lượt rồi, không muốn xem lại nữa.”","words":["我","刚才","看过","一遍","，","不想","再看了","。"],"answer":"我刚才看过一遍，不想再看了。","explanation":"刚才 đứng sau chủ ngữ, trước động từ; 再 (ôn HSK1 Bài 12)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 刚才 hoặc 刚刚.","promptLang":"vi","prompt":"Em gái tôi vừa mới tốt nghiệp đại học tháng trước.","answer":"我妹妹上个月刚刚大学毕业。","answerPy":"Wǒ mèimei shàng ge yuè gānggāng dàxué bìyè.","explanation":"Việc xảy ra cách đây một tháng → 刚刚, không dùng 刚才; 毕业 của bài này."}]},{"point":"Câu ghép điều kiện 「只要……，就……」","items":[{"context":"Sách (完成对话): A: Sao bạn đối xử tốt với mọi người thế? B: “Mình tin rằng chỉ cần mình tốt với người khác, người khác cũng sẽ tốt với mình.”","pre":"我相信只要我对别人好，","blank":"别人就会对我好","post":"。","options":["别人就会对我好","就别人会对我好","别人才会对我好"],"answer":0,"explanation":"Chủ ngữ thứ hai 别人 đứng trước 就; 只要 không đi với 才; 相信 (ôn HSK3 Bài 14), 别人 (ôn HSK3 Bài 11). Đáp án mở."},{"context":"Sách (完成对话): A: “Chỉ cần em chăm chỉ học, thành tích nhất định sẽ được nâng cao.” B: Thưa thầy, em nhất định sẽ cố gắng.","pre":"只要你努力学习，","blank":"成绩就一定会提高","post":"。","options":["成绩就一定会提高","就成绩一定会提高","成绩才一定会提高"],"answer":0,"explanation":"Chủ ngữ 成绩 đứng trước 就; 成绩 (ôn HSK3 Bài 9), 提高、努力 (ôn HSK3 Bài 10). Đáp án mở."},{"context":"Sách (完成对话): A: Cô Trương, cảm ơn cô đã nấu nhiều món thế này, chắc cô mệt lắm. B: “Không mệt, chỉ cần các cháu thích ăn là cô không thấy mệt.”","pre":"不累，","blank":"只要你们喜欢吃","post":"，我就不觉得累。","options":["只要你们喜欢吃","只有你们喜欢吃","你们喜欢吃只要"],"answer":0,"explanation":"Vế sau có 就 → dùng 只要 (只有 phải đi với 才); vế 只要 đứng trước. 觉得 (ôn HSK1 Bài 12). Đáp án mở."},{"context":"“Chỉ cần vài ngày không gọi video cho nó là cô rất nhớ nó.”","pre":"我","blank":"只要","post":"几天不跟他视频，就很想他。","options":["只要","只有","只是"],"answer":0,"explanation":"只要……就……; 只有 đi với 才 (ôn HSK3 Bài 17); 只是 = chỉ là (ôn HSK3 Bài 9)."},{"context":"“Chỉ cần bạn kiên trì ngủ sớm mỗi ngày, sức khỏe nhất định sẽ tốt lên.”","pre":"只要你坚持每天早睡，身体","blank":"就","post":"一定会好起来。","options":["就","才","都"],"answer":0,"explanation":"只要 đi với 就; 好起来 — bổ ngữ xu hướng nghĩa mở rộng (ôn HSK3 Bài 8); 坚持 của bài này."},{"context":"“Chỉ cần có thời gian, tôi sẽ đến thăm bạn.”","pre":"只要有时间，","blank":"我就去看你","post":"。","options":["我就去看你","就我去看你","我去看你就"],"answer":0,"explanation":"Chủ ngữ 我 đứng trước 就, 就 đứng trước động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"只要你每天练习，你才能说好汉语。","isCorrect":false,"correctVersion":"只要你每天练习，就能说好汉语。","explanation":"只要 đi với 就, không đi với 才."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"只要明天不下雨，我们就去爬山。","isCorrect":true,"explanation":"Đúng: chủ ngữ thứ hai 我们 đứng trước 就; 下雨 (ôn HSK1 Bài 12), 爬山 (ôn HSK3 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Chỉ cần luôn kiên trì là có thể hoàn thành mục tiêu của mình.”","words":["只要","一直","坚持","，","就","能","完成","自己的","目标","。"],"answer":"只要一直坚持，就能完成自己的目标。","explanation":"Câu của Bài khoá 4; 一直 (ôn HSK3 Bài 4)."},{"type":"sort","context":"Sắp xếp: “Chỉ cần con thích, mẹ sẽ nấu cho con.”","words":["只要","你","喜欢","，","妈妈","就","给你","做","。"],"answer":"只要你喜欢，妈妈就给你做。","explanation":"Hai chủ ngữ: 妈妈 đứng trước 就; 给 + người + V (ôn HSK2 Bài 1)."},{"type":"sort","context":"Sắp xếp: “Chỉ cần có thời gian, ông tôi sẽ ra công viên đi bộ.”","words":["只要","有时间","，","爷爷","就","去","公园","走走","。"],"answer":"只要有时间，爷爷就去公园走走。","explanation":"公园 (ôn HSK3 Bài 12); 爷爷 (ôn HSK2 Bài 5); lặp động từ 走走."},{"type":"sort","context":"Sắp xếp: “Tôi chỉ cần nghe nhạc là vui ngay.”","words":["我","只要","听","音乐","，","就","很","开心","。"],"answer":"我只要听音乐，就很开心。","explanation":"Một chủ ngữ đặt trước 只要; 音乐 (ôn HSK3 Bài 5), 开心 (ôn HSK3 Bài 8)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 只要……就…….","promptLang":"vi","prompt":"Chỉ cần ngày mai trời đẹp, chúng ta sẽ ra biển chơi.","answer":"只要明天天气好，我们就去海边玩儿。","answerPy":"Zhǐyào míngtiān tiānqì hǎo, wǒmen jiù qù hǎi biān wánr.","explanation":"海 (ôn HSK3 Bài 4); 天气 (ôn HSK1 Bài 12)."}]},{"point":"Cấu trúc cố định 「从……起」 — bắt đầu từ…","items":[{"context":"Sách (完成句子): “Từ khi chuyển đến Bắc Kinh, tôi bắt đầu đi tàu điện ngầm đi làm.”","pre":"从搬到北京起，","blank":"我就开始坐地铁上班了","post":"。","options":["我就开始坐地铁上班了","就我开始坐地铁上班了","我开始就坐地铁上班了"],"answer":0,"explanation":"从 + sự việc + 起，chủ ngữ + 就 + V; 地铁 (ôn HSK2 Bài 12), 搬 (ôn HSK3 Bài 3). Đáp án mở — đây là một cách hoàn thành."},{"context":"Sách (完成句子): “Từ tháng trước, ngày nào tôi cũng tập thể dục hai ba mươi phút.”","pre":"从","blank":"上个月","post":"起，我每天都锻炼二三十分钟。","options":["上个月","上个月以后","上个月开始"],"answer":0,"explanation":"Giữa 从 và 起 chỉ đặt mốc thời gian, không thêm 以后 / 开始; 锻炼 (ôn HSK3 Bài 5); 二三十 — số ước lượng (ngữ pháp 1). Đáp án mở."},{"context":"Sách (完成句子): “Từ khi mua chiếc máy ảnh mới, tôi bắt đầu thích chụp ảnh.”","pre":"","blank":"从买了新相机起","post":"，我就开始喜欢拍照了。","options":["从买了新相机起","起买了新相机","从起买了新相机"],"answer":0,"explanation":"Mốc là một sự việc: 从 + 买了新相机 + 起; 相机 (ôn HSK3 Bài 4), 拍照 (ôn HSK3 Bài 5). Đáp án mở."},{"context":"“Từ lúc đó anh ấy đã cố gắng học tập.”","pre":"他从那时","blank":"起","post":"就努力学习。","options":["起","以前","去"],"answer":0,"explanation":"Câu của Bài khoá 4: 从那时起 = từ lúc đó; 努力 (ôn HSK3 Bài 10)."},{"context":"“Từ hôm đó, chúng tôi đã trở thành bạn tốt.”","pre":"","blank":"从那天起","post":"，我们就变成了好朋友。","options":["从那天起","那天从起","从那天以后起"],"answer":0,"explanation":"从 + 那天 + 起 đứng đầu câu; 变成 (ôn HSK3 Bài 12)."},{"context":"“Từ chuyến du lịch lần đó, tôi càng có hứng thú với văn hoá Trung Quốc hơn.”","pre":"从那次旅游","blank":"起","post":"，我对中国文化更有兴趣了。","options":["起","开","去"],"answer":0,"explanation":"从 + sự việc + 起; 对……有兴趣 (ôn HSK3 Bài 5); 文化 (ôn HSK3 Bài 13); 更 (ôn HSK3 Bài 7)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"起从明天，我每天早上跑步。","isCorrect":false,"correctVersion":"从明天起，我每天早上跑步。","explanation":"Khung đúng: 从 + mốc thời gian + 起."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"从下个星期起，我们每天八点上课。","isCorrect":true,"explanation":"Đúng: 从 + 下个星期 + 起 đầu câu; 上课 (ôn HSK1 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Từ lúc đó anh ấy đã cố gắng học tập.”","words":["他","从","那时","起","就","努力","学习","。"],"answer":"他从那时起就努力学习。","explanation":"Câu của Bài khoá 4: chủ ngữ + 从……起 + 就 + V."},{"type":"sort","context":"Sắp xếp: “Từ hôm đó, chúng tôi đã trở thành bạn tốt.”","words":["从","那天","起","，","我们","就","变成了","好朋友","。"],"answer":"从那天起，我们就变成了好朋友。","explanation":"从……起 đầu câu, có dấu phẩy."},{"type":"sort","context":"Sắp xếp: “Từ ngày mai, tôi phải dậy sớm chạy bộ.”","words":["从","明天","起","，","我","要","早点儿","起床","跑步","。"],"answer":"从明天起，我要早点儿起床跑步。","explanation":"起床 (ôn HSK1 Bài 11); 跑步 (ôn HSK2 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Từ tháng trước, mẹ đã bắt đầu chuẩn bị cho Tết.”","words":["从","上个月","起","，","妈妈","就","开始","为","春节","做准备","了","。"],"answer":"从上个月起，妈妈就开始为春节做准备了。","explanation":"Câu 选词填空 của sách; 为 (ôn HSK3 Bài 11), 准备 (ôn HSK2 Bài 5)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 从……起.","promptLang":"vi","prompt":"Từ năm ngoái, tôi đã bắt đầu học tiếng Trung.","answer":"从去年起，我就开始学习汉语了。","answerPy":"Cóng qùnián qǐ, wǒ jiù kāishǐ xuéxí Hànyǔ le.","explanation":"去年 (ôn HSK1 Bài 15); 开始 (ôn HSK2 Bài 7)."}]}],"/lessons/hsk3v3-bai-2.html":[{"point":"Câu ghép đẳng lập 「又……又……」 — vừa… vừa…","items":[{"context":"Sách (改写句子): “Nhà mới của anh ấy vừa rộng vừa sạch sẽ.” (干净 gānjìng – sạch sẽ)","pre":"他的新家","blank":"又大又干净","post":"。","options":["又大又干净","又很大又很干净","又大和干净"],"answer":0,"explanation":"Gộp “很大，也很干净” thành 又大又干净 — bỏ 很."},{"context":"Sách (改写句子): “Anh ấy viết chữ Hán vừa nhanh vừa đẹp.”","pre":"他写汉字写得","blank":"又快又漂亮","post":"。","options":["又快又漂亮","又快也漂亮","很快又漂亮"],"answer":0,"explanation":"又……又…… làm bổ ngữ trạng thái sau 得 (ôn HSK2 Bài 7)."},{"context":"Sách (改写句子): “Đồ trong siêu thị này vừa nhiều vừa rẻ.”","pre":"这个超市里的东西","blank":"又多又便宜","post":"。","options":["又多又便宜","又多和便宜","又很多又很便宜"],"answer":0,"explanation":"Gộp “很多，也很便宜” thành 又多又便宜."},{"context":"“Sau chuyến bay dài như vậy, em thực sự vừa đói vừa khát.”","pre":"飞了这么远，现在还真是","blank":"又饿又渴","post":"。","options":["又饿又渴","又饿和渴","很饿又渴"],"answer":0,"explanation":"Mỗi tính từ đều có 又 đứng trước."},{"context":"“Lúc sắp thi vừa bận vừa mệt.” (快要 – HSK2 Bài 10; 累 – HSK2 Bài 3)","pre":"快要考试的时候","blank":"又忙又累","post":"，没时间出去吃饭。","options":["又忙又累","又忙也累","忙又又累"],"answer":0,"explanation":"又忙又累 — hai đặc điểm cùng chiều (đều vất vả)."},{"context":"“Cái túi này vừa đẹp vừa rẻ, tôi muốn mua một cái.” (包 – HSK2 Bài 14)","pre":"这个包","blank":"又好看又便宜","post":"，我想买一个。","options":["又好看又便宜","好看又又便宜","又好看和便宜"],"answer":0,"explanation":"又 + 好看 + 又 + 便宜."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个饭馆的菜又很便宜又很好吃。","isCorrect":false,"correctVersion":"这个饭馆的菜又便宜又好吃。","explanation":"Sau 又 không thêm 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"那个女孩儿又高又漂亮。","isCorrect":true,"explanation":"Đúng: 又 + 高 + 又 + 漂亮, hai đặc điểm cùng là lời khen."},{"type":"sort","context":"Sắp xếp: “Bây giờ tôi vừa đói vừa khát.”","words":["我","现在","又","饿","又","渴","。"],"answer":"我现在又饿又渴。","explanation":"Thời gian 现在 đứng sau chủ ngữ, trước 又."},{"type":"sort","context":"Sắp xếp: “Đồ ăn ở đây vừa rẻ vừa ngon.”","words":["这里","的","饭菜","又","便宜","又","好吃","。"],"answer":"这里的饭菜又便宜又好吃。","explanation":"这里的饭菜 làm chủ ngữ; 这里 (HSK1 Bài 12)."},{"type":"sort","context":"Sắp xếp: “Cô gái kia vừa cao vừa xinh.”","words":["那个","女孩儿","又","高","又","漂亮","。"],"answer":"那个女孩儿又高又漂亮。","explanation":"又高又漂亮; 女孩儿 (HSK2 Bài 14)."},{"type":"sort","context":"Sắp xếp: “Anh ấy viết chữ Hán vừa nhanh vừa đẹp.”","words":["他","写","汉字","写","得","又","快","又","漂亮","。"],"answer":"他写汉字写得又快又漂亮。","explanation":"Lặp động từ 写 khi có tân ngữ + 得 (ôn HSK2 Bài 7)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 又……又…….","promptLang":"vi","prompt":"Hôm nay tôi vừa bận vừa mệt.","answer":"我今天又忙又累。","answerPy":"Wǒ jīntiān yòu máng yòu lèi.","explanation":"Thời gian 今天 đứng sau chủ ngữ; 又忙又累 — không thêm 很."}]},{"point":"Đại từ nghi vấn không dùng để hỏi (2) — chỉ “bất kỳ”, đi với 都","items":[{"context":"Sách (改写句子, dùng 什么): “Món Trung Quốc hay món nước ngoài mình đều thích — món gì mình cũng thích ăn.”","pre":"我","blank":"什么菜都喜欢吃","post":"。","options":["什么菜都喜欢吃","都什么菜喜欢吃","什么菜喜欢吃都"],"answer":0,"explanation":"什么菜 + 都 + 喜欢吃."},{"context":"Sách (改写句子, dùng 谁): “Tiểu Lý nấu ăn rất giỏi, ai cũng thích ăn cơm anh ấy nấu.”","pre":"小李很会做饭，","blank":"谁都喜欢吃","post":"他做的饭。","options":["谁都喜欢吃","都谁喜欢吃","谁喜欢吃都"],"answer":0,"explanation":"谁 = bất kỳ ai; 谁 + 都 + V."},{"context":"Sách (改写句子, dùng 怎么): “Nhà hàng không xa lắm, chúng ta đi cách nào cũng được.”","pre":"饭馆不太远，我们","blank":"怎么去都可以","post":"。","options":["怎么去都可以","都怎么去可以","怎么都去可以"],"answer":0,"explanation":"怎么去 = đi bằng cách nào (bất kỳ) + 都可以; thay cho “打车、坐公交车、走路去都可以”."},{"context":"“Món nào cũng ngon.”","pre":"","blank":"哪个菜都","post":"好吃。","options":["哪个菜都","哪个菜","都哪个菜"],"answer":0,"explanation":"哪个菜 + 都 + 好吃; thiếu 都 sẽ thành câu hỏi."},{"context":"“Chuyến du lịch lần này, đi đâu em cũng được.” (旅游 – HSK2 Bài 1)","pre":"这次旅游，我","blank":"去哪儿都可以","post":"。","options":["去哪儿都可以","都去哪儿可以","去哪儿可以都"],"answer":0,"explanation":"去哪儿 + 都可以."},{"context":"“Hôm nay tôi không muốn ăn gì cả.”","pre":"今天我","blank":"什么都不想吃","post":"。","options":["什么都不想吃","什么不想吃","不想吃都什么"],"answer":0,"explanation":"Phủ định: 什么 + 都 + 不 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我都什么菜喜欢吃。","isCorrect":false,"correctVersion":"我什么菜都喜欢吃。","explanation":"都 phải đứng sau 什么菜."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我下午有时间，你想什么时候来都没问题。","isCorrect":true,"explanation":"Đúng: 什么时候 = bất kỳ lúc nào, hô ứng với 都."},{"type":"sort","context":"Sắp xếp: “Món nào cũng ngon.”","words":["哪个","菜","都","好吃","。"],"answer":"哪个菜都好吃。","explanation":"哪个菜 + 都 + 好吃."},{"type":"sort","context":"Sắp xếp: “Ai cũng thích ăn cơm Tiểu Lý nấu.”","words":["谁","都","喜欢","吃","小李","做","的","饭","。"],"answer":"谁都喜欢吃小李做的饭。","explanation":"谁都 + V; 小李做的饭 — cụm chủ vị làm định ngữ (ôn HSK2 Bài 2)."},{"type":"sort","context":"Sắp xếp: “Đi đâu tôi cũng được.”","words":["我","去","哪儿","都","可以","。"],"answer":"我去哪儿都可以。","explanation":"去哪儿 + 都可以."},{"type":"sort","context":"Sắp xếp: “Không có gì ngon bằng cơm mẹ nấu.”","words":["什么","都","没有","妈妈","做","的","饭","好吃","。"],"answer":"什么都没有妈妈做的饭好吃。","explanation":"什么都 + câu so sánh 没有 (ôn HSK2 Bài 9)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 什么……都…….","promptLang":"vi","prompt":"Em ăn gì cũng được, chị gọi món đi.","answer":"我吃什么都可以，你点吧。","answerPy":"Wǒ chī shénme dōu kěyǐ, nǐ diǎn ba.","explanation":"吃什么 + 都可以; 点 — gọi món (HSK2 Bài 8)."}]},{"point":"Đại từ nghi vấn không dùng để hỏi (3) — hai đại từ hô ứng 「……什么，就……什么」","items":[{"context":"Sách (完成对话): A：这是菜单，我们点什么？ B: “Em muốn ăn gì thì gọi món đó.”","pre":"","blank":"你想吃什么就点什么","post":"。","options":["你想吃什么就点什么","你想吃什么就点那个","你想吃什么点就什么"],"answer":0,"explanation":"Hai 什么 hô ứng, cùng chỉ một món."},{"context":"Sách (完成对话): A：我们怎么去电影院？ B: “Bạn muốn đi bằng cách nào thì chúng ta đi cách đó.”","pre":"","blank":"你想怎么去，我们就怎么去","post":"。","options":["你想怎么去，我们就怎么去","你想怎么去，就我们怎么去","你想怎么去，我们就那样去"],"answer":0,"explanation":"Chủ ngữ khác nhau → 我们 đứng trước 就; lặp lại 怎么."},{"context":"Sách (完成对话): A：我什么时候去找你？ B: “Lúc nào bạn có thời gian thì lúc đó đến tìm mình.”","pre":"","blank":"你什么时候有时间，就什么时候来","post":"找我吧。","options":["你什么时候有时间，就什么时候来","你什么时候有时间，就那时候来","你有时间什么时候，就来什么时候"],"answer":0,"explanation":"Cùng chủ ngữ 你 → vế sau lược chủ ngữ; 什么时候……什么时候."},{"context":"“Bạn thấy cái nào đẹp thì mua cái đó.”","pre":"你觉得","blank":"哪个好看就买哪个","post":"。","options":["哪个好看就买哪个","哪个好看就买这个","哪个好看买就哪个"],"answer":0,"explanation":"哪个……哪个; 就 đứng trước động từ vế sau."},{"context":"“Bạn muốn đi đâu thì chúng ta đi đó.”","pre":"你想去哪儿，","blank":"我们就去哪儿","post":"。","options":["我们就去哪儿","就我们去哪儿","我们去就哪儿"],"answer":0,"explanation":"Chủ ngữ thứ hai (我们) + 就 + V + 哪儿."},{"context":"“Bạn muốn ăn bao nhiêu thì gọi bấy nhiêu.”","pre":"你想吃多少","blank":"就点多少","post":"。","options":["就点多少","就点很多","点就多少"],"answer":0,"explanation":"多少 cũng là đại từ nghi vấn: 多少……多少."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你想去哪儿，就我们去哪儿。","isCorrect":false,"correctVersion":"你想去哪儿，我们就去哪儿。","explanation":"Chủ ngữ 我们 phải đứng trước 就."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你们想吃什么就点什么。","isCorrect":true,"explanation":"Đúng: cùng chủ ngữ 你们 nên vế sau lược chủ ngữ."},{"type":"sort","context":"Sắp xếp: “Các em muốn ăn gì thì gọi món đó.”","words":["你们","想","吃","什么","就","点","什么","。"],"answer":"你们想吃什么就点什么。","explanation":"什么……就……什么."},{"type":"sort","context":"Sắp xếp: “Bạn thấy cái nào đẹp thì mua cái đó.”","words":["你","觉得","哪个","好看","就","买","哪个","。"],"answer":"你觉得哪个好看就买哪个。","explanation":"哪个……就……哪个."},{"type":"sort","context":"Sắp xếp: “Bạn muốn đi đâu thì chúng ta đi đó.”","words":["你","想","去","哪儿","，","我们","就","去","哪儿","。"],"answer":"你想去哪儿，我们就去哪儿。","explanation":"Chủ ngữ khác nhau: 我们 + 就."},{"type":"sort","context":"Sắp xếp: “Lúc nào bạn có thời gian thì lúc đó đến nhé.”","words":["你","什么时候","有","时间","，","就","什么时候","来","吧","。"],"answer":"你什么时候有时间，就什么时候来吧。","explanation":"Cùng chủ ngữ 你 → vế sau không lặp lại 你."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng hai đại từ nghi vấn hô ứng.","promptLang":"vi","prompt":"Bạn muốn uống gì thì gọi đồ đó, đừng khách sáo.","answer":"你想喝什么就点什么，别客气。","answerPy":"Nǐ xiǎng hē shénme jiù diǎn shénme, bié kèqi.","explanation":"什么……就……什么; 别客气 — từ mới bài này (别 – HSK2 Bài 2)."}]}],"/lessons/hsk3v3-bai-3.html":[{"point":"Phó từ chỉ mức độ 「挺」 — khá, rất","items":[{"context":"Sách: “你爱游泳吗？” — trả lời bằng 挺……的 (游泳 – HSK2 Bài 7)","pre":"我","blank":"挺爱游泳的","post":"。","options":["挺爱游泳的","爱挺游泳的","挺很爱游泳的"],"answer":0,"explanation":"挺 + 爱 (động từ tâm lý) + tân ngữ + 的."},{"context":"Sách: “你的床舒服吗？” (床、舒服 – HSK2 Bài 6)","pre":"我的床","blank":"挺舒服的","post":"。","options":["挺舒服的","舒服挺的","很挺舒服的"],"answer":0,"explanation":"挺 + tính từ + 的; không dùng chung với 很."},{"context":"Sách: “你觉得现在的天气怎么样？” (天气 – HSK1 Bài 12)","pre":"我觉得现在的天气","blank":"挺好的","post":"，不冷也不热。","options":["挺好的","好挺的","挺很好的"],"answer":0,"explanation":"挺好的 — khá đẹp; không thêm 很."},{"context":"“Món ăn của quán này khá ngon.” (饭馆 – HSK2 Bài 8)","pre":"这家饭馆的菜","blank":"挺好吃的","post":"。","options":["挺好吃的","好吃挺的","挺吃好的"],"answer":0,"explanation":"挺 đứng ngay trước tính từ 好吃."},{"context":"“Mua cái này đi, mình khá thích màu này.” (颜色 – HSK2 Bài 4)","pre":"买这个吧，我","blank":"挺喜欢这个颜色的","post":"。","options":["挺喜欢这个颜色的","喜欢挺这个颜色的","挺这个颜色喜欢的"],"answer":0,"explanation":"挺 + 喜欢 + tân ngữ + 的."},{"context":"“Môi trường khá tốt, cũng không xa ga tàu điện ngầm lắm.” (离 – HSK2 Bài 9)","pre":"环境","blank":"挺好的","post":"，离地铁站还不远。","options":["挺好的","挺很好","很挺好的"],"answer":0,"explanation":"挺……的; 离 + nơi chốn + 远/近."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我挺很喜欢这个颜色的。","isCorrect":false,"correctVersion":"我挺喜欢这个颜色的。","explanation":"挺 và 很 đều là phó từ mức độ, chỉ dùng một."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这家饭馆的服务挺不错的。","isCorrect":true,"explanation":"挺 + 不错 + 的 — đúng. 服务 (HSK3 Bài 2), 不错 (HSK2 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Môi trường của khu dân cư này khá tốt.”","words":["这个","小区","环境","挺","好","的","。"],"answer":"这个小区环境挺好的。","explanation":"挺 + 好 + 的."},{"type":"sort","context":"Sắp xếp: “Mình khá thích màu này.”","words":["我","挺","喜欢","这个","颜色","的","。"],"answer":"我挺喜欢这个颜色的。","explanation":"挺 đứng trước 喜欢."},{"type":"sort","context":"Sắp xếp: “Món ăn của quán này khá ngon.”","words":["这家","饭馆","的","菜","挺","好吃","的","。"],"answer":"这家饭馆的菜挺好吃的。","explanation":"挺好吃的."},{"type":"sort","context":"Sắp xếp: “Mấy ngày nay anh ấy khá bận.”","words":["他","这几天","挺","忙","的","。"],"answer":"他这几天挺忙的。","explanation":"Thời gian đứng sau chủ ngữ, trước 挺."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 挺……的.","promptLang":"vi","prompt":"Căn nhà này khá to, cũng khá rẻ.","answer":"这个房子挺大的，也挺便宜的。","answerPy":"Zhège fángzi tǐng dà de, yě tǐng piányi de.","explanation":"也 đứng trước 挺; 便宜 (HSK1 Bài 10)."}]},{"point":"Bổ ngữ trình độ (1) — 「tính từ + 坏了」","items":[{"context":"Sách: “Hôm nay chuyển nhà, tôi và Lưu Minh đều mệt rã rời.”","pre":"今天搬家，我和刘明都","blank":"累坏了","post":"。","options":["累坏了","坏累了","很累坏了"],"answer":0,"explanation":"Tính từ + 坏了; không thêm 很."},{"context":"Sách: “Hôm nay tôi chưa ăn trưa và tối, đói lả cả người.” (饿 – HSK3 Bài 2)","pre":"我今天没吃午饭和晚饭，","blank":"饿坏了","post":"。","options":["饿坏了","饿得坏","坏饿了"],"answer":0,"explanation":"饿 + 坏了."},{"context":"Sách: “Trong phòng không có điều hoà, chúng tôi đều nóng muốn chết.”","pre":"房间里没有空调，我们都","blank":"热坏了","post":"。","options":["热坏了","热得坏了","非常热坏了"],"answer":0,"explanation":"热坏了; không chen 得, không thêm 非常."},{"context":"“Mấy ngày nay anh bận tối mắt tối mũi, chắc lúc đi quên tắt rồi.”","pre":"我这几天","blank":"忙坏了","post":"，可能走的时候忘关了。","options":["忙坏了","很忙坏了","坏忙了"],"answer":0,"explanation":"Câu trong Bài khoá 2."},{"context":"“Tôi khát muốn chết, ở đâu mua được nước nhỉ?” (渴 – HSK3 Bài 2)","pre":"我","blank":"渴坏了","post":"，哪里能买水？","options":["渴坏了","渴坏","坏渴了"],"answer":0,"explanation":"Luôn có 了 sau 坏."},{"context":"“Ngoài trời có tuyết, tôi đợi nửa tiếng, lạnh cóng cả người.” (下雪 – HSK1 Bài 12)","pre":"外面下雪了，我等了半个小时，","blank":"冷坏了","post":"。","options":["冷坏了","冷坏","很冷坏了"],"answer":0,"explanation":"冷 + 坏了; bổ ngữ thời lượng 半个小时 (HSK2 Bài 9)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我今天很累坏了。","isCorrect":false,"correctVersion":"我今天累坏了。","explanation":"Đã có 坏了 thì bỏ 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这几天非常忙，大家都累坏了。","isCorrect":true,"explanation":"非常 bổ nghĩa cho 忙 ở vế trước; vế sau 累坏了 — đúng."},{"type":"sort","context":"Sắp xếp: “Mấy ngày nay tôi bận tối mắt tối mũi.”","words":["我","这几天","忙","坏了","。"],"answer":"我这几天忙坏了。","explanation":"Tính từ + 坏了."},{"type":"sort","context":"Sắp xếp: “Tôi khát muốn chết, ở đâu mua được nước?”","words":["我","渴","坏了","，","哪里","能","买","水","？"],"answer":"我渴坏了，哪里能买水？","explanation":"渴坏了 + câu hỏi."},{"type":"sort","context":"Sắp xếp: “Không có điều hoà, mọi người đều nóng muốn chết.”","words":["没有","空调","，","大家","都","热","坏了","。"],"answer":"没有空调，大家都热坏了。","explanation":"都 + 热坏了."},{"type":"sort","context":"Sắp xếp: “Dọn nhà mới cả một ngày, tôi mệt rã rời.”","words":["打扫","了","一天","新家","，","我","累","坏了","。"],"answer":"打扫了一天新家，我累坏了。","explanation":"Bổ ngữ thời lượng 一天 (HSK2 Bài 9) + 累坏了."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 坏了.","promptLang":"vi","prompt":"Cả ngày chưa ăn gì, tôi đói lả rồi.","answer":"我一天没吃东西，饿坏了。","answerPy":"Wǒ yì tiān méi chī dōngxi, è huài le.","explanation":"Thời gian + 没 + V; 饿 (HSK3 Bài 2) + 坏了."}]},{"point":"Phó từ 「就」 và 「才」 — sớm/nhanh và muộn/chậm","items":[{"context":"Sách: “你昨天几点回的家？” — trả lời: về muộn (是……的 – HSK2 Bài 1)","pre":"我昨天晚上十一点","blank":"才回家","post":"。","options":["才回家","才回家了","就回家了"],"answer":0,"explanation":"Muộn → 才, cuối câu không có 了."},{"context":"Sách: “这本书你是什么时候看完的？” — trả lời: đọc rất nhanh","pre":"我两天","blank":"就看完了","post":"。","options":["就看完了","才看完了","看完就了"],"answer":0,"explanation":"Nhanh → 就 + V + 了; 看完 — bổ ngữ kết quả (HSK2 Bài 3)."},{"context":"Sách: “你觉得搬家要准备多长时间？” — trả lời: cần lâu","pre":"最少需要一个星期","blank":"才能准备好","post":"。","options":["才能准备好","就能准备好了","才能准备好了"],"answer":0,"explanation":"最少…… → lâu → 才, không có 了."},{"context":"“Ngân hàng Trung Quốc rất gần, đi bộ vài phút là tới.”","pre":"中国银行很近，走路几分钟","blank":"就能到","post":"。","options":["就能到","才能到","能就到"],"answer":0,"explanation":"很近 → nhanh → 就, đứng trước 能."},{"context":"“Đi tàu hoả đến Bắc Kinh, năm tiếng mới tới.” (火车 – HSK1 Bài 14)","pre":"坐火车去北京，五个小时","blank":"才能到","post":"。","options":["才能到","就能到了","才能到了"],"answer":0,"explanation":"Người nói thấy lâu → 才, không có 了."},{"context":"“Phim tám giờ bắt đầu, bảy giờ rưỡi anh ấy đã đến rồi.” (电影 – HSK1 Bài 7)","pre":"电影八点开始，他七点半","blank":"就到了","post":"。","options":["就到了","才到","才到了"],"answer":0,"explanation":"Đến sớm hơn giờ hẹn → 就……了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我昨天十点才起床了。","isCorrect":false,"correctVersion":"我昨天十点才起床。","explanation":"Câu có 才 không dùng 了 cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我早上五点就起床了。","isCorrect":true,"explanation":"就 + V + 了 — dậy sớm, đúng."},{"type":"sort","context":"Sắp xếp: “Chiều nay anh phải đi bệnh viện, rất muộn mới về được.”","words":["我","下午","要","去","医院","，","很晚","才","能","回来","。"],"answer":"我下午要去医院，很晚才能回来。","explanation":"很晚 + 才 + 能回来."},{"type":"sort","context":"Sắp xếp: “Đi bộ vài phút là tới.”","words":["走路","几分钟","就","能","到","。"],"answer":"走路几分钟就能到。","explanation":"Thời gian ngắn + 就."},{"type":"sort","context":"Sắp xếp: “Em nghĩ phải tháng sau mới chuyển nhà được.”","words":["我","觉得","下个月","才","能","搬家","。"],"answer":"我觉得下个月才能搬家。","explanation":"Thời gian + 才 + 能 + V."},{"type":"sort","context":"Sắp xếp: “Anh ấy mười phút đã làm xong rồi.”","words":["他","十分钟","就","做","完","了","。"],"answer":"他十分钟就做完了。","explanation":"Thời gian ngắn + 就 + V完 + 了."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 才.","promptLang":"vi","prompt":"Sao bây giờ bạn mới đến? Chúng tôi đợi bạn nửa tiếng rồi.","answer":"你怎么现在才来？我们等了你半个小时了。","answerPy":"Nǐ zěnme xiànzài cái lái? Wǒmen děngle nǐ bàn ge xiǎoshí le.","explanation":"才 — đến muộn; bổ ngữ thời lượng + 了 (HSK2 Bài 9)."}]}],"/lessons/hsk3v3-bai-4.html":[{"point":"Cấu trúc 「一……也/都 + 不/没……」 — phủ định hoàn toàn","items":[{"context":"Sách: “Bộ quần áo này không đắt chút nào, bạn mua đi.” (贵)","pre":"这件衣服","blank":"一点儿也不贵","post":"，你买吧。","options":["一点儿也不贵","一点儿也贵","不贵一点儿"],"answer":0,"explanation":"一点儿也 + 不 + tính từ — phủ định hoàn toàn."},{"context":"Sách: “Tháng trước chúng tôi chuyển nhà, chẳng quen ai cả.” (认识; 搬家 – ôn HSK3 Bài 3)","pre":"我们上个月搬家了，","blank":"一个人也不认识","post":"。","options":["一个人也不认识","一个人也认识","不认识一个人也"],"answer":0,"explanation":"一 + lượng từ + danh từ + 也不 + V."},{"context":"Sách: “Tuần này tôi bận quá, chẳng có chút thời gian nào.” (时间)","pre":"这个星期我太忙了，","blank":"一点儿时间也没有","post":"。","options":["一点儿时间也没有","一点儿时间也不有","没有一点儿时间也"],"answer":0,"explanation":"有 phủ định bằng 没: 一点儿 + danh từ + 也没有."},{"context":"“Ở thảo nguyên không lạnh chút nào.”","pre":"草原","blank":"一点儿也不冷","post":"。","options":["一点儿也不冷","不冷一点儿","一点儿不也冷"],"answer":0,"explanation":"Trật tự: 一点儿 + 也 + 不 + tính từ."},{"context":"“Tôi chưa xem bộ phim Trung Quốc nào.” (ôn V过 – HSK2 Bài 4)","pre":"我","blank":"一个中国电影也没看过","post":"。","options":["一个中国电影也没看过","一个中国电影也不看过","没看过一个中国电影也"],"answer":0,"explanation":"Kinh nghiệm với 过 phủ định bằng 没."},{"context":"“Tiểu Lý đợi rất lâu nhưng không hề sốt ruột chút nào.” (着急 – ôn HSK3 Bài 1)","pre":"小李等了很久，但是","blank":"一点儿也没着急","post":"。","options":["一点儿也没着急","一点儿着急也没","没着急一点儿也"],"answer":0,"explanation":"Việc đã qua: 一点儿也 + 没 + V/tính từ; 但是 (ôn HSK2 Bài 8)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个星期我一点儿时间也不有。","isCorrect":false,"correctVersion":"这个星期我一点儿时间也没有。","explanation":"有 phủ định bằng 没."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她一件衣服都不想买。","isCorrect":true,"explanation":"一 + lượng từ + danh từ + 都不 + V — đúng (câu của sách)."},{"type":"sort","context":"Sắp xếp: “Ở thảo nguyên không lạnh chút nào.”","words":["草原","一点儿","也","不","冷","。"],"answer":"草原一点儿也不冷。","explanation":"一点儿也 đứng trước 不冷."},{"type":"sort","context":"Sắp xếp: “Cô ấy chẳng muốn mua bộ quần áo nào cả.”","words":["她","一件","衣服","都","不","想","买","。"],"answer":"她一件衣服都不想买。","explanation":"一件衣服 đứng trước 都不想买."},{"type":"sort","context":"Sắp xếp: “Tôi chẳng muốn ăn chút gì cả.”","words":["我","一点儿","东西","也","不","想","吃","。"],"answer":"我一点儿东西也不想吃。","explanation":"一点儿东西 + 也不想吃."},{"type":"sort","context":"Sắp xếp: “Hôm qua tôi không uống cốc cà phê nào.”","words":["我","昨天","一杯","咖啡","也","没","喝","。"],"answer":"我昨天一杯咖啡也没喝。","explanation":"Việc đã qua dùng 没; 咖啡 (ôn HSK2 Bài 9)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 一点儿也不.","promptLang":"vi","prompt":"Hôm nay không nóng chút nào.","answer":"今天一点儿也不热。","answerPy":"Jīntiān yìdiǎnr yě bú rè.","explanation":"一点儿也 + 不 + tính từ; 热 thanh 4 nên 不 đọc bú."}]},{"point":"Câu so sánh (9) 「A 跟 B 一样」","items":[{"context":"Sách: “Cái cốc của tôi giống cái của bạn.”","pre":"我的杯子","blank":"跟你的一样","post":"。","options":["跟你的一样","一样跟你的","跟一样你的"],"answer":0,"explanation":"A 跟 B 一样; 你的 = 你的杯子."},{"context":"Sách: “Từ học hôm nay không giống hôm qua.”","pre":"今天学习的词","blank":"跟昨天的不一样","post":"。","options":["跟昨天的不一样","跟昨天的一样不","不一样跟昨天的"],"answer":0,"explanation":"Phủ định: 不 đặt ngay trước 一样."},{"context":"Sách: “Tôi cao bằng anh trai tôi.”","pre":"","blank":"我跟哥哥","post":"一样高。","options":["我跟哥哥","我比哥哥","我一样哥哥"],"answer":0,"explanation":"A 跟 B 一样 + tính từ; 比 không đi với 一样."},{"context":"“Khách sạn này không giống những khách sạn khác.”","pre":"这家宾馆","blank":"跟别的都不一样","post":"。","options":["跟别的都不一样","都跟别的一样不","跟别的都一样不"],"answer":0,"explanation":"都 + 不 + 一样."},{"context":"“Phòng khách sạn đẹp đúng như tôi nghĩ.”","pre":"宾馆的房间","blank":"跟我想的一样漂亮","post":"。","options":["跟我想的一样漂亮","跟我想的漂亮一样","跟我想的一样很漂亮"],"answer":0,"explanation":"Tính từ đứng sau 一样, không thêm 很."},{"context":"“Hai cái va li này to bằng nhau.” (箱子 – ôn HSK3 Bài 1)","pre":"这两个箱子","blank":"一样大","post":"。","options":["一样大","大一样","一样很大"],"answer":0,"explanation":"Chủ ngữ số nhiều + 一样 + tính từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我跟姐姐高一样。","isCorrect":false,"correctVersion":"我跟姐姐一样高。","explanation":"Tính từ phải đứng sau 一样."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他买的新手机跟我的一样。","isCorrect":true,"explanation":"A 跟 B 一样 — đúng (câu của sách)."},{"type":"sort","context":"Sắp xếp: “Căn phòng này rộng bằng căn phòng kia.”","words":["这个","房间","跟","那个","房间","一样","大","。"],"answer":"这个房间跟那个房间一样大。","explanation":"A 跟 B + 一样 + 大."},{"type":"sort","context":"Sắp xếp: “Khách sạn này không giống những khách sạn khác.”","words":["这家","宾馆","跟","别的","都","不","一样","。"],"answer":"这家宾馆跟别的都不一样。","explanation":"跟别的 + 都不一样."},{"type":"sort","context":"Sắp xếp: “Tôi cao bằng anh trai tôi.”","words":["我","跟","哥哥","一样","高","。"],"answer":"我跟哥哥一样高。","explanation":"一样 + 高."},{"type":"sort","context":"Sắp xếp: “Hôm nay trời lạnh như hôm qua.”","words":["今天","跟","昨天","一样","冷","。"],"answer":"今天跟昨天一样冷。","explanation":"So sánh thời tiết hai ngày."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 跟……一样.","promptLang":"vi","prompt":"Áo của bạn giống áo của tôi.","answer":"你的衣服跟我的一样。","answerPy":"Nǐ de yīfu gēn wǒ de yíyàng.","explanation":"我的 = 我的衣服, không cần nhắc lại danh từ."}]},{"point":"Cấu trúc 「除了……(以外)，……都/还/也……」","items":[{"context":"Sách (viết lại): “Mẹ thích uống cà phê, cũng thích uống trà.”","pre":"","blank":"除了咖啡以外","post":"，妈妈也喜欢喝茶。","options":["除了咖啡以外","咖啡除了以外","以外除了咖啡"],"answer":0,"explanation":"除了 + A + 以外, rồi vế sau dùng 也 (bổ sung)."},{"context":"Sách (viết lại): “Thầy Vương là người Trung Quốc, các thầy cô khác đều là người nước ngoài.”","pre":"除了王老师以外，","blank":"别的老师都是","post":"外国人。","options":["别的老师都是","别的老师还是","都别的老师是"],"answer":0,"explanation":"Loại trừ → dùng 都; 外国 (ôn HSK2 Bài 2)."},{"context":"Sách (viết lại): “Tôi chỉ muốn ăn hoa quả, những thứ khác đều không muốn ăn.”","pre":"除了水果以外，","blank":"别的东西我都不想吃","post":"。","options":["别的东西我都不想吃","别的东西我也想吃","我都不想吃别的东西"],"answer":0,"explanation":"Danh từ được tổng kết (别的东西) đứng trước 都."},{"context":"“Trừ tôi ra, mọi người đều đang chơi điện thoại.”","pre":"除了我以外，","blank":"大家都","post":"在玩手机。","options":["大家都","大家也","都大家"],"answer":0,"explanation":"Tôi không chơi → loại trừ → 都 (dùng 也 thì nghĩa là tôi cũng chơi)."},{"context":"“Ngoài chiếc va li này ra, còn đồ gì khác không?”","pre":"除了这个行李箱以外，","blank":"还有别的东西","post":"吗？","options":["还有别的东西","都有别的东西","有还别的东西"],"answer":0,"explanation":"Bổ sung → 还 đứng trước động từ 有."},{"context":"“Ngoài bóng đá ra, anh ấy còn thích bóng rổ.” (ôn HSK2 Bài 7)","pre":"除了足球，","blank":"他还喜欢","post":"篮球。","options":["他还喜欢","他都喜欢","还他喜欢"],"answer":0,"explanation":"Chủ ngữ đặt trước 还."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"除了咖啡以外，妈妈都喜欢喝茶。","isCorrect":false,"correctVersion":"除了咖啡以外，妈妈也喜欢喝茶。","explanation":"Bổ sung phải dùng 也/还."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"除了这个汉字，别的汉字我都会写。","isCorrect":true,"explanation":"以外 được lược bỏ; 别的汉字 đứng trước 都 — đúng (câu của sách)."},{"type":"sort","context":"Sắp xếp: “Trừ tôi ra, mọi người đều đang chơi điện thoại.”","words":["除了","我","以外","，","大家","都","在","玩","手机","。"],"answer":"除了我以外，大家都在玩手机。","explanation":"Loại trừ → 都."},{"type":"sort","context":"Sắp xếp: “Ngoài ca hát ra, anh ấy cũng thích nhảy.”","words":["除了","唱歌","以外","，","他","也","喜欢","跳舞","。"],"answer":"除了唱歌以外，他也喜欢跳舞。","explanation":"Bổ sung → 也; 跳舞 (ôn HSK2 Bài 14)."},{"type":"sort","context":"Sắp xếp: “Trừ thầy Vương ra, các thầy cô khác đều là người nước ngoài.”","words":["除了","王老师","以外","，","别的","老师","都","是","外国人","。"],"answer":"除了王老师以外，别的老师都是外国人。","explanation":"别的老师 + 都是."},{"type":"sort","context":"Sắp xếp: “Ngoài cưỡi ngựa ra, chúng tôi còn ngắm trăng.”","words":["除了","骑马","以外","，","我们","还","看了","月亮","。"],"answer":"除了骑马以外，我们还看了月亮。","explanation":"Bổ sung → 还."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 除了……以外，还…….","promptLang":"vi","prompt":"Ngoài hộ chiếu ra, bạn còn phải mang vé máy bay.","answer":"除了护照以外，你还要带机票。","answerPy":"Chúle hùzhào yǐwài, nǐ hái yào dài jīpiào.","explanation":"护照、带 (ôn HSK3 Bài 1); 机票 (ôn HSK2 Bài 15); 还要 = còn phải."}]}],"/lessons/hsk3v3-bai-5.html":[{"point":"Bổ ngữ trình độ (2) 「得很」 — … lắm, … cực kỳ","items":[{"context":"Sách: viết lại câu “这里的东西很贵，我什么也不想买。” bằng 得很.","pre":"这里的东西","blank":"贵得很","post":"，我什么也不想买。","options":["贵得很","很贵得很","得很贵"],"answer":0,"explanation":"很贵 → 贵得很; 什么也不… = gì cũng không…."},{"context":"Sách: viết lại câu “超市里的水果特别多，想吃什么有什么。” bằng 得很.","pre":"超市里的水果","blank":"多得很","post":"，想吃什么有什么。","options":["多得很","很多得","得很多"],"answer":0,"explanation":"特别多 → 多得很; 想吃什么有什么 — đại từ nghi vấn hô ứng (ôn HSK3 Bài 2)."},{"context":"Sách: viết lại câu “我好多天没看见他了，他这个月非常忙。” bằng 得很.","pre":"我好多天没看见他了，他这个月","blank":"忙得很","post":"。","options":["忙得很","非常忙得很","得很忙"],"answer":0,"explanation":"非常忙 → 忙得很; không dùng 非常 cùng 得很."},{"context":"“Bây giờ thời tiết đẹp lắm!”","pre":"现在天气","blank":"好得很","post":"！","options":["好得很","很好得","得很好"],"answer":0,"explanation":"Tính từ + 得很."},{"context":"“Tôi thấy leo núi mệt lắm.” (累 – HSK2 Bài 3)","pre":"我觉得爬山","blank":"累得很","post":"。","options":["累得很","得很累","很累得"],"answer":0,"explanation":"得很 đứng sau tính từ 累."},{"context":"“Cô ấy buồn lắm, ha ha.”","pre":"她","blank":"难过得很","post":"，哈哈。","options":["难过得很","很难过得","难过很得"],"answer":0,"explanation":"难过 + 得很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"房间里面很热得很。","isCorrect":false,"correctVersion":"房间里面热得很。","explanation":"Đã có 得很 thì bỏ 很 trước tính từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件大衣漂亮得很，你穿上试试吧。","isCorrect":true,"explanation":"Tính từ 漂亮 + 得很 — đúng; 试试 lặp động từ (HSK2 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Bây giờ thời tiết đẹp lắm.”","words":["现在","天气","好","得","很","。"],"answer":"现在天气好得很。","explanation":"Tính từ + 得很."},{"type":"sort","context":"Sắp xếp: “Trong phòng nóng lắm.”","words":["房间","里面","热","得","很","。"],"answer":"房间里面热得很。","explanation":"热得很."},{"type":"sort","context":"Sắp xếp: “Siêu thị cách đây xa lắm.”","words":["超市","离","这儿","远","得","很","。"],"answer":"超市离这儿远得很。","explanation":"离 (HSK2 Bài 9) + 远得很."},{"type":"sort","context":"Sắp xếp: “Cô ấy buồn lắm.”","words":["她","难过","得","很","。"],"answer":"她难过得很。","explanation":"难过得很."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 得很.","promptLang":"vi","prompt":"Hôm nay tôi bận lắm, không có thời gian đi leo núi.","answer":"今天我忙得很，没有时间去爬山。","answerPy":"Jīntiān wǒ máng de hěn, méiyǒu shíjiān qù pá shān.","explanation":"Tính từ 忙 + 得很; không thêm 很 trước 忙."}]},{"point":"Lượng từ lặp lại (量词重叠) — 张张 / 个个 / 天天…","items":[{"context":"Sách: hoàn thành hội thoại “你喜欢哪个菜？” (dùng 个)","pre":"你喜欢哪个菜？——","blank":"这些菜我个个都喜欢","post":"。","options":["这些菜我个个都喜欢","这些菜我都个个喜欢","我喜欢个个这些菜"],"answer":0,"explanation":"AA + 都 + V; lượng từ lặp đứng trước 都."},{"context":"Sách: hoàn thành hội thoại “你觉得这些衣服怎么样？” (dùng 件)","pre":"你觉得这些衣服怎么样？——","blank":"件件都很漂亮","post":"。","options":["件件都很漂亮","都件件很漂亮","很漂亮件件都"],"answer":0,"explanation":"件件都 + Adj = 每件都很漂亮."},{"context":"Sách: hoàn thành hội thoại “你今年回北京过年吗？” (dùng 年)","pre":"你今年回北京过年吗？——回，我","blank":"年年都回北京过年","post":"。","options":["年年都回北京过年","都年年回北京过年","回北京过年年年"],"answer":0,"explanation":"年年 = mỗi năm; 过年 (HSK2 Bài 14)."},{"context":"“Những bức ảnh này tấm nào cũng rất đẹp.”","pre":"这些照片","blank":"张张都","post":"非常好看。","options":["张张都","都张张","每张张"],"answer":0,"explanation":"AA + 都."},{"context":"“Tôi muốn ra ngoài chụp ảnh, nhưng ngày nào cũng mưa.”","pre":"我想出去拍照，但是","blank":"天天","post":"下雨。","options":["天天","每天天","天每天"],"answer":0,"explanation":"天天 = 每天; 但是 (HSK2 Bài 8)."},{"context":"“Những quả táo này quả nào cũng rất to.”","pre":"这些苹果","blank":"个个都很大","post":"。","options":["个个都很大","都个个很大","很大个个都"],"answer":0,"explanation":"个个都 + Adj."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这些苹果都个个很大。","isCorrect":false,"correctVersion":"这些苹果个个都很大。","explanation":"Lượng từ lặp phải đứng trước 都."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们班的同学个个都对音乐感兴趣。","isCorrect":true,"explanation":"个个都 + 对……感兴趣 — đúng; 班 (HSK2 Bài 13)."},{"type":"sort","context":"Sắp xếp: “Những bức ảnh này tấm nào cũng rất đẹp.”","words":["这些","照片","张张","都","非常","好看","。"],"answer":"这些照片张张都非常好看。","explanation":"张张都 + Adj."},{"type":"sort","context":"Sắp xếp: “Ngày nào bố tôi cũng đi tập thể dục.”","words":["我","爸爸","天天","都","去","锻炼","身体","。"],"answer":"我爸爸天天都去锻炼身体。","explanation":"天天都 + V."},{"type":"sort","context":"Sắp xếp: “Những bộ quần áo này bộ nào cũng rất đẹp.”","words":["这些","衣服","件件","都","很","漂亮","。"],"answer":"这些衣服件件都很漂亮。","explanation":"件件都 + Adj."},{"type":"sort","context":"Sắp xếp: “Học sinh lớp chúng tôi ai cũng rất cao.”","words":["我们","班","的","学生","个个","都","很","高","。"],"answer":"我们班的学生个个都很高。","explanation":"个个都 + Adj."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng lượng từ lặp lại.","promptLang":"vi","prompt":"Ngày nào cô ấy cũng nghe nhạc.","answer":"她天天都听音乐。","answerPy":"Tā tiāntiān dōu tīng yīnyuè.","explanation":"天天都 + V; không nói 每天天."}]},{"point":"Câu tồn hiện (3) — người / vật xuất hiện hoặc biến mất","items":[{"context":"Sách: hoàn thành câu “教室里……。”","pre":"教室里","blank":"走出来两个学生","post":"。","options":["走出来两个学生","两个学生走出来","走出来这两个学生"],"answer":0,"explanation":"Nơi chốn + V + bổ ngữ xu hướng + số lượng + người; 教室 (HSK2 Bài 2)."},{"context":"Sách: hoàn thành câu “……一个人。”","pre":"","blank":"前边走过来","post":"一个人。","options":["前边走过来","在前边走过来","一个人前边走过来"],"answer":0,"explanation":"Nơi chốn (前边) đứng đầu câu, không cần 在."},{"context":"Sách: hoàn thành câu “……飞过来……。”","pre":"天上","blank":"飞过来几只鸟","post":"。","options":["飞过来几只鸟","几只鸟飞过来","飞过来那几只鸟"],"answer":0,"explanation":"飞过来 + 几只鸟 (鸟 – HSK2 Bài 15); bổ ngữ xu hướng kép (HSK2 Bài 14)."},{"context":"“Phía sau có hai người đi qua.”","pre":"后边","blank":"走过去两个人","post":"。","options":["走过去两个人","两个人走过去","走两个人过去"],"answer":0,"explanation":"Người không xác định đứng sau 走过去."},{"context":"“Trên lầu có mấy người đi xuống.”","pre":"楼上","blank":"下来了几个人","post":"。","options":["下来了几个人","几个人下来了","下来了那几个人"],"answer":0,"explanation":"V + 了 + số lượng + người; 楼 (HSK2 Bài 12)."},{"context":"“Trên cây có mấy con chim bay tới.”","pre":"树上","blank":"飞来了几只鸟","post":"。","options":["飞来了几只鸟","几只鸟飞来了","飞来了鸟几只"],"answer":0,"explanation":"Nơi chốn + V + 来了 + 几只 + 鸟."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"前面开过来很多车。","isCorrect":true,"explanation":"Nơi chốn + 开过来 + 很多车 — đúng câu tồn hiện."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在后边走过去两个人。","isCorrect":false,"correctVersion":"后边走过去两个人。","explanation":"Đầu câu tồn hiện không dùng 在."},{"type":"sort","context":"Sắp xếp: “Phía trước có rất nhiều xe chạy tới.”","words":["前面","开","过来","很多","车","。"],"answer":"前面开过来很多车。","explanation":"Nơi chốn + 开过来 + 很多车."},{"type":"sort","context":"Sắp xếp: “Trên lầu có mấy người đi xuống.”","words":["楼上","下来","了","几个","人","。"],"answer":"楼上下来了几个人。","explanation":"Nơi chốn + 下来了 + 几个人."},{"type":"sort","context":"Sắp xếp: “Trên cây có mấy con chim bay tới.”","words":["树上","飞来","了","几只","鸟","。"],"answer":"树上飞来了几只鸟。","explanation":"Nơi chốn + 飞来了 + 几只鸟."},{"type":"sort","context":"Sắp xếp: “Lớp chúng tôi có một bạn học mới đến.”","words":["我们","班","来","了","一个","新","同学","。"],"answer":"我们班来了一个新同学。","explanation":"我们班 làm nơi chốn; 来了 + 一个新同学 (班 – HSK2 Bài 13)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng câu tồn hiện.","promptLang":"vi","prompt":"Phía trước có một người đi tới.","answer":"前面走过来一个人。","answerPy":"Qiánmiàn zǒu guòlai yí ge rén.","explanation":"Nơi chốn + 走过来 + 一个人 (bổ ngữ xu hướng kép – HSK2 Bài 14)."}]},{"point":"Câu ghép rút gọn 「……了……就……」 — xong việc này là làm ngay việc kia","items":[{"context":"Sách: hoàn thành câu “爸爸每次上了飞机就……。”","pre":"爸爸每次上了飞机就","blank":"睡觉","post":"。","options":["睡觉","睡觉过","着睡觉"],"answer":0,"explanation":"Thói quen (每次): V₁ + 了 … 就 + V₂, cuối câu không cần 了; 次 (HSK2 Bài 1)."},{"context":"Sách: hoàn thành câu “今天我没吃早饭，所以下了课就……。”","pre":"今天我没吃早饭，所以下了课就","blank":"去吃饭了","post":"。","options":["去吃饭了","了去吃饭","去吃饭过"],"answer":0,"explanation":"Việc đã xảy ra → thêm 了 cuối câu; 所以 (HSK2 Bài 4)."},{"context":"Sách: hoàn thành câu “我今天有点儿不舒服，……。”","pre":"我今天有点儿不舒服，","blank":"下了班就回家休息","post":"。","options":["下了班就回家休息","下班了就休息回家","就下了班回家休息"],"answer":0,"explanation":"V₁ + 了 + O + 就 + V₂; 舒服 (HSK2 Bài 6)."},{"context":"“Nghe xong buổi hoà nhạc thì em đến nhà chị ăn cơm nhé.”","pre":"你","blank":"听完了音乐会就来","post":"我家吃饭。","options":["听完了音乐会就来","听完音乐会了就来","就听完了音乐会来"],"answer":0,"explanation":"V + 完 + 了 + tân ngữ + 就 + V₂."},{"context":"“Tôi ăn sáng xong là đi học luôn.” (việc đã xảy ra)","pre":"我吃了早饭就","blank":"去学校了","post":"。","options":["去学校了","了去学校","去学校过"],"answer":0,"explanation":"Hành động 2 đã hoàn thành → 了 cuối câu."},{"context":"“Hôm qua chúng tôi tan học xong là về nhà.”","pre":"昨天我们","blank":"下了课就回家了","post":"。","options":["下了课就回家了","下课了就回家","就下了课回家了"],"answer":0,"explanation":"Việc đã xảy ra: V₁ + 了 … 就 + V₂ + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我吃早饭了就去学校了。","isCorrect":false,"correctVersion":"我吃了早饭就去学校了。","explanation":"了 đứng ngay sau động từ thứ nhất."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"明天你下了班就给我打电话吧。","isCorrect":true,"explanation":"Việc sắp làm: V₁ + 了 … 就 + V₂, cuối câu không cần 了 — đúng; 给 + người + 打电话 (HSK2 Bài 1)."},{"type":"sort","context":"Sắp xếp: “Nghe xong buổi hoà nhạc thì em đến nhà chị ăn cơm nhé.”","words":["你","听","完","了","音乐会","就","来","我家","吃饭","。"],"answer":"你听完了音乐会就来我家吃饭。","explanation":"V + 完 + 了 + O + 就 + V₂."},{"type":"sort","context":"Sắp xếp: “Tôi ăn sáng xong là đi học luôn.”","words":["我","吃","了","早饭","就","去","学校","了","。"],"answer":"我吃了早饭就去学校了。","explanation":"了 sau 吃, 就 trước 去, 了 cuối câu."},{"type":"sort","context":"Sắp xếp: “Hôm qua chúng tôi tan học xong là về nhà.”","words":["昨天","我们","下","了","课","就","回家","了","。"],"answer":"昨天我们下了课就回家了。","explanation":"下了课 + 就 + 回家了."},{"type":"sort","context":"Sắp xếp: “Ngày mai bạn đến Bắc Kinh thì gọi điện cho tôi nhé.”","words":["明天","你","到","了","北京","就","给","我","打","电话","吧","。"],"answer":"明天你到了北京就给我打电话吧。","explanation":"Việc sắp làm, cuối câu dùng 吧."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng ……了……就…….","promptLang":"vi","prompt":"Mỗi ngày tôi tan làm là đi tập thể dục.","answer":"我每天下了班就去锻炼身体。","answerPy":"Wǒ měi tiān xiàle bān jiù qù duànliàn shēntǐ.","explanation":"Thói quen: V₁ + 了 … 就 + V₂, cuối câu không thêm 了."}]}],"/lessons/hsk3v3-bai-6.html":[{"point":"Cấu trúc cố định 「该……了」 — đến lúc phải … rồi","items":[{"context":"Sách: hoàn thành câu “天已经黑了，……。”","pre":"天已经黑了，","blank":"我们该回家了","post":"。","options":["我们该回家了","我们该回家","我们了该回家"],"answer":0,"explanation":"该 + V + 了: đã đến lúc về nhà; 黑 (HSK2 Bài 4 – 黑色)."},{"context":"Sách: hoàn thành câu “电影就要开始了，……。”","pre":"电影就要开始了，","blank":"我们该进去了","post":"。","options":["我们该进去了","我们该进去","该了我们进去"],"answer":0,"explanation":"就要……了 — sắp (HSK2 Bài 10); 进去 (HSK2 Bài 4)."},{"context":"Sách: hoàn thành câu “他下个星期过生日，……。”","pre":"他下个星期过生日，","blank":"我们该给他准备礼物了","post":"。","options":["我们该给他准备礼物了","我们该给他准备礼物","我们该了给他准备礼物"],"answer":0,"explanation":"该 + 给他 + 准备礼物 + 了; 准备、礼物 (HSK2 Bài 5); 过生日 (HSK2 Bài 6)."},{"context":"Sách: chọn từ “飞机马上就要起飞了，你的手机……关机了。” (关机 guānjī – tắt máy)","pre":"飞机马上就要起飞了，你的手机","blank":"该","post":"关机了。","options":["该","后来","以前"],"answer":0,"explanation":"该……了 — đến lúc phải tắt máy; 起飞 (ôn HSK3 Bài 4)."},{"context":"Sách (miêu tả tranh): “还有半个多小时，你……。” — tiễn bạn ở ga","pre":"还有半个多小时，你","blank":"该进站了","post":"。","options":["该进站了","进站该了","该进站"],"answer":0,"explanation":"该 + 进站 + 了: đến lúc vào ga rồi."},{"context":"“Chúng ta nên mua vé đi Thượng Hải rồi.”","pre":"咱们","blank":"该买去上海的票了","post":"。","options":["该买去上海的票了","买去上海的票该了","该了买去上海的票"],"answer":0,"explanation":"该 + V + tân ngữ + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"已经很晚了，我该睡觉了。","isCorrect":true,"explanation":"该 + 睡觉 + 了 — đúng; 已经……了 (HSK2 Bài 1)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"现在该是吃饭了。","isCorrect":false,"correctVersion":"现在该吃饭了。","explanation":"Sau 该 dùng thẳng động từ, bỏ 是."},{"type":"sort","context":"Sắp xếp: “Đã muộn lắm rồi, tôi phải đi ngủ thôi.”","words":["已经","很","晚","了","，","我","该","睡觉","了","。"],"answer":"已经很晚了，我该睡觉了。","explanation":"我 + 该 + 睡觉 + 了."},{"type":"sort","context":"Sắp xếp: “Chúng ta nên mua vé đi Thượng Hải rồi.”","words":["咱们","该","买","去","上海","的","票","了","。"],"answer":"咱们该买去上海的票了。","explanation":"该 + 买 + (去上海的) 票 + 了; 咱们 (ôn HSK3 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Còn nửa tiếng nữa, bạn phải vào ga rồi.”","words":["还有","半个","小时","，","你","该","进站","了","。"],"answer":"还有半个小时，你该进站了。","explanation":"还有 + thời gian; 该进站了."},{"type":"sort","context":"Sắp xếp: “Trời lạnh rồi, bạn nên mua áo khoác mới thôi.”","words":["天","冷","了","，","你","该","买","新","大衣","了","。"],"answer":"天冷了，你该买新大衣了。","explanation":"该 + 买新大衣 + 了; 大衣 (ôn HSK3 Bài 5)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 该……了.","promptLang":"vi","prompt":"Sáu giờ rồi, chúng ta phải về nhà thôi.","answer":"六点了，我们该回家了。","answerPy":"Liù diǎn le, wǒmen gāi huí jiā le.","explanation":"该 + 回家 + 了; 了 cuối câu không được thiếu."}]},{"point":"Câu ghép giả định 「如果……，就……」 — nếu … thì …","items":[{"context":"Sách: hoàn thành câu “如果明天下雨，……。”","pre":"如果明天下雨，","blank":"我们就不去爬山了","post":"。","options":["我们就不去爬山了","就我们不去爬山了","所以我们不去爬山了"],"answer":0,"explanation":"Chủ ngữ 我们 đứng trước 就; 爬山 (ôn HSK3 Bài 5)."},{"context":"Sách: hoàn thành câu “如果我觉得太累了，……。”","pre":"如果我觉得太累了，","blank":"就休息一会儿","post":"。","options":["就休息一会儿","所以休息一会儿","休息就一会儿"],"answer":0,"explanation":"Vế sau cùng chủ ngữ 我 nên lược; 一会儿 (HSK2 Bài 5); 累 (HSK2 Bài 3)."},{"context":"Sách: hoàn thành câu “……，就跟朋友一起去旅游。”","pre":"","blank":"如果放假了","post":"，就跟朋友一起去旅游。","options":["如果放假了","虽然放假了","放假了如果"],"answer":0,"explanation":"如果 đứng đầu mệnh đề giả thiết; 虽然 (HSK2 Bài 8) không đi với 就; 跟 (HSK2 Bài 5)."},{"context":"Sách (miêu tả tranh): “……，就给我们打电话。” — dặn bạn khi đến nơi","pre":"","blank":"如果到了上海","post":"，就给我们打电话。","options":["如果到了上海","因为到了上海","到了上海如果"],"answer":0,"explanation":"Giả thiết (chưa xảy ra) dùng 如果; 给 + người + 打电话 (HSK2 Bài 1)."},{"context":"“Nếu không đi nhầm thì đã đến từ hai mươi phút trước rồi.”","pre":"如果没走错，","blank":"二十分钟以前就到了","post":"。","options":["二十分钟以前就到了","就二十分钟以前到了","二十分钟就以前到了"],"answer":0,"explanation":"就 đứng ngay trước động từ 到; 以前 — từ mới bài này."},{"context":"“Nếu bạn cần giúp đỡ thì gọi điện cho tôi.”","pre":"如果你需要帮忙，","blank":"就给我打电话","post":"。","options":["就给我打电话","给我就打电话","所以给我打电话"],"answer":0,"explanation":"就 + cụm giới từ 给我 + V; 需要 (ôn HSK3 Bài 3)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"如果有时间，我就去上海玩几天。","isCorrect":true,"explanation":"Chủ ngữ 我 đứng trước 就 — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"如果明天不下雨，就我们去爬山。","isCorrect":false,"correctVersion":"如果明天不下雨，我们就去爬山。","explanation":"Chủ ngữ vế sau đặt trước 就."},{"type":"sort","context":"Sắp xếp: “Nếu có thời gian, tôi sẽ đi Thượng Hải chơi vài ngày.”","words":["如果","有","时间","，","我","就","去","上海","玩","几天","。"],"answer":"如果有时间，我就去上海玩几天。","explanation":"如果 + giả thiết，我 + 就 + V."},{"type":"sort","context":"Sắp xếp: “Nếu bạn không khoẻ thì ở nhà nghỉ ngơi đi.”","words":["如果","你","不","舒服","，","就","在家","休息","吧","。"],"answer":"如果你不舒服，就在家休息吧。","explanation":"舒服 (HSK2 Bài 6); 吧 — lời khuyên."},{"type":"sort","context":"Sắp xếp: “Nếu ngày mai trời đẹp, chúng ta sẽ đi leo núi.”","words":["如果","明天","天气","好","，","我们","就","去","爬山","。"],"answer":"如果明天天气好，我们就去爬山。","explanation":"我们 + 就 + 去爬山."},{"type":"sort","context":"Sắp xếp: “Nếu bạn đói thì đặt đồ ăn giao tận nơi đi.”","words":["如果","你","饿","了","，","就","点","外卖","吧","。"],"answer":"如果你饿了，就点外卖吧。","explanation":"饿、外卖 (ôn HSK3 Bài 2)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 如果……，就…….","promptLang":"vi","prompt":"Nếu bạn không mang tiền thì có thể quẹt thẻ tín dụng.","answer":"如果你没带钱，就可以刷信用卡。","answerPy":"Rúguǒ nǐ méi dài qián, jiù kěyǐ shuā xìnyòngkǎ.","explanation":"刷 — từ mới bài này; 信用卡 (ôn HSK3 Bài 3)."}]},{"point":"Cụm từ cố định 「越来越」 — càng ngày càng …","items":[{"context":"Sách: hoàn thành câu “这些年的天气……。”","pre":"这些年的天气","blank":"越来越热了","post":"。","options":["越来越热了","越来越很热了","很越来越热了"],"answer":0,"explanation":"越来越 + Adj + 了 — không thêm 很."},{"context":"Sách: hoàn thành câu “他每天都运动，现在……。”","pre":"他每天都运动，现在","blank":"身体越来越好了","post":"。","options":["身体越来越好了","身体越来越非常好了","越来越身体好了"],"answer":0,"explanation":"运动 (HSK2 Bài 7); 身体 (HSK2 Bài 11)."},{"context":"Sách: hoàn thành câu “孩子还没有到家，妈妈……。”","pre":"孩子还没有到家，妈妈","blank":"越来越着急了","post":"。","options":["越来越着急了","越来越很着急了","着急越来越了"],"answer":0,"explanation":"着急 zháojí (ôn HSK3 Bài 1) — tính từ chỉ tâm trạng."},{"context":"Sách (miêu tả tranh): “现在路上的车……，我觉得咱们可能会迟到。”","pre":"现在路上的车","blank":"越来越多","post":"，我觉得咱们可能会迟到。","options":["越来越多","越来越很多","多越来越"],"answer":0,"explanation":"可能 (HSK2 Bài 13); 迟到 — từ mới bài này."},{"context":"“Tôi ngày càng thích cuộc sống ở đây.” (生活 shēnghuó – cuộc sống)","pre":"我","blank":"越来越喜欢","post":"这里的生活了。","options":["越来越喜欢","越来越很喜欢","喜欢越来越"],"answer":0,"explanation":"越来越 + động từ tâm lý 喜欢."},{"context":"“Cậu ấy chạy ngày càng nhanh.”","pre":"他跑得","blank":"越来越快","post":"了。","options":["越来越快","越来越很快","快越来越"],"answer":0,"explanation":"V + 得 + 越来越 + Adj (bổ ngữ trạng thái – HSK2 Bài 7)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她越来越高，也越来越漂亮了。","isCorrect":true,"explanation":"Hai lần 越来越 + Adj — đúng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"现在越来越人喜欢坐高铁。","isCorrect":false,"correctVersion":"现在喜欢坐高铁的人越来越多。","explanation":"越来越 không đứng trước danh từ; đưa “người thích đi tàu cao tốc” lên làm chủ ngữ."},{"type":"sort","context":"Sắp xếp: “Phía trước ngày càng nhiều người.”","words":["前面","的","人","越来越","多","。"],"answer":"前面的人越来越多。","explanation":"越来越 + 多."},{"type":"sort","context":"Sắp xếp: “Tiếng Trung của em ngày càng tốt.”","words":["你的","汉语","越来越","好","了","。"],"answer":"你的汉语越来越好了。","explanation":"越来越好了 — 了 chỉ sự thay đổi."},{"type":"sort","context":"Sắp xếp: “Trời ngày càng lạnh, bạn mặc áo khoác vào đi.”","words":["天气","越来越","冷","了","，","你","穿上","大衣","吧","。"],"answer":"天气越来越冷了，你穿上大衣吧。","explanation":"穿上、大衣 (ôn HSK3 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Ngày càng có nhiều người thích đi tàu cao tốc.”","words":["喜欢","坐","高铁","的","人","越来越","多","了","。"],"answer":"喜欢坐高铁的人越来越多了。","explanation":"Định ngữ dài + 的 + 人 (ôn HSK3 Bài 1) + 越来越多."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 越来越.","promptLang":"vi","prompt":"Khu dân cư này ngày càng sạch sẽ.","answer":"这个小区越来越干净了。","answerPy":"Zhège xiǎoqū yuè lái yuè gānjìng le.","explanation":"小区 (ôn HSK3 Bài 3); 干净 (ôn HSK3 Bài 4)."}]}],"/lessons/hsk3v3-bai-7.html":[{"point":"Câu liên động (2) 「động từ₁ + 着 + động từ₂」 — làm việc 2 theo cách / trạng thái 1","items":[{"context":"Sách: nhìn tranh hoàn thành câu (Vương Nhất Tuyết đứng trong bếp nấu ăn).","pre":"王一雪","blank":"站着做饭","post":"。","options":["站着做饭","站做饭着","做饭站着"],"answer":0,"explanation":"站着 (cách thức) + 做饭 (hành động chính); 站 (ôn HSK3 Bài 1)."},{"context":"Sách: nhìn tranh hoàn thành câu (Lưu Tiểu Tuyết ngồi trên ghế sofa bưng bát ăn cơm).","pre":"刘小雪","blank":"坐着吃饭","post":"。","options":["坐着吃饭","坐吃着饭","吃饭坐着"],"answer":0,"explanation":"坐着 + 吃饭: ngồi ăn cơm."},{"context":"Sách: nhìn tranh hoàn thành câu (người phục vụ mỉm cười ghi món cho khách).","pre":"服务员","blank":"笑着帮他点菜","post":"。","options":["笑着帮他点菜","笑帮他着点菜","帮他点菜笑着"],"answer":0,"explanation":"笑着 + V: vừa cười vừa làm; 点菜 (ôn HSK3 Bài 2)."},{"context":"“Chúng mình có thể đi bộ đến đó.”","pre":"咱们可以","blank":"走着","post":"去。","options":["走着","走路着","着走"],"answer":0,"explanation":"走着去 = đi bộ đi; 咱们 (ôn HSK3 Bài 3)."},{"context":"“Em trai vừa ăn táo vừa làm bài tập.”","pre":"弟弟","blank":"吃着苹果","post":"写作业。","options":["吃着苹果","吃苹果着","着吃苹果"],"answer":0,"explanation":"V₁ + 着 + O₁ + V₂ + O₂: 着 đứng ngay sau 吃."},{"context":"“Cô ấy thích vừa nghe nhạc vừa chạy bộ.”","pre":"她喜欢","blank":"听着音乐","post":"跑步。","options":["听着音乐","听音乐着","着听音乐"],"answer":0,"explanation":"音乐 (ôn HSK3 Bài 5); 跑步 (HSK2 Bài 7)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们走路着去商场吧。","isCorrect":false,"correctVersion":"我们走着去商场吧。","explanation":"着 đi ngay sau động từ 走: 走着去."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"妈妈笑着说：“你长高了！”","isCorrect":true,"explanation":"笑着 + 说 — cách thức của hành động nói; 长高 (ôn HSK3 Bài 1)."},{"type":"sort","context":"Sắp xếp: “Họ ngồi xem ti vi.”","words":["他们","坐","着","看","电视","。"],"answer":"他们坐着看电视。","explanation":"V₁ + 着 + V₂ + O."},{"type":"sort","context":"Sắp xếp: “Chúng mình đi bộ đến siêu thị nhé.”","words":["咱们","走","着","去","超市","吧","。"],"answer":"咱们走着去超市吧。","explanation":"走着 + 去 + nơi chốn; 吧 đề nghị."},{"type":"sort","context":"Sắp xếp: “Cô ấy mặc chiếc váy màu vàng đi nghe hoà nhạc.”","words":["她","穿","着","黄色的","裙子","去","听","音乐会","。"],"answer":"她穿着黄色的裙子去听音乐会。","explanation":"穿着 + O₁ + 去 + V₂ + O₂; 音乐会 (ôn HSK3 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Bố tôi thích ngồi đọc sách.”","words":["我","爸爸","喜欢","坐","着","看书","。"],"answer":"我爸爸喜欢坐着看书。","explanation":"坐着 + 看书."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 着.","promptLang":"vi","prompt":"Hôm qua tôi đi xe đạp đến trường.","answer":"昨天我骑着自行车去学校了。","answerPy":"Zuótiān wǒ qízhe zìxíngchē qù xuéxiào le.","explanation":"骑着自行车 (cách thức) + 去学校; 骑 (ôn HSK3 Bài 4)."}]},{"point":"Câu so sánh (10) 「A 不比 B + tính từ」 — A cũng chẳng hơn B (là mấy)","items":[{"context":"Sách: A: 天中学中文的时间更长，他的中文水平比家月高吗？","pre":"他的中文水平","blank":"不比家月高多少","post":"。","options":["不比家月高多少","比家月不高多少","不比家月很高"],"answer":0,"explanation":"Phản bác ý kiến: A 不比 B + Adj + 多少; 水平 (ôn HSK3 Bài 5)."},{"context":"Sách: A: 你姐姐一个人住，她一定比你更会做饭吧？","pre":"她做饭","blank":"不比我好多少","post":"。","options":["不比我好多少","比我不好多少","不比我很好"],"answer":0,"explanation":"Phản bác: chị ấy nấu cũng chẳng hơn tôi là mấy; 一定 (ôn HSK3 Bài 4)."},{"context":"Sách: A: 我觉得篮球比足球更有意思，你觉得呢？","pre":"篮球","blank":"不比足球有意思","post":"，你多跟我去踢一踢足球就知道了。","options":["不比足球有意思","比足球不有意思","不比足球很有意思"],"answer":0,"explanation":"Phản bác ý kiến người khác bằng 不比; 篮球、足球 (HSK2 Bài 7)."},{"context":"“Váy cũng không đắt hơn quần soóc bao nhiêu.”","pre":"裙子","blank":"不比","post":"短裤贵多少。","options":["不比","比不","不是比"],"answer":0,"explanation":"Thứ tự đúng: 不 + 比."},{"context":"“Anh ấy chạy cũng không nhanh hơn tôi là mấy.”","pre":"他跑得","blank":"不比我快多少","post":"。","options":["不比我快多少","比我不快多少","不比我很快"],"answer":0,"explanation":"Bổ ngữ trạng thái (HSK2 Bài 7) + 不比."},{"context":"“Anh thấy chiếc váy kia đẹp hơn quần soóc.”","pre":"我觉得那条裙子比短裤","blank":"更","post":"好看。","options":["更","很","非常"],"answer":0,"explanation":"Trong câu 比, trước tính từ chỉ dùng 更 / 还 (HSK2 Bài 8), không dùng 很 / 非常."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个西瓜不比那个很甜。","isCorrect":false,"correctVersion":"这个西瓜不比那个甜。","explanation":"Sau 不比 B dùng tính từ trơn, bỏ 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"坐地铁不比打车慢多少，而且便宜多了。","isCorrect":true,"explanation":"不比 + B + Adj + 多少 — đúng; 地铁 (HSK2 Bài 12), 打车 (HSK2 Bài 2), 便宜多了 (HSK2 Bài 12)."},{"type":"sort","context":"Sắp xếp: “Váy cũng không đắt hơn quần soóc bao nhiêu.”","words":["裙子","不","比","短裤","贵","多少","。"],"answer":"裙子不比短裤贵多少。","explanation":"A + 不比 + B + Adj + 多少."},{"type":"sort","context":"Sắp xếp: “Tiếng Trung của anh ấy cũng chẳng giỏi hơn bạn.”","words":["他的","中文","不","比","你","好","。"],"answer":"他的中文不比你好。","explanation":"A + 不比 + B + Adj."},{"type":"sort","context":"Sắp xếp: “Hôm nay cũng không nóng hơn hôm qua là mấy.”","words":["今天","不","比","昨天","热","多少","。"],"answer":"今天不比昨天热多少。","explanation":"不比……热多少."},{"type":"sort","context":"Sắp xếp: “Váy đẹp hơn quần soóc.”","words":["裙子","比","短裤","更","好看","。"],"answer":"裙子比短裤更好看。","explanation":"比 + 更 + Adj."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 不比.","promptLang":"vi","prompt":"Khách sạn này cũng không đắt hơn khách sạn kia bao nhiêu, hơn nữa còn sạch hơn.","answer":"这家宾馆不比那家贵多少，而且更干净。","answerPy":"Zhè jiā bīnguǎn bù bǐ nà jiā guì duōshao, érqiě gèng gānjìng.","explanation":"宾馆、干净 (ôn HSK3 Bài 4); 而且 (từ mới bài này)."}]},{"point":"Bổ ngữ trình độ (3) 「极了」 — … cực kỳ, … vô cùng","items":[{"context":"Sách: hoàn thành câu “她做的中国菜……”","pre":"她做的中国菜","blank":"好吃极了","post":"。","options":["好吃极了","很好吃极了","极了好吃"],"answer":0,"explanation":"Adj + 极了; định ngữ 她做的 (HSK2 Bài 2)."},{"context":"Sách: hoàn thành câu “我昨天晚上睡得……”","pre":"我昨天晚上睡得","blank":"好极了","post":"。","options":["好极了","极了好","很好极了"],"answer":0,"explanation":"Bổ ngữ trạng thái 睡得 (HSK2 Bài 7) + 好极了."},{"context":"Sách: hoàn thành câu “这些水果五块钱，真是……”","pre":"这些水果五块钱，真是","blank":"便宜极了","post":"。","options":["便宜极了","便宜极","很便宜极了"],"answer":0,"explanation":"便宜 (HSK1 Bài 10) + 极了."},{"context":"“Mùa hè năm nay nóng vô cùng.”","pre":"今年夏天","blank":"热极了","post":"。","options":["热极了","热极","很热极了"],"answer":0,"explanation":"Adj + 极了 (có 了)."},{"context":"“Cuốn sách này tôi thích vô cùng.”","pre":"这本书我","blank":"喜欢极了","post":"。","options":["喜欢极了","极了喜欢","很喜欢极了"],"answer":0,"explanation":"Động từ tâm lý + 极了."},{"context":"“Nghe nói con thi rất tốt, mẹ vui cực kỳ.”","pre":"听说你考得很好，妈妈","blank":"高兴极了","post":"。","options":["高兴极了","高兴极","非常高兴极了"],"answer":0,"explanation":"听说 (ôn HSK3 Bài 3); không dùng 非常 cùng 极了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这块冰西瓜非常甜极了。","isCorrect":false,"correctVersion":"这块冰西瓜甜极了。","explanation":"Bỏ 非常: đã có 极了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你的照片照得漂亮极了！","isCorrect":true,"explanation":"Bổ ngữ trạng thái + 极了 — đúng; 照 (ôn HSK3 Bài 5)."},{"type":"sort","context":"Sắp xếp: “Miếng dưa hấu ướp lạnh này ngọt cực kỳ.”","words":["这块","冰","西瓜","甜","极了","。"],"answer":"这块冰西瓜甜极了。","explanation":"甜 + 极了."},{"type":"sort","context":"Sắp xếp: “Mùa hè năm nay nóng vô cùng.”","words":["今年","夏天","热","极了","。"],"answer":"今年夏天热极了。","explanation":"热极了."},{"type":"sort","context":"Sắp xếp: “Món ăn mẹ nấu ngon cực kỳ.”","words":["妈妈","做","的","菜","好吃","极了","。"],"answer":"妈妈做的菜好吃极了。","explanation":"Định ngữ 妈妈做的 + 好吃极了."},{"type":"sort","context":"Sắp xếp: “Hôm nay được nghỉ, tôi vui vô cùng.”","words":["今天","休息","，","我","高兴","极了","。"],"answer":"今天休息，我高兴极了。","explanation":"高兴极了; 休息 (HSK1 Bài 5)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 极了.","promptLang":"vi","prompt":"Khu dân cư mới của chúng tôi đẹp vô cùng.","answer":"我们的新小区漂亮极了。","answerPy":"Wǒmen de xīn xiǎoqū piàoliang jí le.","explanation":"小区 (ôn HSK3 Bài 3) + 漂亮极了; không thêm 很."}]},{"point":"Câu ghép tăng tiến 「不但……，而且……」 — không những… mà còn…","items":[{"context":"Sách: A: 为什么很多人喜欢坐高铁？","pre":"因为高铁","blank":"不但很快，而且很舒服","post":"。","options":["不但很快，而且很舒服","不但很快，但是很舒服","而且很快，不但很舒服"],"answer":0,"explanation":"Cùng chủ ngữ 高铁 → 不但 sau chủ ngữ; 高铁 (ôn HSK3 Bài 6), 舒服 (HSK2 Bài 6)."},{"context":"Sách: A: 你为什么喜欢在网上买东西？","pre":"因为在网上买东西","blank":"不但便宜，而且很方便","post":"。","options":["不但便宜，而且很方便","便宜不但，而且很方便","不但便宜，所以很方便"],"answer":0,"explanation":"网上 (HSK2 Bài 2); 方便 (ôn HSK3 Bài 2)."},{"context":"Sách: A: 你们班谁会打篮球？","pre":"你们班谁会打篮球？——","blank":"不但天中会打篮球，而且家月也会打","post":"。","options":["不但天中会打篮球，而且家月也会打","天中不但会打篮球，而且家月也会打","不但天中会打篮球，而且家月会也打"],"answer":0,"explanation":"Khác chủ ngữ → 不但 trước 天中, vế sau có 也; 打篮球 (HSK2 Bài 7)."},{"context":"“Ti vi bây giờ không những rẻ mà còn dùng rất tiện.”","pre":"现在的电视","blank":"不但","post":"便宜，而且用着非常方便。","options":["不但","但是","虽然"],"answer":0,"explanation":"不但……而且…… — tăng tiến."},{"context":"“Gia Nguyệt không những thích hát mà còn hát rất hay.”","pre":"家月不但喜欢唱歌，","blank":"而且","post":"唱得很好听。","options":["而且","但是","所以"],"answer":0,"explanation":"Vế sau dùng 而且; bổ ngữ trạng thái 唱得很好听 (HSK2 Bài 7)."},{"context":"“Ở lớp chúng tôi, không những Gia Nguyệt biết nói tiếng Hán mà Thiên Trung cũng biết.”","pre":"在我们班，","blank":"不但家月","post":"会说汉语，而且天中也会说汉语。","options":["不但家月","家月不但","家月但是"],"answer":0,"explanation":"Khác chủ ngữ → 不但 + 家月."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这家饭馆的菜不但好吃，但是很便宜。","isCorrect":false,"correctVersion":"这家饭馆的菜不但好吃，而且很便宜。","explanation":"Tăng tiến dùng 而且, không dùng 但是."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不但我喜欢这个小区，而且我爸爸妈妈也很喜欢。","isCorrect":true,"explanation":"Khác chủ ngữ: 不但 + 我…，而且 + 爸爸妈妈 + 也… — đúng; 小区 (ôn HSK3 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Ti vi bây giờ không những rẻ mà còn dùng rất tiện.”","words":["现在的","电视","不但","便宜","，","而且","用着","非常","方便","。"],"answer":"现在的电视不但便宜，而且用着非常方便。","explanation":"Cùng chủ ngữ: S + 不但 A，而且 B."},{"type":"sort","context":"Sắp xếp: “Cô ấy không những biết nấu ăn mà còn nấu rất ngon.”","words":["她","不但","会","做饭","，","而且","做","得","很","好吃","。"],"answer":"她不但会做饭，而且做得很好吃。","explanation":"不但 sau chủ ngữ 她; 做得很好吃 (HSK2 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Không những tôi muốn đi, mà em gái tôi cũng muốn đi.”","words":["不但","我","想","去","，","而且","我","妹妹","也","想","去","。"],"answer":"不但我想去，而且我妹妹也想去。","explanation":"Khác chủ ngữ: 不但 + S₁…，而且 + S₂ + 也…."},{"type":"sort","context":"Sắp xếp: “Dưa hấu ở đây không những to mà còn rất ngọt.”","words":["这里的","西瓜","不但","大","，","而且","很","甜","。"],"answer":"这里的西瓜不但大，而且很甜。","explanation":"Cùng chủ ngữ 西瓜."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 不但……，而且…….","promptLang":"vi","prompt":"Mua đồ trên mạng không những rẻ mà còn rất tiện.","answer":"在网上买东西不但便宜，而且很方便。","answerPy":"Zài wǎngshang mǎi dōngxi búdàn piányi, érqiě hěn fāngbiàn.","explanation":"Cùng chủ ngữ (在网上买东西) → 不但 sau chủ ngữ."}]}],"/lessons/hsk3v3-bai-8.html":[{"point":"Bổ ngữ xu hướng mở rộng (1) 「下去」 — tiếp tục, thêm nữa","items":[{"context":"Sách: hoàn thành câu “现在她很喜欢汉语，还打算……。”","pre":"现在她很喜欢汉语，还打算","blank":"一直学下去","post":"。","options":["一直学下去","一直下去学","一直学下来"],"answer":0,"explanation":"V + 下去 = tiếp tục làm; 打算 = dự định."},{"context":"Sách: hoàn thành câu “这本书太有意思了，我想一直……。”","pre":"这本书太有意思了，我想一直","blank":"看下去","post":"。","options":["看下去","下去看","看下来"],"answer":0,"explanation":"看下去 = đọc tiếp; 有意思 (HSK2 Bài 8)."},{"context":"Sách: hoàn thành câu “我不想在这里……，下个星期就去找新房子。”","pre":"我不想在这里","blank":"住下去","post":"，下个星期就去找新房子。","options":["住下去","下去住","住上去"],"answer":0,"explanation":"住下去 = ở tiếp; 房子 (HSK2 Bài 14)."},{"context":"“Năm nay tôi tăng hơn mười cân, không thể béo thêm nữa.”","pre":"我今年胖了十多斤，不能再","blank":"胖下去","post":"了。","options":["胖下去","下去胖","胖上去"],"answer":0,"explanation":"Tính từ + 下去: trạng thái tiếp tục."},{"context":"“Cô ấy đọc xong câu thứ nhất rồi, phần sau bạn đọc tiếp đi.”","pre":"她读完了第一个问题，后面的你","blank":"读下去","post":"。","options":["读下去","读下来","下去读"],"answer":0,"explanation":"V + 下去 = làm tiếp phần còn lại."},{"context":"“Nếu cứ nóng thêm nữa thì không ra ngoài được.”","pre":"这几天太热了，如果再","blank":"热下去","post":"就不能出门了。","options":["热下去","热上去","下去热"],"answer":0,"explanation":"再 + Adj + 下去; 出门 (HSK2 Bài 15)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我想一直学汉语下去。","isCorrect":false,"correctVersion":"汉语我想一直学下去。","explanation":"下去 đứng ngay sau động từ, tân ngữ đưa lên trước."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你说得很好，说下去吧，大家都在听。","isCorrect":true,"explanation":"V + 下去 = nói tiếp — đúng; 在 + V (HSK1 Bài 11)."},{"type":"sort","context":"Sắp xếp: “Tôi không thể béo thêm nữa.”","words":["我","不能","再","胖","下去","了","。"],"answer":"我不能再胖下去了。","explanation":"不能再 + Adj + 下去了."},{"type":"sort","context":"Sắp xếp: “Phần sau bạn đọc tiếp đi.”","words":["后面","的","你","读","下去","。"],"answer":"后面的你读下去。","explanation":"V + 下去."},{"type":"sort","context":"Sắp xếp: “Cuốn sách này hay quá, tôi muốn đọc tiếp.”","words":["这本书","太","有意思","了","，","我","想","一直","看","下去","。"],"answer":"这本书太有意思了，我想一直看下去。","explanation":"一直 + V + 下去."},{"type":"sort","context":"Sắp xếp: “Bạn nói tiếp đi, tôi đang nghe.”","words":["你","说","下去","，","我","在","听","。"],"answer":"你说下去，我在听。","explanation":"说下去 = nói tiếp."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 下去.","promptLang":"vi","prompt":"Tiếng Trung rất thú vị, tôi muốn tiếp tục học.","answer":"汉语很有意思，我想一直学下去。","answerPy":"Hànyǔ hěn yǒu yìsi, wǒ xiǎng yìzhí xué xiàqu.","explanation":"学下去 — tân ngữ 汉语 đã đứng đầu câu."}]},{"point":"Từ li hợp (2) — bổ ngữ chen giữa hai phần","items":[{"context":"Sách: hoàn thành câu “……，我要和朋友去旅游。” (考试)","pre":"","blank":"考完试以后","post":"，我要和朋友去旅游。","options":["考完试以后","考试完以后","考以后完试"],"answer":0,"explanation":"完 chen giữa 考 và 试; 旅游 (HSK2 Bài 1)."},{"context":"Sách: hoàn thành câu “学校……，大家都很高兴。” (放假)","pre":"学校","blank":"放了一个星期假","post":"，大家都很高兴。","options":["放了一个星期假","放假了一个星期","一个星期放假了"],"answer":0,"explanation":"了 + thời lượng chen giữa 放 và 假."},{"context":"Sách: hoàn thành câu “天气太热了，我想……，再去吃饭。” (洗澡)","pre":"天气太热了，我想","blank":"先洗个澡","post":"，再去吃饭。","options":["先洗个澡","先洗澡个","个先洗澡"],"answer":0,"explanation":"个 chen giữa: 洗个澡; 先……再……."},{"context":"“Hôm qua tôi bơi một tiếng.”","pre":"昨天我","blank":"游了一个小时泳","post":"。","options":["游了一个小时泳","游泳了一个小时","一个小时游泳了"],"answer":0,"explanation":"游 + 了 + thời lượng + 泳."},{"context":"“Mình về nhà ngủ một giấc trước đã.”","pre":"我先回去","blank":"睡一觉","post":"。","options":["睡一觉","睡觉一","一睡觉"],"answer":0,"explanation":"一 (động lượng) chen giữa 睡 và 觉."},{"context":"“Tháng sau Tiểu Trương kết hôn với bạn gái.”","pre":"小张下个月","blank":"跟他女朋友结婚","post":"。","options":["跟他女朋友结婚","结婚他女朋友","结婚跟他女朋友"],"answer":0,"explanation":"跟 + người + 结婚; 跟 (HSK2 Bài 5)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我帮忙你吧。","isCorrect":false,"correctVersion":"我帮你吧。","explanation":"帮忙 là từ li hợp, không mang tân ngữ; dùng 帮 + người hoặc 帮你的忙 (帮忙 – HSK2 Bài 1)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"今年夏天只下了两次雨。","isCorrect":true,"explanation":"了 + 两次 chen giữa 下 và 雨 — đúng."},{"type":"sort","context":"Sắp xếp: “Chiều nào tôi cũng đến chạy bộ một tiếng.”","words":["我","每天","下午","都","来","跑","一个小时","步","。"],"answer":"我每天下午都来跑一个小时步。","explanation":"跑 + thời lượng + 步."},{"type":"sort","context":"Sắp xếp: “Mùa hè năm nay chỉ mưa hai lần.”","words":["今年","夏天","只","下","了","两次","雨","。"],"answer":"今年夏天只下了两次雨。","explanation":"下了两次雨."},{"type":"sort","context":"Sắp xếp: “Tôi đã nằm viện ba ngày.”","words":["我","住","了","三天","院","。"],"answer":"我住了三天院。","explanation":"住了三天院."},{"type":"sort","context":"Sắp xếp: “Hôm qua chúng tôi thi hai tiếng.”","words":["昨天","我们","考","了","两个小时","试","。"],"answer":"昨天我们考了两个小时试。","explanation":"考了两个小时试; 考试 (HSK2 Bài 10)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng từ li hợp 睡觉.","promptLang":"vi","prompt":"Tôi đã ngủ một giấc, giờ đỡ nhiều rồi.","answer":"我睡了一觉，现在好多了。","answerPy":"Wǒ shuìle yí jiào, xiànzài hǎo duō le.","explanation":"了 + 一 chen giữa 睡 và 觉."}]},{"point":"Bổ ngữ thời lượng (2) — thời gian tính từ khi hành động kết thúc","items":[{"context":"Sách: hoàn thành hội thoại “你来中国多长时间了？”","pre":"你来中国多长时间了？——我","blank":"来中国半年了","post":"。","options":["来中国半年了","半年来中国了","来半年中国了"],"answer":0,"explanation":"Động từ không duy trì 来 + tân ngữ + thời lượng + 了."},{"context":"Sách: hoàn thành hội thoại “听说你们已经结婚了？”","pre":"我们是前年结的，已经","blank":"结婚两年了","post":"。","options":["结婚两年了","两年结婚了","结两年婚了"],"answer":0,"explanation":"结婚 không duy trì → thời lượng đặt sau cả từ: 结婚两年了."},{"context":"Sách: hoàn thành hội thoại “那次去上海玩得开心极了。”","pre":"是啊！虽然","blank":"已经过去三年了","post":"，但是我也常想起那次旅游。","options":["已经过去三年了","三年以前过去了","已经过去三年以前"],"answer":0,"explanation":"已经过去 + thời lượng + 了; 虽然……但是…… (HSK2 Bài 8)."},{"context":"“Cô ấy về nhà được hai tháng rồi.”","pre":"她","blank":"回家两个月了","post":"。","options":["回家两个月了","两个月回家了","回两个月家了"],"answer":0,"explanation":"V + O + thời lượng + 了."},{"context":"“Khai giảng đã được hơn ba tuần rồi.”","pre":"","blank":"开学已经三个多星期了","post":"。","options":["开学已经三个多星期了","已经三个多星期开学了","开三个多星期学了"],"answer":0,"explanation":"开学 (HSK2 Bài 10) + 已经 + thời lượng + 了."},{"context":"“Anh ấy đến Bắc Kinh được một năm rồi.”","pre":"他","blank":"来北京一年了","post":"。","options":["来北京一年了","一年来北京了","来一年北京了"],"answer":0,"explanation":"V + nơi chốn + thời lượng + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他到了北京一个星期。","isCorrect":false,"correctVersion":"他到北京一个星期了。","explanation":"到 là động từ không duy trì → thời lượng đặt sau tân ngữ và 了 ở cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"开学已经三个多星期了。","isCorrect":true,"explanation":"开学 + 已经 + thời lượng + 了 — đúng."},{"type":"sort","context":"Sắp xếp: “Cô ấy về nhà được hai tháng rồi.”","words":["她","回","家","两个月","了","。"],"answer":"她回家两个月了。","explanation":"V + O + thời lượng + 了."},{"type":"sort","context":"Sắp xếp: “Lần trước tôi đến bệnh viện đã cách đây gần hai năm rồi.”","words":["我","上次","来","医院","已经","过去","差不多","两年","了","。"],"answer":"我上次来医院已经过去差不多两年了。","explanation":"已经过去 + 差不多两年 + 了."},{"type":"sort","context":"Sắp xếp: “Khai giảng đã được hơn ba tuần rồi.”","words":["开学","已经","三个多","星期","了","。"],"answer":"开学已经三个多星期了。","explanation":"开学已经……了."},{"type":"sort","context":"Sắp xếp: “Anh trai tôi kết hôn được ba năm rồi.”","words":["我","哥哥","结婚","已经","三年","了","。"],"answer":"我哥哥结婚已经三年了。","explanation":"结婚 + 已经 + 三年 + 了."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ thời lượng.","promptLang":"vi","prompt":"Tôi đến Trung Quốc được một năm rồi.","answer":"我来中国一年了。","answerPy":"Wǒ lái Zhōngguó yì nián le.","explanation":"来 + 中国 + 一年 + 了."}]},{"point":"Cấu trúc 「……以前 / 以后 / 前 / 后」 — trước / sau khi…","items":[{"context":"Sách: hoàn thành câu “……，别忘了换一下衣服。”","pre":"","blank":"运动以后","post":"，别忘了换一下衣服。","options":["运动以后","以后运动","运动的以后"],"answer":0,"explanation":"Sự việc + 以后; 运动 (HSK2 Bài 7); 换 (ôn HSK3 Bài 3)."},{"context":"Sách: hoàn thành câu “……，请大家检查自己的行李。”","pre":"","blank":"下飞机以前","post":"，请大家检查自己的行李。","options":["下飞机以前","以前下飞机","下以前飞机"],"answer":0,"explanation":"Sự việc + 以前; 行李 (ôn HSK3 Bài 1)."},{"context":"Sách: hoàn thành câu “……，好好问一下医生这些药怎么吃。”","pre":"","blank":"出院以前","post":"，好好问一下医生这些药怎么吃。","options":["出院以前","以前出院","出以前院"],"answer":0,"explanation":"出院以前 — trước khi ra viện."},{"context":"“Loại thuốc này mỗi ngày uống một lần trước khi ngủ.”","pre":"这种药需要每天","blank":"睡前","post":"吃一次。","options":["睡前","前睡","以前睡"],"answer":0,"explanation":"睡前 = 睡觉以前 (dạng ngắn)."},{"context":"“Chúng tôi quyết định tan làm xong cùng đi xem phim.”","pre":"我们决定","blank":"下班后","post":"一起去看个电影。","options":["下班后","后下班","下后班"],"answer":0,"explanation":"Sự việc + 后."},{"context":"“Thi xong, chúng mình cùng đi du lịch nhé.”","pre":"","blank":"考完试以后","post":"，咱们一起去旅游吧。","options":["考完试以后","以后考完试","考试完以后"],"answer":0,"explanation":"Sự việc + 以后; 完 chen giữa từ li hợp 考试; 咱们 (ôn HSK3 Bài 3)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"以后吃饭，我们去走走吧。","isCorrect":false,"correctVersion":"吃饭以后，我们去走走吧。","explanation":"……以后 đặt sau sự việc."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"考完试以后，咱们一起去旅游吧。","isCorrect":true,"explanation":"Sự việc + 以后 đứng đầu câu — đúng."},{"type":"sort","context":"Sắp xếp: “Loại thuốc này mỗi ngày cần uống một lần trước khi ngủ.”","words":["这种","药","需要","每天","睡前","吃","一次","。"],"answer":"这种药需要每天睡前吃一次。","explanation":"睡前 đứng trước động từ 吃."},{"type":"sort","context":"Sắp xếp: “Tan làm xong chúng ta cùng đi xem phim nhé.”","words":["下班","后","我们","一起","去","看","电影","吧","。"],"answer":"下班后我们一起去看电影吧。","explanation":"下班后 đứng đầu câu."},{"type":"sort","context":"Sắp xếp: “Trước khi ra viện, bác sĩ kê cho tôi vài loại thuốc.”","words":["出院","前","，","医生","给","我","开","了","几种","药","。"],"answer":"出院前，医生给我开了几种药。","explanation":"出院前 + mệnh đề chính."},{"type":"sort","context":"Sắp xếp: “Ba ngày trước tôi bị cảm.”","words":["三天","前","我","感冒","了","。"],"answer":"三天前我感冒了。","explanation":"Thời gian + 前 = … trước."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng ……以前.","promptLang":"vi","prompt":"Trước khi đi ngủ đừng xem điện thoại.","answer":"睡觉以前别看手机。","answerPy":"Shuìjiào yǐqián bié kàn shǒujī.","explanation":"Sự việc + 以前; 别 (HSK2 Bài 2)."}]}],"/lessons/hsk3v3-bai-9.html":[{"point":"Câu ghép chỉ mục đích 「为了……，……」 — để …, (thì) …","items":[{"context":"Sách: hoàn thành câu “……，我们决定搬家。”","pre":"","blank":"为了离公司近一点儿","post":"，我们决定搬家。","options":["为了离公司近一点儿","所以离公司近一点儿","离公司近一点儿为了"],"answer":0,"explanation":"为了 + mục đích đứng đầu câu; 决定 = quyết định; 搬家 (ôn HSK3 Bài 3); 离 (HSK2 Bài 9)."},{"context":"Sách: hoàn thành câu “……，她每天都去锻炼身体。”","pre":"","blank":"为了身体好","post":"，她每天都去锻炼身体。","options":["为了身体好","所以身体好","身体好为了"],"answer":0,"explanation":"为了 + mục đích (sức khoẻ tốt); 锻炼身体 (ôn HSK3 Bài 5)."},{"context":"Sách: hoàn thành câu “……，他们打算坐高铁去上海。”","pre":"","blank":"为了早点儿到上海","post":"，他们打算坐高铁去上海。","options":["为了早点儿到上海","为了早点儿到上海了","早点儿到上海为了"],"answer":0,"explanation":"为了 đứng đầu câu, mục đích chưa xảy ra nên không thêm 了; 高铁 = tàu cao tốc."},{"context":"“Nghe nói để chuẩn bị cho đại hội thể thao, mấy bạn nam các anh ngày nào cũng tập bóng.”","pre":"听说","blank":"为了","post":"准备运动会，你们几个男生每天都练球。","options":["为了","因为","所以"],"answer":0,"explanation":"准备运动会 là mục đích → 为了."},{"context":"“Mọi người chơi cầu chỉ là để rèn luyện sức khoẻ.”","pre":"大家打球只","blank":"是为了","post":"锻炼身体。","options":["是为了","为了是","是因为"],"answer":0,"explanation":"Mục đích ở vế sau: (只)是为了 + mục đích."},{"context":"Sách (Bài tập tổng hợp): “Để đạt thành tích tốt, các vận động viên mỗi ngày phải tập hơn mười tiếng.”","pre":"运动员们","blank":"为了得到好成绩","post":"，每天要练十多个小时。","options":["为了得到好成绩","因为得到好成绩","得到好成绩为了"],"answer":0,"explanation":"为了 + 得到 + 好成绩 (từ mới bài này)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"为了锻炼身体，所以我每天都去跑步。","isCorrect":false,"correctVersion":"为了锻炼身体，我每天都去跑步。","explanation":"为了 không đi với 所以."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"为了参加网球比赛，她最近一直在练习。","isCorrect":true,"explanation":"为了 + mục đích, vế sau là hành động — đúng; 一直 (ôn HSK3 Bài 4)."},{"type":"sort","context":"Sắp xếp: “Để rèn luyện sức khoẻ, sáng nào tôi cũng đi chạy bộ.”","words":["为了","锻炼","身体","，","我","每天","早上","都","去","跑步","。"],"answer":"为了锻炼身体，我每天早上都去跑步。","explanation":"为了 + mục đích，+ hành động; 跑步 (HSK2 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Mọi người chơi cầu chỉ là để rèn luyện sức khoẻ.”","words":["大家","打球","只是","为了","锻炼","身体","。"],"answer":"大家打球只是为了锻炼身体。","explanation":"只是为了 — mục đích ở vế sau."},{"type":"sort","context":"Sắp xếp: “Để học tốt tiếng Trung, ngày nào cô ấy cũng xem phim Trung Quốc.”","words":["为了","学好","汉语","，","她","每天","都","看","中国","电影","。"],"answer":"为了学好汉语，她每天都看中国电影。","explanation":"学好 — bổ ngữ kết quả (HSK2 Bài 3)."},{"type":"sort","context":"Sắp xếp: “Tôi đến Bắc Kinh là để thăm ông bà.”","words":["我","来","北京","是","为了","看","爷爷","奶奶","。"],"answer":"我来北京是为了看爷爷奶奶。","explanation":"是为了 + mục đích; 爷爷、奶奶 (HSK2 Bài 5)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 为了.","promptLang":"vi","prompt":"Để chuẩn bị cho đại hội thể thao, ngày nào chúng tôi cũng luyện tập.","answer":"为了准备运动会，我们每天都练习。","answerPy":"Wèile zhǔnbèi yùndònghuì, wǒmen měi tiān dōu liànxí.","explanation":"为了 + mục đích; 准备 (HSK2 Bài 5); không thêm 所以."}]},{"point":"Bổ ngữ khả năng (可能补语) — V + 得 / 不 + bổ ngữ","items":[{"context":"Sách: hoàn thành hội thoại “我和你妈妈在门口等着你呢。——机场人太多了，我……。”","pre":"机场人太多了，我","blank":"找不到你们","post":"。","options":["找不到你们","不找到你们","没找得到你们"],"answer":0,"explanation":"找不到 = tìm không thấy (phủ định khả năng); 着 (HSK2 Bài 11)."},{"context":"Sách: hoàn thành hội thoại “喂？喂？我说话你……？——没问题，我听得见。”","pre":"喂？喂？我说话你","blank":"听得见听不见","post":"？","options":["听得见听不见","听得见不听得见","不听得见"],"answer":0,"explanation":"Nghi vấn: V得C + V不C; trả lời 听得见."},{"context":"Sách: hoàn thành hội thoại “咱们还没做今天的作业呢，半个小时……？”","pre":"咱们还没做今天的作业呢，半个小时","blank":"做得完吗","post":"？","options":["做得完吗","做完得吗","不做得完吗"],"answer":0,"explanation":"V得C + 吗; 完 — bổ ngữ kết quả (HSK2 Bài 3); 作业 = bài tập về nhà."},{"context":"Sách: hoàn thành hội thoại “——没问题，……，今天的作业一点儿也不多。”","pre":"没问题，","blank":"做得完","post":"，今天的作业一点儿也不多。","options":["做得完","做不完","没做完"],"answer":0,"explanation":"Khẳng định V得C; 一点儿也不 (ôn HSK3 Bài 4)."},{"context":"“Chơi không tốt cũng không sao.”","pre":"","blank":"打不好","post":"没关系。","options":["打不好","不打好","没打得好"],"answer":0,"explanation":"Phủ định khả năng: V + 不 + 好."},{"context":"“Nếu lúc nào cũng không đỡ được cầu thì ngại lắm.”","pre":"如果总是","blank":"接不住","post":"球，就太不好意思了。","options":["接不住","不接住","接得不住"],"answer":0,"explanation":"接住 = đỡ được; phủ định khả năng 接不住; 总是 (ôn HSK3 Bài 5)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这本书我不看得懂。","isCorrect":false,"correctVersion":"这本书我看不懂。","explanation":"不 đứng giữa V và bổ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你只有一个星期的时间，学得会游泳吗？","isCorrect":true,"explanation":"V得C + 吗 — câu của sách; 游泳 (HSK2 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Hôm nay sao thế? Sút mãi không vào!”","words":["今天","怎么回事","？","总是","踢","不","进去","！"],"answer":"今天怎么回事？总是踢不进去！","explanation":"V + 不 + bổ ngữ xu hướng 进去."},{"type":"sort","context":"Sắp xếp: “Cuốn sách này bạn đọc có hiểu không?”","words":["这","本","书","你","看","得","懂","看","不","懂","？"],"answer":"这本书你看得懂看不懂？","explanation":"V得C + V不C."},{"type":"sort","context":"Sắp xếp: “Bạn ngồi xa như vậy, có nhìn thấy không?”","words":["你","坐","得","这么","远","，","看","得","见","吗","？"],"answer":"你坐得这么远，看得见吗？","explanation":"坐得这么远 — bổ ngữ trạng thái (HSK2 Bài 7); 看得见吗 — bổ ngữ khả năng."},{"type":"sort","context":"Sắp xếp: “Nhiều món như vậy, tôi ăn không hết.”","words":["这么","多","菜","，","我","吃","不","完","。"],"answer":"这么多菜，我吃不完。","explanation":"吃不完 = ăn không hết; 这么 (HSK2 Bài 3)."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng bổ ngữ khả năng.","promptLang":"vi","prompt":"Bạn nói nhanh quá, tôi nghe không hiểu.","answer":"你说得太快了，我听不懂。","answerPy":"Nǐ shuō de tài kuài le, wǒ tīng bu dǒng.","explanation":"听不懂 (✗ 不能听懂); 说得太快 — bổ ngữ trạng thái (HSK2 Bài 7)."}]},{"point":"Cấu trúc cố định 「越A越B」 — càng … càng …","items":[{"context":"Sách: hoàn thành câu “我们越说……。”","pre":"我们越说","blank":"越高兴","post":"。","options":["越高兴","很高兴","越很高兴"],"answer":0,"explanation":"越A越B; sau 越 không thêm 很."},{"context":"Sách: hoàn thành câu “这个电影越看……。”","pre":"这个电影越看","blank":"越有意思","post":"。","options":["越有意思","越很有意思","有意思越"],"answer":0,"explanation":"有意思 (HSK2 Bài 8)."},{"context":"Sách: hoàn thành câu “她……，我越担心。”","pre":"她","blank":"越不说话","post":"，我越担心。","options":["越不说话","不说话越","越很不说话"],"answer":0,"explanation":"越 + 不 + V; 担心 = lo lắng; 说话 (HSK1 Bài 14)."},{"context":"“Trận bóng đá hôm nay tôi càng xem càng sốt ruột.”","pre":"今天的足球比赛我","blank":"越看越着急","post":"。","options":["越看越着急","越看着急","看越越着急"],"answer":0,"explanation":"着急 zháojí (ôn HSK3 Bài 1)."},{"context":"“Mẹ càng nói, nó càng không vui.”","pre":"","blank":"妈妈越说","post":"，他越不高兴。","options":["妈妈越说","越妈妈说","妈妈说越"],"answer":0,"explanation":"越 đứng sau chủ ngữ."},{"context":"“Tôi muốn quen bạn bè Trung Quốc, càng nhiều càng tốt.”","pre":"我想认识中国朋友，","blank":"越多越好","post":"。","options":["越多越好","越很多越好","多越好"],"answer":0,"explanation":"越 + tính từ + 越 + tính từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"雨越下越大，我们别出去了。","isCorrect":true,"explanation":"越下越大 — đúng; 别……了 (HSK2 Bài 2)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"越妈妈说，他越不高兴。","isCorrect":false,"correctVersion":"妈妈越说，他越不高兴。","explanation":"越 đứng sau chủ ngữ."},{"type":"sort","context":"Sắp xếp: “Mưa càng lúc càng to.”","words":["雨","越","下","越","大","。"],"answer":"雨越下越大。","explanation":"越 + V + 越 + Adj."},{"type":"sort","context":"Sắp xếp: “Tiếng Trung càng học càng thú vị.”","words":["汉语","越","学","越","有意思","。"],"answer":"汉语越学越有意思。","explanation":"有意思 (HSK2 Bài 8)."},{"type":"sort","context":"Sắp xếp: “Anh ấy càng chạy càng nhanh.”","words":["他","越","跑","越","快","。"],"answer":"他越跑越快。","explanation":"跑 (HSK2 Bài 7)."},{"type":"sort","context":"Sắp xếp: “Chiếc áo này tôi càng nhìn càng thích.”","words":["这","件","衣服","我","越","看","越","喜欢","。"],"answer":"这件衣服我越看越喜欢。","explanation":"Tân ngữ đưa lên đầu câu làm chủ đề; 越看越喜欢."},{"type":"translate","context":"Dịch sang tiếng Trung, dùng 越A越B.","promptLang":"vi","prompt":"Bóng rổ tôi càng chơi càng thích.","answer":"篮球我越打越喜欢。","answerPy":"Lánqiú wǒ yuè dǎ yuè xǐhuan.","explanation":"越 + V + 越 + 喜欢; 打篮球 (HSK2 Bài 7)."}]}]});
